import * as React from "react"
import type { RowData } from "@tanstack/react-table"
import { useSortable } from "@dnd-kit/sortable"
import { CSS } from "@dnd-kit/utilities"

import { TableRow } from "@/components/ui/table"
import { cn } from "@/lib/utils"

import { mergeProps } from "../../../helpers/slot-props"

import { BODY_ROW_CLASS } from "../../../core/constants"
import { RowDragContext } from "../../../injected-columns/injected-columns"
import type { DataTableRow } from "../../../core/table-types"
import { DndKeyContext, useDndId } from "../../../core/dnd-scope"

/**
 * Body row. `useSortable` is always called (disabled when row ordering is off).
 * Exposes its drag-handle props through {@link RowDragContext} so the drag
 * column's handle can activate it. Applies the selected-row accent.
 */
export function DataTableBodyRow<TData extends RowData>({
  row,
  draggable,
  children,
  className,
  onClick,
  onDoubleClick,
  ...rest
}: Omit<React.ComponentProps<"tr">, "children"> & {
  row: DataTableRow<TData>
  draggable: boolean
  children: React.ReactNode
  className?: string
  onClick?: React.MouseEventHandler<HTMLTableRowElement>
  onDoubleClick?: React.MouseEventHandler<HTMLTableRowElement>
}) {
  const tableKey = React.useContext(DndKeyContext)
  const dndId = useDndId()
  const {
    attributes,
    listeners,
    setNodeRef,
    setActivatorNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({
    id: dndId(row.id),
    disabled: !draggable,
    data: { type: "row", tableKey, rowId: row.id },
  })

  // Inside a DataTableDndProvider a floating preview follows the pointer, so
  // the dragged row stays in place, dimmed.
  const previewed = isDragging && tableKey != null
  const style: React.CSSProperties = {
    transform: previewed ? undefined : CSS.Transform.toString(transform),
    transition,
    position: isDragging ? "relative" : undefined,
    zIndex: isDragging ? 1 : undefined,
    opacity: previewed ? 0.5 : undefined,
  }

  const dragProps = React.useMemo(
    () => ({
      attributes: attributes as unknown as Record<string, unknown>,
      listeners: listeners as Record<string, unknown> | undefined,
      setActivatorNodeRef,
    }),
    [attributes, listeners, setActivatorNodeRef]
  )

  return (
    <RowDragContext.Provider value={dragProps}>
      <TableRow
        {...mergeProps(
          {
            ref: setNodeRef,
            style,
            "data-state": row.getIsSelected() ? "selected" : undefined,
            "data-dragging": isDragging || undefined,
            className: cn(
              BODY_ROW_CLASS,
              (onClick || onDoubleClick) && "cursor-pointer"
            ),
          } as React.ComponentProps<"tr">,
          { ...rest, onClick, onDoubleClick, className }
        )}
      >
        {children}
      </TableRow>
    </RowDragContext.Provider>
  )
}

"use client"

import type { RowData } from "@tanstack/react-table"
import type * as React from "react"

import { cn } from "@/lib/utils"

import type { DataTableInstance } from "../../../core/types"
import type { DataTableHeader } from "../../../core/table-types"
import { dt } from "../../../core/internal"

/** Drag handle to grab the resize edge of a column header. */
export function ColumnResizeHandle<TData extends RowData, TValue>({
  header,
  table,
}: {
  header: DataTableHeader<TData, TValue>
  table: DataTableInstance<TData>
}) {
  if (!header.column.getCanResize()) return null
  const { column } = header
  const size = column.getSize()
  const { minSize, maxSize } = column.columnDef
  const min = typeof minSize === "number" ? minSize : 0
  const max =
    typeof maxSize === "number" && maxSize < Number.MAX_SAFE_INTEGER
      ? maxSize
      : undefined

  const resizeTo = (next: number) => {
    const clamped = Math.round(Math.min(max ?? Infinity, Math.max(min, next)))
    table.setColumnSizing((prev) => ({ ...prev, [column.id]: clamped }))
  }

  // Arrow keys resize by 10px (Shift: 50px), toward the column's far edge on
  // the right in left-to-right tables and mirrored right to left; Home / End
  // jump to the limits; Enter fits the column to its content.
  const onKeyDown = (event: React.KeyboardEvent<HTMLSpanElement>) => {
    const step = event.shiftKey ? 50 : 10
    const grow = dt(table).direction === "rtl" ? "ArrowLeft" : "ArrowRight"
    const shrink = grow === "ArrowRight" ? "ArrowLeft" : "ArrowRight"
    if (event.key === grow) resizeTo(size + step)
    else if (event.key === shrink) resizeTo(size - step)
    else if (event.key === "Home") resizeTo(min)
    else if (event.key === "End" && max != null) resizeTo(max)
    else if (event.key === "Enter") {
      if (dt(table).enableColumnAutosize) dt(table).autoSizeColumn(column.id)
      else column.resetSize()
    } else return
    event.preventDefault()
    event.stopPropagation()
  }

  return (
    <span
      role="separator"
      tabIndex={0}
      aria-orientation="vertical"
      aria-valuenow={Math.round(size)}
      aria-valuemin={min}
      aria-valuemax={max}
      onKeyDown={onKeyDown}
      aria-label={dt(table).localization.resizeColumn}
      onMouseDown={header.getResizeHandler()}
      onTouchStart={header.getResizeHandler()}
      onDoubleClick={() =>
        dt(table).enableColumnAutosize
          ? dt(table).autoSizeColumn(header.column.id)
          : header.column.resetSize()
      }
      className={cn(
        // Hidden at rest; a faint divider appears while the cursor is anywhere
        // in the header row (group/th), strengthens to primary on direct hover,
        // and stays primary while actively resizing.
        "absolute end-0 top-0 z-10 h-full w-1 cursor-col-resize touch-none bg-transparent transition-colors outline-none select-none group-hover/th:bg-border/60 hover:bg-primary focus-visible:bg-primary focus-visible:ring-2 focus-visible:ring-ring/40",
        // Touch devices can't hover, so the grip would be invisible: on a coarse
        // pointer reveal it at rest and widen the hit area for a finger.
        "pointer-coarse:w-1.5",
        header.column.getIsResizing()
          ? "bg-primary"
          : "pointer-coarse:bg-border/60"
      )}
    />
  )
}

"use client"

import * as React from "react"
import type { RowData } from "@tanstack/react-table"
import { useSortable } from "@dnd-kit/sortable"
import { CSS } from "@dnd-kit/utilities"

import { Button } from "@/components/ui/button"
import { TableHead } from "@/components/ui/table"
import { cn } from "@/lib/utils"

import { getSlotProps, mergeProps } from "../../../helpers/slot-props"

import {
  getColumnPinningClass,
  getColumnPinningStyle,
} from "../../../utils/column-styles"
import type { IconComponent } from "../../../core/icons"
import type { DataTableInstance } from "../../../core/types"
import { getPinSide } from "../../../helpers/column-pinning"
import { ColumnResizeHandle } from "./column-resize-handle"
import type {
  DataTableColumn,
  DataTableHeader,
} from "../../../core/table-types"
import { setColumnDragVars } from "../../../utils/column-styles"
import { DndKeyContext, useDndId } from "../../../core/dnd-scope"

/** dnd-kit activator props for the current column's drag handle. */
export interface ColumnDragHandleProps {
  attributes: Record<string, unknown>
  listeners: Record<string, unknown> | undefined
  setActivatorNodeRef: (el: HTMLElement | null) => void
}

/** Provided by the sortable header cell, consumed by {@link ColumnDragHandle}
 *  so the grip can live inside the column header (beside the actions menu)
 *  while the dnd-kit wiring stays on the cell. Null when the column isn't
 *  draggable. */
export const ColumnDragContext =
  React.createContext<ColumnDragHandleProps | null>(null)

/**
 * Header cell. `useSortable` is always called (disabled when ordering is off or
 * for display columns) to keep hook order stable. Applies pinning + width
 * styles, an optional drag grip, and the resize handle.
 */
export function DataTableHeadCell<TData extends RowData, TValue>({
  header,
  table,
  draggable,
  resizable,
  widthStyle,
  padding,
  colSpan = header.colSpan,
  children,
}: {
  header: DataTableHeader<TData, TValue>
  table: DataTableInstance<TData>
  draggable: boolean
  resizable: boolean
  widthStyle: React.CSSProperties
  padding: string
  /** Overrides `header.colSpan` (column virtualization renders part of a group). */
  colSpan?: number
  children: React.ReactNode
}) {
  const column = header.column
  const tableKey = React.useContext(DndKeyContext)
  const dndId = useDndId()
  const {
    attributes,
    listeners,
    setNodeRef,
    setActivatorNodeRef,
    transform,
    transition: sortTransition,
    isDragging,
  } = useSortable({
    id: dndId(column.id),
    disabled: !draggable,
    data: { type: "column", tableKey, columnId: column.id },
  })

  // While a column is dragged, its header follows the pointer and the others
  // slide aside; the same offsets go to CSS variables on the scroll surface so
  // the body, filter and footer cells move with their headers (no row
  // re-renders). Reduced motion: no slide animation.
  const offsetX = transform?.x ?? 0
  // The surface is found from this cell, not from `refs.tableContainerRef`,
  // which is briefly detached while the table commits a re-render.
  const cellRef = React.useRef<HTMLTableCellElement | null>(null)
  const setCellRef = React.useCallback(
    (node: HTMLTableCellElement | null) => {
      cellRef.current = node
      setNodeRef(node)
    },
    [setNodeRef]
  )
  const surfaceOf = () =>
    cellRef.current?.closest<HTMLElement>('[data-slot="data-table-surface"]')
  const written = React.useRef("0:false")
  React.useLayoutEffect(() => {
    const surface = surfaceOf()
    const key = `${offsetX}:${isDragging}`
    if (!surface || written.current === key) return
    written.current = key
    setColumnDragVars(
      surface,
      column.id,
      offsetX,
      isDragging,
      !window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
    )
  })
  React.useEffect(() => {
    const surface = surfaceOf()
    return () => {
      if (surface) setColumnDragVars(surface, column.id, 0, false, false)
    }
    // Clean up once, when the column's header goes away.
  }, [column.id])

  const pinningStyle = getColumnPinningStyle(column)
  const style: React.CSSProperties = {
    ...widthStyle,
    ...pinningStyle,
    transform: CSS.Translate.toString(transform),
    // Animate width for programmatic changes (autosize, pinning) but not during
    // an active drag, where the easing makes the header lag behind the cursor;
    // the other headers slide aside with dnd-kit's own transition.
    transition: column.getIsResizing()
      ? undefined
      : ["width 0.15s ease", !isDragging && offsetX !== 0 && sortTransition]
          .filter(Boolean)
          .join(", "),
    opacity: isDragging ? 0.85 : undefined,
    // A pinned header keeps its pinning layer, above the headers under it.
    zIndex: isDragging ? 30 : pinningStyle.zIndex,
  }

  // Hand the drag-activator props to the header (via context) so the grip can
  // render next to the column-actions menu instead of crowding the left edge.
  const dragProps = React.useMemo<ColumnDragHandleProps>(
    () => ({
      attributes: attributes as unknown as Record<string, unknown>,
      listeners: listeners as Record<string, unknown> | undefined,
      setActivatorNodeRef,
    }),
    [attributes, listeners, setActivatorNodeRef]
  )

  return (
    <TableHead
      {...mergeProps(
        // The ref callback is handed to the cell, not read during render.
        // eslint-disable-next-line react-hooks/refs
        {
          ref: setCellRef,
          colSpan,
          style,
          "data-pinned": getPinSide(column) || undefined,
          "aria-sort": ariaSort(column.getIsSorted()),
          className: cn(
            "relative bg-card",
            padding,
            // Match the body: under fixed layout, keep long header labels from
            // bleeding past the (resizable) column edge.
            resizable && "overflow-hidden",
            getColumnPinningClass(column)
          ),
        } as React.ComponentProps<"th">,
        getSlotProps(
          table,
          "headCell",
          {
            header: header as DataTableHeader<TData, unknown>,
            column: column as DataTableColumn<TData, unknown>,
          },
          column.columnDef.meta?.slotProps?.headCell
        )
      )}
    >
      <ColumnDragContext.Provider value={draggable ? dragProps : null}>
        {children}
      </ColumnDragContext.Provider>
      {resizable && <ColumnResizeHandle header={header} table={table} />}
    </TableHead>
  )
}

/** Column reorder grip. Reads dnd-kit props from {@link ColumnDragContext} and
 *  renders nothing when the column isn't draggable. Lives inside the column
 *  header, just before the column-actions menu. */
export function ColumnDragHandle({
  label,
  Icon,
}: {
  label: string
  Icon: IconComponent
}) {
  const ctx = React.useContext(ColumnDragContext)
  if (!ctx) return null
  const { attributes, listeners, setActivatorNodeRef } = ctx
  return (
    <Button
      type="button"
      variant="ghost"
      size="icon"
      aria-label={label}
      ref={setActivatorNodeRef}
      // dnd-kit injects an aria-describedby id that can differ between the
      // server and client render; suppress that benign attribute mismatch.
      suppressHydrationWarning
      {...attributes}
      {...listeners}
      // touch-none: let dnd-kit's pointer sensor own the touch gesture
      // (otherwise the browser scrolls/selects text before a drag can start on
      // a phone). size-7 matches the actions menu for a finger-friendly target.
      className="size-7 shrink-0 cursor-grab touch-none text-muted-foreground opacity-70 transition-opacity group-hover/th:opacity-100 focus-visible:opacity-100 active:cursor-grabbing"
    >
      <Icon className="size-3.5" />
    </Button>
  )
}

function ariaSort(
  sorted: false | "asc" | "desc"
): React.AriaAttributes["aria-sort"] {
  if (sorted === "asc") return "ascending"
  if (sorted === "desc") return "descending"
  return "none"
}

import * as React from "react"

import { cn } from "@/lib/utils"

const MAX_HIGHLIGHT_LENGTH = 2000

function escapeRegExp(input: string): string {
  return input.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
}

/**
 * Wraps occurrences of `query` within `text` in a themeable `<mark>`. Work is
 * skipped when there's no query, the query is escaped, and very long strings
 * are left unhighlighted to avoid regex blowups on huge cells.
 */
export const Highlight = React.memo(function Highlight({
  text,
  query,
  className,
}: {
  text: string
  query?: string | null
  className?: string
}) {
  const trimmed = query?.trim()
  if (!trimmed || text.length === 0 || text.length > MAX_HIGHLIGHT_LENGTH) {
    return <>{text}</>
  }

  const parts = text.split(new RegExp(`(${escapeRegExp(trimmed)})`, "gi"))
  if (parts.length === 1) return <>{text}</>

  const needle = trimmed.toLowerCase()
  return (
    <>
      {parts.map((part, index) =>
        part.toLowerCase() === needle ? (
          <mark
            key={index}
            className={cn(
              "rounded-xs bg-highlight px-0.5 text-highlight-foreground",
              className
            )}
          >
            {part}
          </mark>
        ) : (
          <React.Fragment key={index}>{part}</React.Fragment>
        )
      )}
    </>
  )
})

"use client"

import * as React from "react"

import { GridSyncContext } from "../../hooks/use-grid-navigation"
import { useRowState } from "./row-state-hub"

const sameItems = (a: readonly unknown[], b: readonly unknown[]) =>
  a.length === b.length && a.every((value, i) => Object.is(value, b[i]))

interface MemoRowProps {
  /** Identifies the rendered row for its state subscription. */
  stateKey: string
  /** What places the row: the row object, its position. */
  rowKey: readonly unknown[]
  /** Reads the state only this row shows (selection, expansion, pinning,
   *  editing), live from the table. */
  selectRowState: () => readonly unknown[]
  /** Inputs every row reads (table state and options); one array shared by
   *  all rows of a render. */
  tableDeps: readonly unknown[]
  /** Renders the row with the current closure. */
  render: () => React.ReactNode
}

/**
 * A body row that re-renders on its own: when its placement or the
 * table-wide inputs change (the body passes new props), or when the state
 * only it shows changes (through the body's row state hub). Selecting a row or
 * typing in an inline editor re-renders that row and nothing else. `render`
 * is left out of the comparison: it is a fresh closure every time, and
 * everything it reads is covered above or read live.
 */
export const MemoRow = React.memo(
  function MemoRow({ stateKey, selectRowState, render }: MemoRowProps) {
    useRowState(stateKey, selectRowState)
    // Keyboard navigation fixes focus and the tab stop after rows render.
    const scheduleGridSync = React.useContext(GridSyncContext)
    React.useLayoutEffect(() => {
      scheduleGridSync?.()
    })
    return <>{render()}</>
  },
  (prev, next) =>
    sameItems(prev.rowKey, next.rowKey) &&
    sameItems(prev.tableDeps, next.tableDeps)
)

"use client"

import { flexRender, type RowData } from "@tanstack/react-table"
import * as React from "react"

import type { DataTableInstance } from "../../core/types"
import { SUBSTRING_MODES } from "../../fns/filter-fns"
import { getEffectiveMode } from "../../helpers/effective-filter-mode"
import { stopPropagation } from "../../helpers/stop-propagation"
import { DataTableBodyCellContent } from "../editing/data-table-edit-cell"
import { Highlight } from "./highlight"
import type { DataTableCell } from "../../core/table-types"
import { dt } from "../../core/internal"
import {
  DEFAULT_AGGREGATION_LABELS,
  type DataTableLocalization,
} from "../../core/localization"

/** Table state every cell reads, taken once per body render rather than per
 *  cell (reading the state costs a few microseconds, times every cell). */
export interface CellRenderState {
  isGrouping: boolean
  globalFilter: unknown
}

export function getCellRenderState<TData extends RowData>(
  table: DataTableInstance<TData>
): CellRenderState {
  const { grouping, globalFilter } = table.getState()
  return { isGrouping: grouping.length > 0, globalFilter }
}

/**
 * Resolves a body cell's content, handling grouped / aggregated / placeholder
 * cells and falling back to the highlight-aware value renderer.
 */
export function renderBodyCell<TData extends RowData>(
  cell: DataTableCell<TData, unknown>,
  table: DataTableInstance<TData>,
  enableHighlight: boolean,
  columnsWithCustomCell: ReadonlySet<string>,
  localization: DataTableInstance<TData>["dataTable"]["localization"],
  shared: CellRenderState = getCellRenderState(table)
): React.ReactNode {
  const { row, column } = cell
  const icons = dt(table).icons
  const meta = column.columnDef.meta

  // Grouped/aggregated/placeholder cells are a grouping concept. Tree data
  // (getSubRows) also marks parent rows' cells as "aggregated", which would
  // bypass normal cell rendering (e.g. the expand chevron). Only take these
  // branches when grouping is actually active.
  const { isGrouping } = shared

  if (isGrouping && cell.getIsGrouped()) {
    return (
      <button
        type="button"
        aria-label={localization.toggleRowExpanded}
        aria-expanded={row.getIsExpanded()}
        onClick={(event) => {
          stopPropagation(event)
          row.getToggleExpandedHandler()()
        }}
        onDoubleClick={stopPropagation}
        style={{ paddingInlineStart: `${row.depth * 1}rem` }}
        className="flex items-center gap-1.5 text-start outline-none focus-visible:ring-2 focus-visible:ring-ring/40"
      >
        {row.getIsExpanded() ? (
          <icons.expanded className="size-4 shrink-0 text-muted-foreground" />
        ) : (
          <icons.collapsed className="size-4 shrink-0 text-muted-foreground rtl:rotate-180" />
        )}
        <span className="font-medium">
          {meta?.renderGroupedCell
            ? meta.renderGroupedCell({ cell, row, column, table })
            : flexRender(column.columnDef.cell, {
                ...cell.getContext(),
                table,
              })}
        </span>
        <span className="text-xs text-muted-foreground">
          ({row.subRows.length})
        </span>
      </button>
    )
  }

  if (isGrouping && cell.getIsAggregated()) {
    if (meta?.renderAggregatedCell) {
      return meta.renderAggregatedCell({ cell, row, column, table })
    }
    return flexRender(
      column.columnDef.aggregatedCell ?? column.columnDef.cell,
      { ...cell.getContext(), table }
    )
  }

  if (isGrouping && cell.getIsPlaceholder()) {
    return meta?.renderPlaceholderCell
      ? meta.renderPlaceholderCell({ cell, row, column, table })
      : null
  }

  return (
    <DataTableBodyCellContent
      cell={cell}
      table={table}
      fallback={renderCellContent(
        cell,
        table,
        enableHighlight,
        columnsWithCustomCell,
        shared.globalFilter
      )}
    />
  )
}

/**
 * Renders a cell's value, auto-highlighting matched substrings for columns with
 * no custom cell renderer and an active string substring filter / global query.
 */
function renderCellContent<TData extends RowData>(
  cell: DataTableCell<TData, unknown>,
  table: DataTableInstance<TData>,
  enableHighlight: boolean,
  columnsWithCustomCell: ReadonlySet<string>,
  globalFilter: unknown
): React.ReactNode {
  const { column } = cell
  const value = cell.getValue()
  const canHighlight =
    enableHighlight &&
    column.columnDef.meta?.enableFilterMatchHighlighting !== false &&
    !columnsWithCustomCell.has(column.id) &&
    (typeof value === "string" || typeof value === "number")

  if (canHighlight) {
    const query = resolveHighlightQuery(cell, table, globalFilter)
    if (query) {
      return <Highlight text={String(value)} query={query} />
    }
  }

  return flexRender(column.columnDef.cell, { ...cell.getContext(), table })
}

/** The active highlight query for a cell: its column filter, else global search. */
function resolveHighlightQuery<TData extends RowData>(
  cell: DataTableCell<TData, unknown>,
  table: DataTableInstance<TData>,
  globalFilter: unknown
): string | null {
  const filterValue = cell.column.getFilterValue()
  if (
    typeof filterValue === "string" &&
    filterValue.length > 0 &&
    SUBSTRING_MODES.has(getEffectiveMode(cell.column, table))
  ) {
    return filterValue
  }
  if (
    typeof globalFilter === "string" &&
    globalFilter.length > 0 &&
    SUBSTRING_MODES.has(dt(table).globalFilterMode)
  ) {
    return globalFilter
  }
  return null
}

/**
 * The table's default `aggregatedCell`: several aggregations
 * (`aggregationFn: ["sum", "mean"]`) show each result with its label;
 * a single one shows its value, as TanStack's default does.
 */
export function DefaultAggregatedCell<TData extends RowData>({
  getValue,
  column,
  table,
}: {
  getValue: () => unknown
  column: { columnDef: { aggregationFn?: unknown } }
  table: unknown
}): React.ReactNode {
  const value = getValue()
  if (Array.isArray(column.columnDef.aggregationFn)) {
    return (
      <AggregationResults
        value={value}
        localization={dt(table as DataTableInstance<TData>).localization}
      />
    )
  }
  return (value as { toString?: () => string } | null)?.toString?.() ?? null
}

/** "Sum 4,000 · Mean 2,000": each aggregation's label and value. */
function AggregationResults({
  value,
  localization,
}: {
  value: unknown
  localization: DataTableLocalization
}) {
  if (value == null || typeof value !== "object")
    return <>{String(value ?? "")}</>
  const labels = {
    ...DEFAULT_AGGREGATION_LABELS,
    ...localization.aggregationFns,
  }
  const format = (result: unknown): string =>
    typeof result === "number"
      ? result.toLocaleString(localization.language)
      : Array.isArray(result)
        ? result.map(format).join(" – ")
        : String(result ?? "")
  return (
    <span className="inline-flex flex-wrap gap-x-3">
      {Object.entries(value).map(([name, result]) => (
        <span key={name}>
          <span className="text-muted-foreground">{labels[name] ?? name}</span>{" "}
          <span className="font-medium tabular-nums">{format(result)}</span>
        </span>
      ))}
    </span>
  )
}

