import type { RowData } from "@tanstack/react-table"

import { Button } from "@/components/ui/button"
import { TableCell, TableRow } from "@/components/ui/table"

import type { DataTableInstance } from "../../core/types"
import { useTableState } from "../../hooks/use-table-state"
import { getColumnLabel } from "../../helpers/column-label"
import { isColumnEditable } from "../../helpers/is-column-editable"
import { DataTableEditField } from "./data-table-edit-field"
import type { DataTableColumn } from "../../core/table-types"
import { dt } from "../../core/internal"
import { getSlotProps } from "../../helpers/slot-props"
import { getEditSelectOptions } from "../../helpers/edit-select-options"

/**
 * Inline create row for `createDisplayMode: "row"`. Renders an editor per
 * editable column bound to the shared `rowDraft`, with Save/Cancel in a
 * full-width action strip beneath it. Save commits via `onCreatingRowSave`.
 */
export function DataTableCreateRow<TData extends RowData>({
  table,
}: {
  table: DataTableInstance<TData>
}) {
  const {
    enableEditing,
    rowDraft,
    onCreatingRowSave,
    cancelEdit,
    cancelEditing,
    localization,
  } = dt(table)
  // The body does not re-render for the edit draft.
  useTableState(table, (state) => state.rowDraft)

  const leafColumns = table.getVisibleLeafColumns()
  const editableColumns = leafColumns.filter(
    (column) => enableEditing && isColumnEditable(column)
  )
  const hasErrors = editableColumns.some(
    (column) => column.columnDef.meta?.validate?.(rowDraft[column.id]) != null
  )

  const submit = () => {
    if (hasErrors) return
    onCreatingRowSave?.({ values: rowDraft, table, exit: cancelEdit })
  }

  return (
    <>
      <TableRow
        data-slot="data-table-create-row"
        className="bg-muted/30 align-top hover:bg-muted/30"
      >
        {leafColumns.map((column) => {
          const editable = enableEditing && isColumnEditable(column)
          return (
            <TableCell key={column.id} className="p-2 align-top">
              {editable ? <CreateField column={column} table={table} /> : null}
            </TableCell>
          )
        })}
      </TableRow>
      <TableRow className="border-b-2 bg-muted/30 hover:bg-muted/30">
        <TableCell colSpan={leafColumns.length} className="p-2">
          <div className="flex items-center justify-end gap-2">
            <Button variant="outline" size="sm" onClick={cancelEditing}>
              {localization.cancel}
            </Button>
            <Button size="sm" onClick={submit} disabled={hasErrors}>
              {localization.save}
            </Button>
          </div>
        </TableCell>
      </TableRow>
    </>
  )
}

/** One editor in the create row, bound to the shared row draft. */
function CreateField<TData extends RowData>({
  column,
  table,
}: {
  column: DataTableColumn<TData, unknown>
  table: DataTableInstance<TData>
}) {
  const cn = dt(table)
  const meta = column.columnDef.meta
  const value = cn.rowDraft[column.id]
  return (
    <DataTableEditField
      value={value}
      variant={meta?.editVariant}
      options={getEditSelectOptions(column, table)}
      error={meta?.validate?.(value)}
      ariaLabel={getColumnLabel(column)}
      onChange={(next) => cn.setRowDraftValue(column.id, next)}
      fieldProps={getSlotProps(
        table,
        "editField",
        { column },
        meta?.slotProps?.editField
      )}
    />
  )
}

"use client"

import type { RowData } from "@tanstack/react-table"
import * as React from "react"

import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuTrigger,
} from "@/components/ui/context-menu"

import type { DataTableInstance } from "../../core/types"
import { getColumnLabel } from "../../helpers/column-label"
import { isColumnEditable } from "../../helpers/is-column-editable"
import { stopPropagation } from "../../helpers/stop-propagation"
import { ClickToCopy, copyText } from "../body/click-to-copy"
import { DataTableEditField } from "./data-table-edit-field"
import type { DataTableCell } from "../../core/table-types"
import { dt } from "../../core/internal"
import { getSlotProps } from "../../helpers/slot-props"
import { getEditSelectOptions } from "../../helpers/edit-select-options"

/**
 * Resolves a leaf data cell's interactive content: an inline editor when this
 * cell/row is being edited (cell/row/table modes), otherwise the value wrapped
 * with click-to-copy, click-to-edit (cell mode), and/or a cell-actions context
 * menu as configured. `fallback` is the normal rendered value.
 */
export function DataTableBodyCellContent<TData extends RowData>({
  cell,
  table,
  fallback,
}: {
  cell: DataTableCell<TData, unknown>
  table: DataTableInstance<TData>
  fallback: React.ReactNode
}) {
  const cn = dt(table)
  const { row, column } = cell
  const editable = cn.getCanEditRow(row) && isColumnEditable(column, row)
  const mode = cn.editDisplayMode

  const isCellEditing =
    mode === "cell" &&
    cn.editingCell?.rowId === row.id &&
    cn.editingCell?.columnId === column.id
  const isRowEditing = mode === "row" && cn.editingRowId === row.id
  const isTableEditing = mode === "table"

  if (editable && (isCellEditing || isRowEditing || isTableEditing)) {
    const renderEditCell = column.columnDef.meta?.renderEditCell
    if (renderEditCell) {
      return renderEditCell({ cell, row, column, table })
    }
    return mode === "row" ? (
      <RowDraftEditor cell={cell} table={table} />
    ) : (
      <LocalDraftEditor
        cell={cell}
        table={table}
        exitOnCommit={mode === "cell"}
      />
    )
  }

  let node: React.ReactNode = fallback

  const copyOption =
    column.columnDef.meta?.enableClickToCopy ?? cn.enableClickToCopy
  const copyMode =
    typeof copyOption === "function" ? copyOption(cell) : copyOption
  if (copyMode === true) {
    node = (
      <ClickToCopy
        value={String(cell.getValue() ?? "")}
        copyLabel={cn.localization.copy}
        copiedLabel={cn.localization.copied}
      >
        {node}
      </ClickToCopy>
    )
  } else if (editable && mode === "cell") {
    node = (
      <button
        type="button"
        onClick={(event) => {
          stopPropagation(event)
          cn.setEditingCell({ rowId: row.id, columnId: column.id })
        }}
        onDoubleClick={stopPropagation}
        className="-mx-1 w-full rounded-sm px-1 text-start transition-colors outline-none hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring/40"
      >
        {node}
      </button>
    )
  }

  const cellActions =
    typeof cn.enableCellActions === "function"
      ? cn.enableCellActions(cell)
      : cn.enableCellActions
  // Copy shows in the menu when copying is on; Edit when the cell can start
  // editing (table mode is always editing).
  const menuCopy = copyMode === "context-menu" || (cellActions && !!copyMode)
  const menuEdit = cellActions && editable && mode !== "table"
  if (cn.renderCellActionMenuItems || menuCopy || menuEdit) {
    node = (
      <CellActionsMenu
        cell={cell}
        table={table}
        copy={menuCopy}
        edit={menuEdit}
      >
        {node}
      </CellActionsMenu>
    )
  }

  return node
}

/** The right-click menu on a cell: built-in Copy / Edit items, or the
 *  consumer's `renderCellActionMenuItems`. */
function CellActionsMenu<TData extends RowData>({
  cell,
  table,
  copy,
  edit,
  children,
}: {
  cell: DataTableCell<TData, unknown>
  table: DataTableInstance<TData>
  copy: boolean
  edit: boolean
  children: React.ReactNode
}) {
  const cn = dt(table)
  const { row, column } = cell
  // The context menu has no controlled `open`; remounting closes it.
  const [instance, setInstance] = React.useState(0)
  const closeMenu = () => setInstance((n) => n + 1)

  const internalMenuItems = (
    <>
      {copy && (
        <ContextMenuItem
          onClick={() => void copyText(String(cell.getValue() ?? ""))}
        >
          <cn.icons.copy />
          {cn.localization.copy}
        </ContextMenuItem>
      )}
      {edit && (
        <ContextMenuItem
          onClick={() =>
            cn.editDisplayMode === "cell"
              ? cn.setEditingCell({ rowId: row.id, columnId: column.id })
              : cn.beginRowEdit(row)
          }
        >
          <cn.icons.edit />
          {cn.localization.edit}
        </ContextMenuItem>
      )}
    </>
  )

  return (
    <ContextMenu key={instance}>
      <ContextMenuTrigger asChild>
        <span className="block">{children}</span>
      </ContextMenuTrigger>
      <ContextMenuContent
        onClick={stopPropagation}
        onDoubleClick={stopPropagation}
      >
        {cn.renderCellActionMenuItems
          ? cn.renderCellActionMenuItems({
              cell,
              row,
              table,
              internalMenuItems,
              closeMenu,
            })
          : internalMenuItems}
      </ContextMenuContent>
    </ContextMenu>
  )
}

/** Editor bound to the shared row draft (row/modal editing). */
function RowDraftEditor<TData extends RowData>({
  cell,
  table,
}: {
  cell: DataTableCell<TData, unknown>
  table: DataTableInstance<TData>
}) {
  const cn = dt(table)
  const { column } = cell
  const meta = column.columnDef.meta
  const value =
    column.id in cn.rowDraft ? cn.rowDraft[column.id] : cell.getValue()
  const error = meta?.validate?.(value)
  return (
    <DataTableEditField
      value={value}
      variant={meta?.editVariant}
      options={getEditSelectOptions(column, table, cell.row)}
      error={error}
      ariaLabel={getColumnLabel(column)}
      onChange={(next) => cn.setRowDraftValue(column.id, next)}
      fieldProps={getSlotProps(
        table,
        "editField",
        { column, row: cell.row },
        meta?.slotProps?.editField
      )}
    />
  )
}

/** Editor with local draft state (cell + table editing). */
function LocalDraftEditor<TData extends RowData>({
  cell,
  table,
  exitOnCommit,
}: {
  cell: DataTableCell<TData, unknown>
  table: DataTableInstance<TData>
  exitOnCommit: boolean
}) {
  const cn = dt(table)
  const { row, column } = cell
  const meta = column.columnDef.meta
  const [draft, setDraft] = React.useState<unknown>(() => cell.getValue())
  const error = meta?.validate?.(draft)

  const commit = (next: unknown = draft) => {
    if (meta?.validate?.(next)) return
    if (next !== cell.getValue()) {
      cn.onEditingCellSave?.({ row, column, value: next, table })
    }
    if (exitOnCommit) cn.setEditingCell(null)
  }

  const cancel = () => {
    setDraft(cell.getValue())
    if (exitOnCommit) cn.setEditingCell(null)
  }

  return (
    <DataTableEditField
      value={draft}
      variant={meta?.editVariant}
      options={getEditSelectOptions(column, table, row)}
      error={error}
      ariaLabel={getColumnLabel(column)}
      autoFocus={exitOnCommit}
      onChange={setDraft}
      onCommit={commit}
      onCancel={cancel}
      fieldProps={getSlotProps(
        table,
        "editField",
        { column, row },
        meta?.slotProps?.editField
      )}
    />
  )
}

"use client"

import * as React from "react"

import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { cn } from "@/lib/utils"

import type { DataTableFilterOption, EditVariant } from "../../core/types"
import { stopPropagation } from "../../helpers/stop-propagation"
import { mergeProps } from "../../helpers/slot-props"

const FIELD_CLASS =
  "h-8 rounded-sm text-xs font-normal tracking-normal normal-case"

/**
 * A controlled inline edit field (text / number / select). The parent owns the
 * draft value; this renders the input, surfaces validation errors, and wires
 * Enter (commit) / Escape (cancel) / blur (commit) for text inputs; select
 * commits on pick with the picked value.
 */
export function DataTableEditField({
  value,
  onChange,
  onCommit,
  onCancel,
  variant = "text",
  options,
  error,
  ariaLabel,
  autoFocus,
  fieldProps,
}: {
  /** Extra props for the input (or the select's trigger): `slotProps.editField`. */
  fieldProps?: Record<string, unknown>
  value: unknown
  onChange: (value: unknown) => void
  onCommit?: (value?: unknown) => void
  onCancel?: () => void
  variant?: EditVariant
  options?: DataTableFilterOption[]
  error?: string
  ariaLabel: string
  autoFocus?: boolean
}) {
  if (variant === "select") {
    return (
      <div
        className="flex flex-col gap-0.5"
        onClick={stopPropagation}
        onDoubleClick={stopPropagation}
      >
        <Select
          // Always controlled: "" shows the placeholder in both Radix and
          // Base UI, while `undefined` would flip to uncontrolled.
          value={value == null ? "" : String(value)}
          onValueChange={(picked) => {
            // Options carry strings; a numeric value stays a number.
            const next =
              typeof value === "number" &&
              typeof picked === "string" &&
              picked.trim() !== "" &&
              !Number.isNaN(Number(picked))
                ? Number(picked)
                : picked
            onChange(next)
            // Select commits on pick. Pass the value: the parent's draft
            // state has not updated yet in this tick.
            onCommit?.(next)
          }}
        >
          <SelectTrigger
            {...mergeProps(
              {
                size: "sm",
                className: cn(FIELD_CLASS, "w-full px-2"),
                "aria-label": ariaLabel,
                "aria-invalid": !!error,
              } as React.ComponentProps<typeof SelectTrigger>,
              fieldProps
            )}
          >
            <SelectValue placeholder="—" />
          </SelectTrigger>
          <SelectContent>
            {(options ?? []).map((option) => (
              <SelectItem key={option.value} value={option.value}>
                {option.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {error && <FieldError>{error}</FieldError>}
      </div>
    )
  }

  return (
    <div
      className="flex flex-col gap-0.5"
      onClick={stopPropagation}
      onDoubleClick={stopPropagation}
    >
      <Input
        {...mergeProps(
          {
            autoFocus,
            type: variant === "number" ? "number" : "text",
            inputMode: variant === "number" ? "decimal" : undefined,
            value: value == null ? "" : String(value),
            "aria-label": ariaLabel,
            "aria-invalid": !!error,
            onChange: (e: React.ChangeEvent<HTMLInputElement>) =>
              onChange(
                variant === "number"
                  ? e.target.value === ""
                    ? ""
                    : Number(e.target.value)
                  : e.target.value
              ),
            onKeyDown: (e: React.KeyboardEvent<HTMLInputElement>) => {
              if (e.key === "Enter") {
                e.preventDefault()
                onCommit?.()
              } else if (e.key === "Escape") {
                e.preventDefault()
                onCancel?.()
              }
            },
            onBlur: () => onCommit?.(),
            className: FIELD_CLASS,
          } as React.ComponentProps<"input">,
          fieldProps
        )}
      />
      {error && <FieldError>{error}</FieldError>}
    </div>
  )
}

function FieldError({ children }: { children: React.ReactNode }) {
  return <span className="text-[10px] text-destructive">{children}</span>
}

"use client"

import type { RowData } from "@tanstack/react-table"
import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"

import type { DataTableInstance } from "../../core/types"
import { useTableState } from "../../hooks/use-table-state"
import { getColumnLabel } from "../../helpers/column-label"
import { isColumnEditable } from "../../helpers/is-column-editable"
import { DataTableEditField } from "./data-table-edit-field"
import { dt } from "../../core/internal"
import { getSlotProps, mergeProps } from "../../helpers/slot-props"
import { getEditSelectOptions } from "../../helpers/edit-select-options"

/**
 * Edit/create dialog for `editDisplayMode: "modal"` (and the create form in any
 * mode). Renders an editor per editable column bound to the shared row draft;
 * Save commits via `onEditingRowSave` / `onCreatingRowSave`.
 */
export function DataTableEditModal<TData extends RowData>({
  table,
}: {
  table: DataTableInstance<TData>
}) {
  const {
    localization,
    editDisplayMode,
    createDisplayMode,
    editingRowId,
    isCreating,
    rowDraft,
    setRowDraftValue,
    cancelEdit,
    cancelEditing,
    onEditingRowSave,
    onCreatingRowSave,
    renderEditRowDialogContent,
    renderCreateRowDialogContent,
    getCanEditRow,
  } = dt(table)
  // The table around this dialog does not re-render for the edit draft.
  useTableState(table, (state) => [
    state.rowDraft,
    state.editingRowId,
    state.isCreating,
  ])

  // `table.getRow` throws when the id is gone (row deleted / refetched while
  // the dialog is open); look it up without throwing and bail out below.
  const editingRow =
    editingRowId != null
      ? table.getCoreRowModel().rowsById[editingRowId]
      : undefined
  const editingRowMissing = editingRowId != null && editingRow == null
  React.useEffect(() => {
    if (editingRowMissing) cancelEdit()
  }, [editingRowMissing, cancelEdit])

  const open =
    (isCreating && createDisplayMode === "modal") ||
    (editDisplayMode === "modal" &&
      editingRow != null &&
      getCanEditRow(editingRow))
  if (!open) return null

  const editableColumns = table
    .getAllLeafColumns()
    .filter((column) => isColumnEditable(column, editingRow ?? undefined))

  const hasErrors = editableColumns.some((column) => {
    const value =
      column.id in rowDraft
        ? rowDraft[column.id]
        : editingRow?.getValue(column.id)
    return column.columnDef.meta?.validate?.(value) != null
  })

  const submit = () => {
    if (hasErrors) return
    if (isCreating) {
      onCreatingRowSave?.({ values: rowDraft, table, exit: cancelEdit })
    } else if (editingRow) {
      onEditingRowSave?.({
        row: editingRow,
        values: rowDraft,
        table,
        exit: cancelEdit,
      })
    }
  }

  const internalEditComponents = editableColumns.map((column) => {
    const meta = column.columnDef.meta
    const value =
      column.id in rowDraft
        ? rowDraft[column.id]
        : editingRow?.getValue(column.id)
    return (
      <div key={column.id} className="flex flex-col gap-1.5">
        <Label className="text-xs">{getColumnLabel(column)}</Label>
        <DataTableEditField
          value={value}
          variant={meta?.editVariant}
          options={getEditSelectOptions(column, table, editingRow)}
          error={meta?.validate?.(value)}
          ariaLabel={getColumnLabel(column)}
          onChange={(next) => setRowDraftValue(column.id, next)}
          fieldProps={getSlotProps(
            table,
            "editField",
            { column, row: editingRow ?? undefined },
            meta?.slotProps?.editField
          )}
        />
      </div>
    )
  })

  const contentProps = {
    table,
    internalEditComponents,
    save: submit,
    cancel: cancelEditing,
    hasErrors,
  }
  const custom = isCreating
    ? renderCreateRowDialogContent?.(contentProps)
    : editingRow &&
      renderEditRowDialogContent?.({
        ...contentProps,
        row: editingRow,
      })

  return (
    <Dialog open onOpenChange={(next) => !next && cancelEditing()}>
      <DialogContent
        {...mergeProps(
          { className: "sm:max-w-lg" } as React.ComponentProps<"div">,
          getSlotProps(table, "editDialog", {
            row: editingRow ?? undefined,
            isCreating,
          })
        )}
      >
        {custom ?? (
          <>
            <DialogHeader>
              <DialogTitle>
                {isCreating ? localization.createNewRow : localization.editRow}
              </DialogTitle>
            </DialogHeader>
            <div className="flex flex-col gap-3 py-2">
              {internalEditComponents}
            </div>
            <DialogFooter>
              <Button variant="outline" size="sm" onClick={cancelEditing}>
                {localization.cancel}
              </Button>
              <Button size="sm" onClick={submit} disabled={hasErrors}>
                {localization.save}
              </Button>
            </DialogFooter>
          </>
        )}
      </DialogContent>
    </Dialog>
  )
}

"use client"

import * as React from "react"

import { flexRender, type RowData } from "@tanstack/react-table"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

import { defaultIcons } from "../../core/icons"
import { MOTION_TIMING_CLASS } from "../../core/motion"
import type { DataTableInstance } from "../../core/types"
import { getColumnLabel } from "../../helpers/column-label"
import {
  headerControlsOptionsFromTable,
  shouldShowColumnActions,
  shouldShowColumnFilterButton,
} from "../../helpers/header-controls"
import { ColumnDragHandle } from "../body/dnd"
import { DataTableColumnActions } from "../menus/data-table-column-actions"
import { DataTableColumnFilter } from "./data-table-column-filter"
import type { DataTableHeader } from "../../core/table-types"
import { dt } from "../../core/internal"

interface DataTableColumnHeaderProps<TData extends RowData, TValue> {
  header: DataTableHeader<TData, TValue>
  table: DataTableInstance<TData>
}

// Right alignment reverses the row so the label hugs the right edge with its
// controls on the inside; a reversed main axis starts on the right.
const ALIGN_CLASS = {
  left: "justify-start text-start",
  center: "justify-center text-center",
  right: "flex-row-reverse justify-start text-end",
} as const

/**
 * Wraps every header cell with the MRT layout: label (sort trigger) · sort
 * indicator · multi-sort order badge · column-actions menu, left-aligned by
 * default. Clicking the label cycles asc → desc → none; shift-click multi-sorts
 * (both via TanStack's `getToggleSortingHandler`).
 */
export function DataTableColumnHeader<TData extends RowData, TValue>({
  header,
  table,
}: DataTableColumnHeaderProps<TData, TValue>) {
  const { column } = header
  const { localization, icons } = dt(table)
  const controls = headerControlsOptionsFromTable(table)
  const align = column.columnDef.meta?.align ?? "left"

  const showFilterPopover = shouldShowColumnFilterButton(column, controls)
  const hasFilter = column.getFilterValue() != null
  const filterPopover = showFilterPopover ? (
    <Popover>
      <Tooltip>
        <TooltipTrigger asChild>
          <PopoverTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              aria-label={localization.filterByColumn(getColumnLabel(column))}
              className={cn(
                "size-7 shrink-0 opacity-70 transition-opacity group-hover/th:opacity-100 focus-visible:opacity-100 data-[state=open]:opacity-100",
                hasFilter && "text-primary opacity-100"
              )}
            >
              {hasFilter ? <icons.filter /> : <icons.filterOff />}
            </Button>
          </PopoverTrigger>
        </TooltipTrigger>
        <TooltipContent>
          {localization.filterByColumn(getColumnLabel(column))}
        </TooltipContent>
      </Tooltip>
      <PopoverContent align="start" className="w-64 gap-2">
        <span className="text-xs font-semibold tracking-wide text-muted-foreground uppercase">
          {localization.filterByColumn(getColumnLabel(column))}
        </span>
        <DataTableColumnFilter header={header} table={table} />
      </PopoverContent>
    </Popover>
  ) : null

  const labelNode = header.isPlaceholder
    ? null
    : flexRender(column.columnDef.header, { ...header.getContext(), table })

  const canSort = column.getCanSort()
  const sorted = column.getIsSorted() // false | "asc" | "desc"
  const sortIndex = column.getSortIndex()
  const isMultiSort = table.getState().sorting.length > 1 && sortIndex >= 0

  const showActions = shouldShowColumnActions(column, controls)

  const dragHandle = (
    <ColumnDragHandle
      label={localization.reorderColumn}
      Icon={icons.dragHandle}
    />
  )

  // Non-interactive header (e.g. the selection column): render content plainly.
  if (!canSort && !showActions) {
    return (
      <div
        className={cn("group/th flex items-center gap-1", ALIGN_CLASS[align])}
      >
        {labelNode}
        {dragHandle}
        {filterPopover}
      </div>
    )
  }

  const sortTooltip = !sorted
    ? localization.sortByColumnAsc(getColumnLabel(column))
    : sorted === "asc"
      ? localization.sortByColumnDesc(getColumnLabel(column))
      : localization.clearSort

  return (
    <div
      className={cn("group/th flex items-center gap-0.5", ALIGN_CLASS[align])}
    >
      {canSort ? (
        <Tooltip>
          <TooltipTrigger asChild>
            <button
              type="button"
              onClick={column.getToggleSortingHandler()}
              aria-label={sortTooltip}
              className="-mx-1.5 flex min-w-0 items-center gap-1 rounded-sm px-1.5 py-1 text-xs font-medium tracking-wider text-muted-foreground uppercase transition-colors outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/40 data-[sorted=true]:text-foreground motion-reduce:transition-none"
              data-sorted={!!sorted}
            >
              <span className="min-w-0 truncate">{labelNode}</span>
              <SortIndicator sorted={sorted} icons={icons} />
              {isMultiSort && (
                <Badge
                  variant="secondary"
                  className="ms-0.5 h-4 min-w-4 shrink-0 justify-center rounded-sm px-1 text-[10px] leading-none tabular-nums"
                >
                  {sortIndex + 1}
                </Badge>
              )}
            </button>
          </TooltipTrigger>
          <TooltipContent>{sortTooltip}</TooltipContent>
        </Tooltip>
      ) : (
        <span className="min-w-0 truncate px-0 text-xs font-medium tracking-wider uppercase">
          {labelNode}
        </span>
      )}

      {dragHandle}
      {showActions && (
        <DataTableColumnActions
          column={column}
          table={table}
          className="-my-1"
        />
      )}
      {filterPopover}
    </div>
  )
}

/** One stacked icon layer; only the shown one is visible. Layers fade and
 *  scale between states. */
const SORT_LAYER_CLASS = cn(
  "col-start-1 row-start-1 flex items-center justify-center transition-[opacity,visibility,scale]",
  MOTION_TIMING_CLASS
)

/** The today-look of the unsorted icon (faded, brighter on header hover). */
const UNSORTED_ICON_CLASS =
  "size-3.5 shrink-0 opacity-50 transition-opacity group-hover/th:opacity-70"

/**
 * The sort state icon. Every state's icon stays mounted, stacked in one grid
 * cell, and only the current one is visible, so a change fades between them
 * (when the table animates) instead of swapping nodes. With the default
 * icons, one arrow serves both directions and turns 180° for descending.
 * Custom icons are shown as given and only fade.
 *
 * The arrow only turns while it shows: clearing the sort keeps its last
 * direction so it just fades out, and when it shows again it takes its new
 * direction at once instead of turning while it fades in.
 */
function SortIndicator({
  sorted,
  icons,
}: {
  sorted: false | "asc" | "desc"
  icons: DataTableInstance["dataTable"]["icons"]
}) {
  const direction = sorted || "none"
  // The direction before the last change (state, not a ref: it is read
  // during render). Set during render, as React's "storing information from
  // previous renders" pattern does.
  const [seen, setSeen] = React.useState({ direction, from: direction })
  let from = seen.from
  if (seen.direction !== direction) {
    from = seen.direction
    setSeen({ direction, from })
  }
  const turned = (direction === "none" ? from : direction) === "desc"
  const turns = from !== "none"
  const defaultArrows =
    icons.sortAscending === defaultIcons.sortAscending &&
    icons.sortDescending === defaultIcons.sortDescending

  const layer = (shown: boolean, icon: React.ReactNode, key: string) => (
    <span
      key={key}
      data-shown={shown ? "" : undefined}
      className={cn(
        SORT_LAYER_CLASS,
        shown ? "scale-100" : "invisible scale-75 opacity-0"
      )}
    >
      {icon}
    </span>
  )

  return (
    <span
      data-slot="data-table-sort-indicator"
      data-direction={direction}
      aria-hidden="true"
      className="inline-grid shrink-0 place-items-center"
    >
      {layer(
        direction === "none",
        <icons.sortUnsorted className={UNSORTED_ICON_CLASS} />,
        "none"
      )}
      {defaultArrows ? (
        layer(
          direction !== "none",
          <icons.sortAscending
            className={cn(
              "size-3.5 shrink-0",
              turns && ["transition-[rotate]", MOTION_TIMING_CLASS],
              turned && "rotate-180"
            )}
          />,
          "arrow"
        )
      ) : (
        <>
          {layer(
            direction === "asc",
            <icons.sortAscending className="size-3.5 shrink-0" />,
            "asc"
          )}
          {layer(
            direction === "desc",
            <icons.sortDescending className="size-3.5 shrink-0" />,
            "desc"
          )}
        </>
      )}
    </span>
  )
}

"use client"

import {
  SortableContext,
  horizontalListSortingStrategy,
} from "@dnd-kit/sortable"
import type { RowData } from "@tanstack/react-table"
import * as React from "react"

import {
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { cn } from "@/lib/utils"

import { CELL_PADDING_Y } from "../../core/constants"
import type { DataTableInstance } from "../../core/types"
import {
  headerControlsOptionsFromTable,
  shouldShowColumnDragGrip,
} from "../../helpers/header-controls"
import type {
  VirtualHeaderLayout,
  WithHeaderSpacers,
} from "../../hooks/use-table-virtualizers"
import {
  getColumnDragStyle,
  getColumnPinningClass,
  getColumnPinningStyle,
  getWidthStyle,
} from "../../utils/column-styles"
import { DataTableHeadCell } from "../body/dnd"
import { DataTableColumnFilter } from "./data-table-column-filter"
import { DataTableColumnHeader } from "./data-table-column-header"
import { isFilterRowVisible } from "../../helpers/grid-rows"
import { getSlotProps, mergeProps } from "../../helpers/slot-props"
import type { DataTableHeader } from "../../core/table-types"
import { dt } from "../../core/internal"
import { useDndId } from "../../core/dnd-scope"

interface DataTableHeaderProps<TData extends RowData> {
  table: DataTableInstance<TData>
  withHeaderSpacers: WithHeaderSpacers
}

/**
 * The table `<thead>`: the (optionally sticky) header-group rows and, when
 * enabled, the per-column filter subheader row. Honors column virtualization,
 * ordering (drag handles), pinning, and resizing.
 */
export function DataTableHeader<TData extends RowData>({
  table,
  withHeaderSpacers,
}: DataTableHeaderProps<TData>) {
  const {
    enableColumnResizing,
    enableColumnVirtualization,
    enableStickyHeader,
    enableKeyboardNavigation,
    refs,
  } = dt(table)

  const controls = headerControlsOptionsFromTable(table)
  const padding = CELL_PADDING_Y
  const dndId = useDndId()
  const leafColumnIds = table.getVisibleLeafColumns().map((c) => dndId(c.id))

  const filterRowVisible = isFilterRowVisible(table)
  const headerGroups = table.getHeaderGroups()
  // Grid row positions (keyboard navigation makes the table a grid).
  const rowIndex = (index: number) =>
    enableKeyboardNavigation ? index + 1 : undefined

  const renderHeadCell = (
    header: DataTableHeader<TData, unknown>,
    layout?: VirtualHeaderLayout
  ) => (
    <DataTableHeadCell
      key={layout?.key ?? header.id}
      header={header}
      table={table}
      colSpan={layout?.colSpan}
      // Draggable for reordering (column ordering) or to drag onto the group
      // zone (grouping) — the drag-end handler routes by the drop target. The
      // grip's presence drives the column's reserved width, so both read the
      // same predicate (see helpers/header-controls).
      draggable={shouldShowColumnDragGrip(header.column, controls)}
      resizable={enableColumnResizing}
      widthStyle={layout?.widthStyle ?? getWidthStyle(header.column, table)}
      padding={padding}
    >
      {header.isPlaceholder ? null : (
        <DataTableColumnHeader header={header} table={table} />
      )}
    </DataTableHeadCell>
  )

  const renderFilterCell = (
    header: DataTableHeader<TData, unknown>,
    layout?: VirtualHeaderLayout
  ) => (
    <TableHead
      key={layout?.key ?? header.id}
      {...mergeProps(
        {
          // The filter row holds controls, not column headers.
          role: enableKeyboardNavigation ? "gridcell" : "cell",
          colSpan: layout?.colSpan ?? header.colSpan,
          style: {
            ...(layout?.widthStyle ?? getWidthStyle(header.column, table)),
            ...getColumnPinningStyle(header.column),
            // Follows its header while the column is dragged.
            ...(dt(table).enableColumnOrdering &&
              getColumnDragStyle(
                header.column.id,
                getColumnPinningStyle(header.column).zIndex as
                  number | undefined
              )),
          },
          className: cn("bg-card", getColumnPinningClass(header.column)),
        } as React.ComponentProps<"th">,
        getSlotProps(
          table,
          "filterCell",
          { header, column: header.column },
          header.column.columnDef.meta?.slotProps?.filterCell
        )
      )}
    >
      <DataTableColumnFilter header={header} table={table} />
    </TableHead>
  )

  return (
    <TableHeader
      {...mergeProps(
        {
          // Forwarding the exposed DOM ref object as a JSX ref.
          ref: refs.tableHeadRef,
          className: cn(enableStickyHeader && "sticky top-0 z-20 bg-card"),
        } as React.ComponentProps<"thead">,
        getSlotProps(table, "head", {})
      )}
    >
      {headerGroups.map((headerGroup, index) => (
        <TableRow
          key={headerGroup.id}
          {...mergeProps(
            {
              "aria-rowindex": rowIndex(index),
              className: "group/th hover:bg-transparent",
            } as React.ComponentProps<"tr">,
            getSlotProps(table, "headRow", { headerGroup })
          )}
        >
          <SortableContext
            items={leafColumnIds}
            strategy={horizontalListSortingStrategy}
          >
            {enableColumnVirtualization
              ? withHeaderSpacers(
                  headerGroup.headers,
                  renderHeadCell,
                  `head-${headerGroup.id}`
                )
              : headerGroup.headers.map((header) => renderHeadCell(header))}
          </SortableContext>
        </TableRow>
      ))}

      {filterRowVisible &&
        // Only leaf columns filter; group header rows would render empty.
        headerGroups.slice(-1).map((headerGroup) => (
          <TableRow
            key={`${headerGroup.id}-filters`}
            aria-rowindex={rowIndex(headerGroups.length)}
            className="hover:bg-transparent"
          >
            {enableColumnVirtualization
              ? withHeaderSpacers(
                  headerGroup.headers,
                  renderFilterCell,
                  `filter-${headerGroup.id}`
                )
              : headerGroup.headers.map((header) => renderFilterCell(header))}
          </TableRow>
        ))}
    </TableHeader>
  )
}

