import { dt } from "../../../core/internal"

/** Toolbar button that opens the advanced filter panel; badges the active-rule
 *  count when any rules are set. */
export function DataTableAdvancedFilterToggle<TData extends RowData>({
  table,
}: {
  table: DataTableInstance<TData>
}) {
  const {
    localization,
    icons,
    advancedFilter,
    showAdvancedFilterPanel,
    setShowAdvancedFilterPanel,
  } = dt(table)
  const count = advancedFilter.rules.length

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          variant="outline"
          size="icon"
          aria-label={localization.advancedFilters}
          aria-pressed={showAdvancedFilterPanel}
          onClick={() => setShowAdvancedFilterPanel((prev) => !prev)}
          className={cn(
            "relative size-8",
            (showAdvancedFilterPanel || count > 0) && "bg-muted text-foreground"
          )}
        >
          <icons.advancedFilter />
          {count > 0 && (
            <Badge className="absolute -end-1.5 -top-1.5 size-4 justify-center rounded-full p-0 text-[10px] tabular-nums">
              {count}
            </Badge>
          )}
        </Button>
      </TooltipTrigger>
      <TooltipContent>{localization.advancedFilters}</TooltipContent>
    </Tooltip>
  )
}

"use client"

import type { RowData } from "@tanstack/react-table"

import { Button } from "@/components/ui/button"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"

import { DENSITY_ORDER } from "../../../core/constants"
import type { DataTableInstance } from "../../../core/types"
import { dt } from "../../../core/internal"

const DENSITY_LABEL_KEYS = {
  comfortable: "densityComfortable",
  compact: "densityCompact",
  spacious: "densitySpacious",
} as const

/** Single button that cycles comfortable → compact → spacious. */
export function DataTableDensityToggle<TData extends RowData>({
  table,
}: {
  table: DataTableInstance<TData>
}) {
  const { localization, icons, density, setDensity } = dt(table)
  const currentLabel = localization[DENSITY_LABEL_KEYS[density]]
  const label = `${localization.toggleDensity} (${currentLabel})`
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          variant="outline"
          size="icon"
          aria-label={label}
          className="size-8"
          onClick={() =>
            setDensity((prev) => {
              const next =
                DENSITY_ORDER[
                  (DENSITY_ORDER.indexOf(prev) + 1) % DENSITY_ORDER.length
                ]
              return next ?? "comfortable"
            })
          }
        >
          <icons.density />
        </Button>
      </TooltipTrigger>
      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  )
}

