"use client"

import * as React from "react"

import type { RowData } from "@tanstack/react-table"

import type { DataTableInstance } from "../../core/types"
import { dt } from "../../core/internal"
import { readMotionTokens } from "../../core/motion"
import { getSlotProps, mergeProps } from "../../helpers/slot-props"

/**
 * Selection alert banner shown between the toolbar and the table when any rows
 * are selected: a muted strip with the localized count and a Clear action.
 */
export function DataTableAlertBanner<TData extends RowData>({
  table,
}: {
  table: DataTableInstance<TData>
}) {
  const { localization, enableRowSelection } = dt(table)
  const selectedCount = enableRowSelection
    ? table.getSelectedRowModel().rows.length
    : 0
  const totalCount =
    selectedCount > 0 ? table.getPrePaginatedRowModel().rows.length : 0
  const text =
    selectedCount > 0
      ? localization.rowsSelected(selectedCount, totalCount)
      : null
  const countRef = React.useRef<HTMLSpanElement>(null)
  useCountCrossfade(countRef, text)

  if (text === null) return null

  return (
    <div
      {...mergeProps(
        {
          "data-slot": "data-table-alert-banner",
          className:
            "flex items-center justify-between gap-3 rounded-md border bg-muted px-3 py-2 text-xs font-medium text-muted-foreground",
          role: "status",
        } as React.ComponentProps<"div">,
        getSlotProps(table, "alertBanner", {})
      )}
    >
      {/* The box the old count's copy fades out in (see useCountCrossfade). */}
      <span className="relative">
        <span ref={countRef} data-slot="data-table-selected-count">
          {text}
        </span>
      </span>
      <button
        type="button"
        onClick={() => table.resetRowSelection()}
        className="font-semibold tracking-wide text-foreground underline-offset-4 hover:underline"
      >
        {localization.clearSelection}
      </button>
    </div>
  )
}

/**
 * Crossfades the count when its text changes: the new text fades in while a
 * short-lived copy of the old one, laid over it in the same box, fades out
 * and is removed. Not when the banner first appears (from 0), and never
 * unless the table animates: the root's `[data-animations]` already folds in
 * `enableAnimations` and reduced motion, so reading it here needs no extra
 * prop or media-query subscription.
 */
function useCountCrossfade(
  ref: React.RefObject<HTMLSpanElement | null>,
  text: string | null
) {
  const prev = React.useRef(text)
  const copy = React.useRef<HTMLElement | null>(null)
  React.useLayoutEffect(() => {
    const before = prev.current
    prev.current = text
    const el = ref.current
    const box = el?.parentElement
    if (!el || !box || before === null || before === text) return
    const root = el.closest("[data-animations]")
    if (!root || typeof el.animate !== "function") return
    const { durationFast, ease } = readMotionTokens(root)
    copy.current?.remove()
    const old = document.createElement("span")
    old.textContent = before
    old.setAttribute("aria-hidden", "true")
    old.setAttribute("data-slot", "data-table-selected-count-previous")
    Object.assign(old.style, {
      position: "absolute",
      top: "0",
      insetInlineStart: "0",
      whiteSpace: "nowrap",
      pointerEvents: "none",
    })
    box.append(old)
    copy.current = old
    const remove = () => {
      old.remove()
      if (copy.current === old) copy.current = null
    }
    const timing = { duration: durationFast, easing: ease }
    el.animate([{ opacity: 0 }, { opacity: 1 }], timing)
    old
      .animate([{ opacity: 1 }, { opacity: 0 }], {
        ...timing,
        fill: "forwards",
      })
      .finished.then(remove, remove)
  }, [ref, text])
}

"use client"

import type * as React from "react"

import type { RowData } from "@tanstack/react-table"

import { cn } from "@/lib/utils"

import type { DataTableInstance } from "../../core/types"
import { DataTablePagination } from "./data-table-pagination"
import { dt } from "../../core/internal"
import { getSlotProps, mergeProps } from "../../helpers/slot-props"

interface DataTableBottomToolbarProps<TData extends RowData> {
  table: DataTableInstance<TData>
}

/**
 * The bottom toolbar region. Honors a `renderBottomToolbar` override; otherwise
 * lays out optional custom actions alongside the bottom pagination control,
 * rendering nothing when neither is present.
 */
export function DataTableBottomToolbar<TData extends RowData>({
  table,
}: DataTableBottomToolbarProps<TData>) {
  const {
    enableBottomToolbar,
    enablePagination,
    positionPagination,
    renderBottomToolbar,
    renderBottomToolbarCustomActions,
    refs,
  } = dt(table)

  if (renderBottomToolbar) return <>{renderBottomToolbar({ table })}</>
  if (!enableBottomToolbar) return null

  const customActions = renderBottomToolbarCustomActions?.({ table })
  const showBottomPagination =
    enablePagination &&
    (positionPagination === "bottom" || positionPagination === "both")
  const pagination = showBottomPagination ? (
    <DataTablePagination table={table} />
  ) : null

  if (customActions == null && pagination == null) return null

  return (
    <div
      {...mergeProps(
        {
          // Forwarding the exposed DOM ref object as a JSX ref.
          ref: refs.bottomToolbarRef,
          "data-slot": "data-table-bottom-toolbar",
          className: cn(
            customActions != null &&
              "flex flex-wrap items-center justify-between gap-4"
          ),
        } as React.ComponentProps<"div">,
        getSlotProps(table, "bottomToolbar", {})
      )}
    >
      {customActions != null ? (
        <>
          <div className="flex items-center gap-2">{customActions}</div>
          {pagination && <div className="flex-1">{pagination}</div>}
        </>
      ) : (
        pagination
      )}
    </div>
  )
}

"use client"

import type { RowData } from "@tanstack/react-table"
import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import type { DataTableInstance } from "../../core/types"
import type { GlobalFilterMode } from "../../fns/filter-fns"
import { dt } from "../../core/internal"
import { getSlotProps, mergeProps } from "../../helpers/slot-props"

/**
 * Expandable global search (MRT order: first in the toolbar icon cluster). The
 * search button expands into an input with a leading icon, an optional
 * search-mode menu, and a clear affordance. Input is debounced in manual
 * (server) mode so each keystroke doesn't fire a request.
 */
export function DataTableGlobalFilter<TData extends RowData>({
  table,
  searchInputRef,
}: {
  table: DataTableInstance<TData>
  /** Optional ref forwarded to the search input. Defaults to the instance's
   *  `searchInputRef` when rendered by `DataTable`. */
  searchInputRef?: React.RefObject<HTMLInputElement | null>
}) {
  const {
    localization,
    icons,
    enableGlobalFilter,
    enableGlobalFilterModes,
    globalFilterMode,
    setGlobalFilterMode,
    renderGlobalFilterModeMenuItems,
    globalFilterModeOptions: modes,
    showGlobalFilter: expanded,
    setShowGlobalFilter: setExpanded,
  } = dt(table)

  const external = (table.getState().globalFilter ?? "") as string
  // A value set from outside opens the box (also when the table starts with
  // a search in `initialState`).
  const [openedFor, setOpenedFor] = React.useState("")
  if (external.length > 0 && !expanded && external !== openedFor) {
    setOpenedFor(external)
    setExpanded(true)
  }
  const [value, setValue] = React.useState(external)

  // Values this box committed that the table state has not reflected yet.
  // Controlled state that stores them late (router / async state) echoes them
  // back while the user types on; an echo must not replace the newer draft.
  const [inFlight, setInFlight] = React.useState<string[]>([])

  // Outside changes (`setGlobalFilter`, `resetGlobalFilter`, controlled state)
  // win over the local draft. Adjusted during render (React's "derive state
  // from a prop change" pattern) rather than in an effect, which lint forbids.
  // While typing with a debounce, `external` is unchanged, so the draft is kept:
  // `value` only resets when `external` itself changes to something new.
  const [prevExternal, setPrevExternal] = React.useState(external)
  if (external !== prevExternal) {
    setPrevExternal(external)
    const echo = inFlight.indexOf(external)
    if (echo >= 0) {
      setInFlight(inFlight.slice(echo + 1))
    } else {
      setInFlight([])
      setValue(external)
      if (external.length > 0) setExpanded(true)
    }
  }
  // Drive focus-on-expand and let consumers focus the box. Use the forwarded
  // ref when provided (so `DataTable` shares its `searchInputRef`), else a
  // local one. React assigns it directly — no manual `.current` mutation.
  const localRef = React.useRef<HTMLInputElement>(null)
  const inputRef = searchInputRef ?? localRef

  const debounceMs = table.options.manualFiltering ? 300 : 0

  React.useEffect(() => {
    if (value === (table.getState().globalFilter ?? "")) return
    const id = setTimeout(() => {
      setInFlight((prev) => [...prev.slice(-19), value])
      table.setGlobalFilter(value || undefined)
    }, debounceMs)
    return () => clearTimeout(id)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value, debounceMs])

  if (!enableGlobalFilter) return null

  if (!expanded) {
    return (
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            variant="outline"
            size="icon"
            aria-label={localization.search}
            className="size-8"
            onClick={() => {
              setExpanded(true)
              requestAnimationFrame(() => inputRef.current?.focus())
            }}
          >
            <icons.search />
          </Button>
        </TooltipTrigger>
        <TooltipContent>{localization.search}</TooltipContent>
      </Tooltip>
    )
  }

  const clear = () => {
    setValue("")
    table.setGlobalFilter(undefined)
    setExpanded(false)
  }

  return (
    <div className="flex h-9 items-center gap-0.5 rounded-md border bg-background ps-2 pe-1 focus-within:border-ring">
      <icons.search className="size-3.5 shrink-0 text-muted-foreground" />
      <Input
        {...mergeProps(
          // The ref is forwarded to the input, not read during render.
          // eslint-disable-next-line react-hooks/refs
          {
            ref: inputRef,
            value,
            onChange: (e: React.ChangeEvent<HTMLInputElement>) =>
              setValue(e.target.value),
            onBlur: () => {
              if (!value) setExpanded(false)
            },
            placeholder: localization.searchPlaceholder,
            "aria-label": localization.search,
            className:
              "h-7 w-40 border-0 px-1 text-xs font-normal tracking-normal normal-case shadow-none focus-visible:ring-0 sm:w-56",
          } as React.ComponentProps<"input">,
          getSlotProps(table, "searchInput", {})
        )}
      />
      {value && (
        <Button
          variant="ghost"
          size="icon"
          aria-label={localization.clearSearch}
          onClick={clear}
          className="size-7"
        >
          <icons.clear />
        </Button>
      )}
      {enableGlobalFilterModes && (
        <DropdownMenu>
          <Tooltip>
            <TooltipTrigger asChild>
              <DropdownMenuTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  aria-label={localization.globalFilterMode}
                  className="size-7"
                >
                  <icons.search className="size-3" />
                </Button>
              </DropdownMenuTrigger>
            </TooltipTrigger>
            <TooltipContent>{localization.globalFilterMode}</TooltipContent>
          </Tooltip>
          <DropdownMenuContent align="end" className="w-48">
            {/* Base UI's GroupLabel requires a Group ancestor; Radix renders
                the group as an inert wrapper. */}
            <DropdownMenuGroup>
              <DropdownMenuLabel>
                {localization.globalFilterMode}
              </DropdownMenuLabel>
            </DropdownMenuGroup>
            <DropdownMenuSeparator />
            {renderGlobalFilterModeMenuItems ? (
              renderGlobalFilterModeMenuItems({
                modes,
                currentMode: globalFilterMode,
                onSelect: setGlobalFilterMode,
                table,
              })
            ) : (
              <DropdownMenuRadioGroup
                value={globalFilterMode}
                onValueChange={(mode) =>
                  setGlobalFilterMode(mode as GlobalFilterMode)
                }
              >
                {modes.map((mode) => (
                  <DropdownMenuRadioItem key={mode} value={mode}>
                    {localization.filterModes[mode] ?? mode}
                  </DropdownMenuRadioItem>
                ))}
              </DropdownMenuRadioGroup>
            )}
          </DropdownMenuContent>
        </DropdownMenu>
      )}
    </div>
  )
}

"use client"

import * as React from "react"

import { useDroppable } from "@dnd-kit/core"
import type { RowData } from "@tanstack/react-table"

import { Badge } from "@/components/ui/badge"
import { cn } from "@/lib/utils"

import type { DataTableInstance } from "../../core/types"
import { getColumnLabel } from "../../helpers/column-label"
import { dt } from "../../core/internal"
import { DndKeyContext, useDndId } from "../../core/dnd-scope"

export const GROUP_DROPZONE_ID = "cn-group-dropzone"

/**
 * The MRT "drop to group by" zone: a dashed strip below the toolbar showing
 * chips for the active grouping columns (each removable) and acting as a drop
 * target for column drags (handled by the column DnD context in `<DataTable>`).
 */
export function DataTableDropToGroupZone<TData extends RowData>({
  table,
}: {
  table: DataTableInstance<TData>
}) {
  const { localization, icons } = dt(table)
  const grouping = table.getState().grouping
  const tableKey = React.useContext(DndKeyContext)
  const dndId = useDndId()
  const { setNodeRef, isOver } = useDroppable({
    id: dndId(GROUP_DROPZONE_ID),
    data: { type: "group-zone", tableKey },
  })

  return (
    <div
      ref={setNodeRef}
      className={cn(
        "flex min-h-10 flex-wrap items-center gap-2 rounded-md border border-dashed px-3 py-2 text-xs text-muted-foreground transition-colors",
        isOver && "border-primary bg-muted text-foreground"
      )}
    >
      <icons.group className="size-3.5 shrink-0" />
      {grouping.length === 0 ? (
        <span>{localization.dropToGroupBy}</span>
      ) : (
        grouping.map((columnId) => {
          const column = table.getColumn(columnId)
          if (!column) return null
          return (
            <Badge
              key={columnId}
              variant="secondary"
              className="gap-1 rounded-sm pe-1 normal-case"
            >
              {getColumnLabel(column)}
              <button
                type="button"
                aria-label={localization.ungroupByColumn(
                  getColumnLabel(column)
                )}
                onClick={() => column.toggleGrouping()}
                className="rounded-sm text-muted-foreground transition-colors hover:text-foreground"
              >
                <icons.clear className="size-3" />
              </button>
            </Badge>
          )
        })
      )}
    </div>
  )
}

"use client"

import type { RowData } from "@tanstack/react-table"
import type * as React from "react"

import { Button } from "@/components/ui/button"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"

import type { DataTableInstance } from "../../core/types"
import { formatInteger } from "../../helpers/format-integer"
import { dt } from "../../core/internal"
import { getSlotProps, mergeProps } from "../../helpers/slot-props"

interface DataTablePaginationProps<TData extends RowData> {
  table: DataTableInstance<TData>
}

/**
 * Bottom toolbar. Left: rows-per-page select. Right: MRT-style "start–end of
 * total" range label + first/prev/next/last icon buttons. Works in client and
 * manual/server pagination (counts come from the table instance).
 */
export function DataTablePagination<TData extends RowData>({
  table,
}: DataTablePaginationProps<TData>) {
  const { localization, icons, paginationDisplayMode, pageSizeOptions } =
    dt(table)
  if (paginationDisplayMode === "custom") return null

  const { pageIndex, pageSize } = table.getState().pagination
  const totalRows = table.getRowCount()
  const start = totalRows === 0 ? 0 : pageIndex * pageSize + 1
  const end = Math.min((pageIndex + 1) * pageSize, totalRows)

  return (
    <div
      {...mergeProps(
        {
          "data-slot": "data-table-pagination",
          className: "flex flex-wrap items-center justify-between gap-4 py-1",
        } as React.ComponentProps<"div">,
        getSlotProps(table, "pagination", {})
      )}
    >
      <div className="flex items-center gap-2">
        <span className="text-xs font-medium tracking-wide text-muted-foreground">
          {localization.rowsPerPage}
        </span>
        <Select
          value={`${pageSize}`}
          onValueChange={(value) => table.setPageSize(Number(value))}
        >
          <SelectTrigger
            size="sm"
            className="h-8 w-18"
            aria-label={localization.rowsPerPage}
          >
            <SelectValue
              placeholder={formatInteger(pageSize, localization.language)}
            />
          </SelectTrigger>
          <SelectContent>
            {pageSizeOptions.map((size) => (
              <SelectItem key={size} value={`${size}`}>
                {formatInteger(size, localization.language)}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {paginationDisplayMode === "pages" ? (
        <div className="flex items-center gap-1">
          <PaginationButton
            label={localization.goToPreviousPage}
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
          >
            <icons.pagePrev className="rtl:rotate-180" />
          </PaginationButton>
          {getPageList(pageIndex + 1, table.getPageCount()).map((item, i) =>
            item === "ellipsis" ? (
              <span
                key={`ellipsis-${i}`}
                className="px-1 text-xs text-muted-foreground"
                aria-hidden
              >
                …
              </span>
            ) : (
              <Button
                key={item}
                variant={item === pageIndex + 1 ? "default" : "outline"}
                size="icon"
                aria-label={localization.goToPage(item)}
                aria-current={item === pageIndex + 1 ? "page" : undefined}
                onClick={() => table.setPageIndex(item - 1)}
                className="size-8 text-xs tabular-nums"
              >
                {formatInteger(item, localization.language)}
              </Button>
            )
          )}
          <PaginationButton
            label={localization.goToNextPage}
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
          >
            <icons.pageNext className="rtl:rotate-180" />
          </PaginationButton>
        </div>
      ) : (
        <div className="flex items-center gap-3">
          <span className="text-xs font-medium tracking-wide text-muted-foreground tabular-nums">
            {localization.paginationRange(start, end, totalRows)}
          </span>
          <div className="flex items-center gap-1">
            <PaginationButton
              label={localization.goToFirstPage}
              onClick={() => table.setPageIndex(0)}
              disabled={!table.getCanPreviousPage()}
            >
              <icons.pageFirst className="rtl:rotate-180" />
            </PaginationButton>
            <PaginationButton
              label={localization.goToPreviousPage}
              onClick={() => table.previousPage()}
              disabled={!table.getCanPreviousPage()}
            >
              <icons.pagePrev className="rtl:rotate-180" />
            </PaginationButton>
            <PaginationButton
              label={localization.goToNextPage}
              onClick={() => table.nextPage()}
              disabled={!table.getCanNextPage()}
            >
              <icons.pageNext className="rtl:rotate-180" />
            </PaginationButton>
            <PaginationButton
              label={localization.goToLastPage}
              onClick={() => table.setPageIndex(table.getPageCount() - 1)}
              disabled={!table.getCanNextPage()}
            >
              <icons.pageLast className="rtl:rotate-180" />
            </PaginationButton>
          </div>
        </div>
      )}
    </div>
  )
}

/**
 * Windowed page list for "pages" mode: always shows the first and last page and
 * the current page ± 1, collapsing the gaps to an `"ellipsis"` marker. Lists
 * every page when there are 7 or fewer. Page numbers are 1-based.
 */
function getPageList(current: number, total: number): (number | "ellipsis")[] {
  if (total <= 1) return total === 1 ? [1] : []
  if (total <= 7) return Array.from({ length: total }, (_, i) => i + 1)
  const wanted = [1, total, current, current - 1, current + 1].filter(
    (p) => p >= 1 && p <= total
  )
  const sorted = [...new Set(wanted)].sort((a, b) => a - b)
  const result: (number | "ellipsis")[] = []
  let prev = 0
  for (const page of sorted) {
    if (page - prev > 1) result.push("ellipsis")
    result.push(page)
    prev = page
  }
  return result
}

function PaginationButton({
  label,
  onClick,
  disabled,
  children,
}: {
  label: string
  onClick: () => void
  disabled: boolean
  children: React.ReactNode
}) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          variant="outline"
          size="icon"
          aria-label={label}
          onClick={onClick}
          disabled={disabled}
          className="size-8"
        >
          {children}
        </Button>
      </TooltipTrigger>
      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  )
}

