  hasFooter,
} from "../components/body/data-table-footer"
import { DataTableEditModal } from "../components/editing/data-table-edit-modal"
import { DataTableHeader } from "../components/head/data-table-header"
import { DataTableAlertBanner } from "../components/toolbar/data-table-alert-banner"
import { DataTableBottomToolbar } from "../components/toolbar/data-table-bottom-toolbar"
import { DataTableDropToGroupZone } from "../components/toolbar/data-table-grouping"
import { DataTablePagination } from "../components/toolbar/data-table-pagination"
import { DataTableToolbar } from "../components/toolbar/data-table-toolbar"
import { EDITING_STATE, region } from "../components/region"
import {
  GridSyncContext,
  useGridNavigation,
} from "../hooks/use-grid-navigation"
import { useDragAnnouncements } from "../hooks/use-drag-announcements"
import { useInfiniteScroll } from "../hooks/use-infinite-scroll"
import { useTableDnd } from "../hooks/use-table-dnd"
import {
  DndKeyContext,
  TableDropTarget,
  useDndScope,
  useIsDropTarget,
} from "./dnd-scope"
import { useTableVirtualizers } from "../hooks/use-table-virtualizers"
import { useTableState } from "../hooks/use-table-state"
import { useFullscreenModal } from "../hooks/use-fullscreen-modal"
import { useRowPinningDisplay } from "../hooks/use-row-pinning-display"
import { getDataRowCount, getHeaderRowCount } from "../helpers/grid-rows"
import { getColumnSizeVars } from "../utils/column-styles"
import { type DataTableInstance } from "./types"
import { dt } from "./internal"
import { DataTableProvider } from "./table-context"
import { DENSITY_PADDING_VARS } from "./constants"
import { MOTION_ROOT_CLASS, useAnimationsActive } from "./motion"

/**
 * Body wrapper that freezes during an active column resize. With
 * `columnResizeMode: "onChange"` the table re-renders on every mousemove;
 * skipping the body's re-render keeps drags smooth, since column widths come
 * from the CSS size vars on `<table>` and update without React. Outside of a
 * resize the comparator returns false, so normal re-rendering is unchanged.
 */
// The parts around the body re-render on their own state, not on every change
// to the table (see components/region.tsx). The edit modal shows the edit
// draft, so it is not one of them.
const ToolbarRegion = region(DataTableToolbar)
const AlertBannerRegion = region(DataTableAlertBanner)
const PaginationRegion = region(DataTablePagination)
const BottomToolbarRegion = region(DataTableBottomToolbar)
const DropToGroupZoneRegion = region(DataTableDropToGroupZone)
const HeaderRegion = region(DataTableHeader, EDITING_STATE)
const FooterRegion = region(DataTableFooter)

// State that rows (and the editors) subscribe to themselves: the table
// around them does not re-render for it.
const ROW_STATE = new Set([
  "rowSelection",
  "rowDraft",
  "editingCell",
  "editingRowId",
])

const MemoizedDataTableBody = React.memo(
  DataTableBody,
  (_prev, next) =>
    next.table.getState().columnSizingInfo.isResizingColumn !== false
) as typeof DataTableBody

interface DataTableProps<
  TData extends RowData,
> extends React.ComponentProps<"div"> {
  /** The instance returned by `useDataTable`. */
  table: DataTableInstance<TData>
}

/**
 * Points a callback or object ref at `el`. Returns the callback's return value
 * (a React 19 ref cleanup) when `ref` is a function.
 */
function assignRef<T>(ref: React.Ref<T> | undefined, el: T | null) {
  if (typeof ref === "function") return ref(el)
  if (ref) ref.current = el
}

/**
 * Renders a data table from an instance produced by {@link useDataTable}.
 * Vertical stack: top toolbar → alert banner → drop-to-group zone → bordered
 * surface (sticky header, optional filter row, body, optional sticky footer) →
 * pagination. Wires DnD column/row ordering, pinning, resizing, grouping,
 * expansion, and detail panels.
 */
export function DataTable<TData extends RowData>({
  table,
  className,
  ref: refProp,
  onKeyDown: onKeyDownProp,
  ...props
}: DataTableProps<TData>) {
  const {
    density,
    isFullscreen,
    setIsFullscreen,
    isLoading,
    isSaving,
    showProgressBars,
    showLoadingOverlay,
    enableColumnResizing,
    enableGrouping,
    enableRowVirtualization,
    enableStickyHeader,
    enablePagination,
    enableInfiniteScroll,
    onLoadMore,
    hasNextPage,
    isFetchingNextPage,
    infiniteScrollThreshold,
    positionPagination,
    positionToolbarAlertBanner,
    positionToolbarDropZone,
    enableTopToolbar,
    enableKeyboardNavigation,
    enableAnimations,
    enableTableHead,
    enableTableFooter,
    direction,
    setDirection,
    enableColumnVirtualization,
    localization,
    renderCaption,
    renderTopToolbar,
  } = dt(table)
  const { refs } = table.dataTable
  const animate = useAnimationsActive(enableAnimations)

  // The paper div feeds `refs.tablePaperRef` and, when given, the consumer's
  // own ref; a plain `ref={refs.tablePaperRef}` would be overwritten by the
  // `{...props}` spread.
  const paperElRef = React.useRef<HTMLDivElement | null>(null)
  const paperRef = React.useCallback(
    (el: HTMLDivElement | null) => {
      assignRef(refs.tablePaperRef, el)
      paperElRef.current = el
      const consumerCleanup = assignRef(refProp, el)
      // Returning a cleanup makes React 19 call it on detach instead of
      // calling this ref with `null`, so a consumer callback ref that returned
      // its own cleanup is honored and never sees `null`.
      return () => {
        assignRef(refs.tablePaperRef, null)
        paperElRef.current = null
        if (typeof consumerCleanup === "function") consumerCleanup()
        else assignRef(refProp, null)
      }
    },
    [refs.tablePaperRef, refProp]
  )

  const gridRef = React.useRef<HTMLDivElement>(null)
  const tableElRef = React.useRef<HTMLTableElement>(null)
  // One callback for the table's lifetime: a new one each render would make
  // React detach and re-attach the surface on every commit, leaving
  // `refs.tableContainerRef` empty while child effects run.
  const setSurfaceRef = React.useCallback(
    // A callback ref runs after render: writing refs there is legal React.
    // eslint-disable-next-line react-hooks/immutability
    (node: HTMLDivElement | null) => {
      gridRef.current = node
      // The exposed container ref is a RefObject, mutable by contract; read
      // through the stable table, so this callback never changes.
      // eslint-disable-next-line react-hooks/immutability
      table.dataTable.refs.tableContainerRef.current = node
    },
    [table]
  )
  // The table re-renders itself on state changes; the component holding the
  // table does not (see `useDataTable`'s `stateSelector`).
  useTableState(table, (state) =>
    Object.fromEntries(
      Object.entries(state).filter(([key]) => !ROW_STATE.has(key))
    )
  )

  // Read the direction the table actually renders in (`dir` on it or any
  // ancestor), for the behaviour CSS cannot mirror: resizing, arrow keys and
  // column virtualization.
  React.useLayoutEffect(() => {
    const el = gridRef.current
    if (!el) return
    const measured = getComputedStyle(el).direction === "rtl" ? "rtl" : "ltr"
    if (measured !== direction) setDirection(measured)
  })
  const { sensors, collisionDetection, handleDragEnd } = useTableDnd(table)
  const accessibility = useDragAnnouncements(table)
  // Inside a DataTableDndProvider the table joins the provider's drag
  // context (rows can then move between tables) instead of having its own.
  const dndScope = useDndScope()
  const dndKey = React.useId()
  const isDropTarget = useIsDropTarget(dndScope ? dndKey : null)
  const dndEntry = {
    table: table as unknown as DataTableInstance<never>,
    collisionDetection,
    handleDragEnd,
    announcements: accessibility.announcements,
    screenReaderInstructions: accessibility.screenReaderInstructions,
  }
  const dndEntryRef = React.useRef(dndEntry)
  React.useLayoutEffect(() => {
    dndEntryRef.current = dndEntry
  })
  React.useEffect(() => {
    if (!dndScope) return
    // The provider reads the latest handlers through this proxy.
    const latest = dndEntryRef
    return dndScope.register(dndKey, {
      get table() {
        return latest.current.table
      },
      collisionDetection: (args) => latest.current.collisionDetection(args),
      handleDragEnd: (event) => latest.current.handleDragEnd(event),
      get announcements() {
        return latest.current.announcements
      },
      get screenReaderInstructions() {
        return latest.current.screenReaderInstructions
      },
    })
  }, [dndScope, dndKey])
  const {
    rowVirtualizer,
    columnVirtualizer,
    virtualItems,
    virtualColumns,
    withColumnSpacers,
    withHeaderSpacers,
  } = useTableVirtualizers(table, gridRef)

  // Keyboard navigation works on display indexes (top, center, bottom rows;
  // visible leaf columns), which it maps back to the virtualizers' indexes to
  // scroll a cell that is not rendered into view.
  const { onKeyDown, onFocus, onBlur, scheduleSync } =
    useGridNavigation<HTMLDivElement>({
      enabled: enableKeyboardNavigation,
      rtl: direction === "rtl",
      ref: gridRef,
      rowCount: () =>
        table.getTopRows().length +
        table.getCenterRows().length +
        table.getBottomRows().length,
      colCount: () => table.getVisibleLeafColumns().length,
      scrollToCell: ({ row, col }) => {
        if (enableRowVirtualization) {
          const center = table.getCenterRows()[row - table.getTopRows().length]
          const index = center
            ? virtualItems.findIndex(
                (item) => !item.detail && item.row.id === center.id
              )
            : -1
          if (index >= 0) rowVirtualizer.scrollToIndex(index)
        }
        if (enableColumnVirtualization) columnVirtualizer.scrollToIndex(col)
      },
    })

  // Infinite scroll: observe a bottom sentinel against the scroll surface and
  // ask the consumer to append the next chunk when it nears the viewport.
  const sentinelRef = React.useRef<HTMLDivElement>(null)
  useInfiniteScroll({
    enabled: enableInfiniteScroll,
    hasNextPage,
    isFetchingNextPage,
    onLoadMore,
    threshold: infiniteScrollThreshold,
    scrollRef: gridRef,
    sentinelRef,
  })

  const hasRows =
    table.getTopRows().length +
      table.getCenterRows().length +
      table.getBottomRows().length >
    0
  const showFooter = enableTableFooter && hasFooter(table)

  // Grid semantics (keyboard navigation makes the table a grid): the full row
  // and column counts, since virtualization and pinning render a subset.
  const isGrid = enableKeyboardNavigation
  const ariaRowCount =
    getHeaderRowCount(table) +
    getDataRowCount(table) +
    (showFooter ? table.getFooterGroups().length : 0)
  const isBusy = isLoading || isSaving

  useRowPinningDisplay({
    table,
    surfaceRef: gridRef,
    stickyHeader: enableStickyHeader,
    stickyFooter: dt(table).enableStickyFooter,
  })

  const fullscreen = useFullscreenModal(paperElRef, isFullscreen, () =>
    setIsFullscreen(false)
  )

  const columnSizing = table.getState().columnSizing
  const columnSizingInfo = table.getState().columnSizingInfo
  const columnSizeVars = React.useMemo(
    () => (enableColumnResizing ? getColumnSizeVars(table) : {}),
    // columnSizing/Info are intentional triggers: recompute vars on resize.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [enableColumnResizing, table, columnSizing, columnSizingInfo]
  )

  const dndContent = (
    <>
      {enableGrouping &&
        (positionToolbarDropZone === "top" ||
          positionToolbarDropZone === "both") && (
          <DropToGroupZoneRegion table={table} config={dt(table)} />
        )}

      <div
        {...mergeProps(
          // The callback ref runs after render, not during it.
          // eslint-disable-next-line react-hooks/refs
          {
            ref: setSurfaceRef,
            onKeyDown,
            onFocus,
            onBlur,
            // Focusable (not a Tab stop) so keyboard navigation can park
            // focus here when the focused cell scrolls out of a virtual
            // window.
            tabIndex: enableKeyboardNavigation ? -1 : undefined,
            "data-slot": "data-table-surface",
            className: cn(
              // This surface is the single scroll container for both axes, so
              // the sticky header/footer engage and the horizontal scrollbar
              // stays pinned to the visible bottom. Neutralize the shadcn
              // <Table> wrapper's own overflow so it doesn't become a second
              // (unbounded) scroll container that breaks sticky positioning.
              "relative overflow-auto rounded-md border bg-card text-card-foreground *:data-[slot=table-container]:overflow-visible",
              "focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:outline-none",
              // MRT-parity default bound: with a sticky header the surface
              // caps near the viewport height, so tall content (long groups,
              // trees, detail panels) scrolls internally under the pinned
              // header instead of stretching the page. A `slotProps.surface`
              // class (via tailwind-merge) or `enableStickyHeader: false` opts
              // out.
              enableStickyHeader &&
                "max-h-[clamp(350px,calc(100dvh-200px),9999px)]",
              enableRowVirtualization && "max-h-150"
            ),
          } as React.ComponentProps<"div">,
          getSlotProps(table, "surface", {})
        )}
      >
        {animate && (
          <div
            data-slot="data-table-motion-layer"
            aria-hidden
            // Sized and clipped to the table while it shows leave copies,
            // so they never extend the scroll area (see `layerClip`).
            className="pointer-events-none absolute top-0 left-0 h-0 w-full overflow-x-visible overflow-y-clip"
          />
        )}
        {showProgressBars && (
          <div
            data-slot="data-table-progress"
            className="absolute inset-x-0 top-0 z-30 h-0.5 overflow-hidden bg-primary/20"
            role="presentation"
          >
            {/* @keyframes can't go in an inline style attribute, so the rule
                    lives in this co-located <style> — keeping the table
                    self-contained (no globals.css / registry CSS needed). The
                    animation itself is applied inline; reduced motion stops it. */}
            <style>
              {
                "@keyframes data-table-progress{from{transform:translateX(-100%)}to{transform:translateX(400%)}}@media (prefers-reduced-motion:reduce){[data-slot=data-table-progress-bar]{animation:none!important}}"
              }
            </style>
            <div
              data-slot="data-table-progress-bar"
              className="h-full w-1/3 bg-primary"
              style={{
                animation: "data-table-progress 1.1s ease-in-out infinite",
              }}
            />
          </div>
        )}

        {/* Before the table: it reads the rows before React updates them. */}
        <DataTableRowMotion
          table={table}
          tableRef={tableElRef}
          active={animate}
        />
        <Table
          {...mergeProps(
            // The ref is forwarded to the element, not read during render.
            // eslint-disable-next-line react-hooks/refs
            {
              ref: tableElRef,
              role: isGrid ? "grid" : undefined,
              "aria-rowcount": isGrid ? ariaRowCount : undefined,
              "aria-colcount": isGrid
                ? table.getVisibleLeafColumns().length
                : undefined,
              "aria-busy": isBusy || undefined,
              style: {
                ...columnSizeVars,
                // Fixed layout makes per-column widths authoritative (auto
                // layout would stretch/redistribute them and ignore a resize).
                // `max(100%, totalSize)` keeps the table at least as wide as the
                // surface: when the columns are narrower than the surface, fixed
                // layout distributes the slack proportionally so they fill it
                // (no trailing empty space); when they outgrow the surface, the
                // table exceeds 100% and scrolls horizontally.
                ...(enableColumnResizing
                  ? { width: `max(100%, ${table.getTotalSize()}px)` }
                  : null),
              },
              className: cn(enableColumnResizing && "table-fixed"),
            } as React.ComponentProps<"table">,
            getSlotProps(table, "table", {})
          )}
        >
          {renderCaption && (
            <TableCaption>{renderCaption({ table })}</TableCaption>
          )}
          {enableTableHead && (
            <HeaderRegion
              table={table}
              config={dt(table)}
              withHeaderSpacers={withHeaderSpacers}
            />
          )}
          <GridSyncContext.Provider value={scheduleSync}>
            <MemoizedDataTableBody
              table={table}
              rowVirtualizer={rowVirtualizer}
              virtualItems={virtualItems}
              virtualColumns={virtualColumns}
              withColumnSpacers={withColumnSpacers}
            />
          </GridSyncContext.Provider>
          {showFooter && (
            <FooterRegion
              table={table}
              config={dt(table)}
              withHeaderSpacers={withHeaderSpacers}
            />
          )}
        </Table>

        {enableInfiniteScroll && hasRows && (
          <>
            {/* Bottom sentinel: when it scrolls near the viewport (within
                    `infiniteScrollThreshold`px) the table asks for the next
                    chunk. Sits after the rendered window, so it works with or
                    without row virtualization. `sticky start-0` keeps it within
                    the horizontal viewport so a wide (horizontally scrolled)
                    table still triggers — the IntersectionObserver checks both
                    axes, and a start-anchored sentinel would otherwise scroll
                    out of the root rect. */}
            <div
              ref={sentinelRef}
              data-slot="data-table-infinite-sentinel"
              aria-hidden
              className="sticky start-0 h-px w-full"
            />
            {isFetchingNextPage && (
              <div
                data-slot="data-table-infinite-loader"
                role="status"
                className="sticky start-0 flex items-center justify-center gap-2 py-3 text-sm text-muted-foreground"
              >
                <span
                  aria-hidden
                  className="size-4 animate-spin rounded-full border-2 border-current border-t-transparent"
                />
                {localization.loadingMore}
              </div>
            )}
          </>
        )}

        {showLoadingOverlay && hasRows && (
          <div className="absolute inset-0 z-10 bg-card/40" aria-hidden />
        )}
      </div>

      {enableGrouping &&
        (positionToolbarDropZone === "bottom" ||
          positionToolbarDropZone === "both") && (
          <DropToGroupZoneRegion table={table} config={dt(table)} />
        )}
    </>
  )

  return (
    <DataTableProvider table={table}>
      <div
        {...mergeProps(
          // The ref is forwarded to the element, not read during render.
          // eslint-disable-next-line react-hooks/refs
          {
            ref: paperRef,
            "data-slot": "data-table",
            className: cn(
              // The timing of this table's own controls (nearest root wins).
              "relative flex w-full flex-col gap-2",
              MOTION_ROOT_CLASS,
              DENSITY_PADDING_VARS,
              isFullscreen &&
                "fixed inset-0 z-50 gap-2 overflow-auto bg-background p-4"
            ),
            "data-density": density,
            "data-animations": animate ? "" : undefined,
            // A row from another table is over this one (see
            // DataTableDndProvider); style it with `data-[drop-target]:…`.
            "data-drop-target": isDropTarget || undefined,
            // Full screen covers the page, so it is a modal dialog meanwhile.
            role: isFullscreen ? "dialog" : undefined,
            "aria-modal": isFullscreen || undefined,
            onKeyDown: fullscreen.onKeyDown,
          } as React.ComponentProps<"div">,
          getSlotProps(table, "root", {}),
          { ...props, className, onKeyDown: onKeyDownProp }
        )}
      >
        <div role="status" aria-live="polite" className="sr-only">
          {isLoading ? localization.loading : ""}
        </div>
        {renderTopToolbar
          ? renderTopToolbar({ table })
          : enableTopToolbar && (
              <ToolbarRegion
                table={table}
                config={dt(table)}
                // Forwarding the exposed ref objects as props (not reading
                // .current during render).
                toolbarRef={refs.topToolbarRef}
                searchInputRef={refs.searchInputRef}
              />
            )}
        {positionToolbarAlertBanner === "top" && (
          <AlertBannerRegion table={table} config={dt(table)} />
        )}

        {enablePagination &&
          (positionPagination === "top" || positionPagination === "both") && (
            <PaginationRegion table={table} config={dt(table)} />
          )}

        <DndKeyContext.Provider value={dndScope ? dndKey : null}>
          {dndScope ? (
            <>
              <TableDropTarget tableKey={dndKey} />
              {dndContent}
            </>
          ) : (
            <DndContext
              sensors={sensors}
              accessibility={accessibility}
              collisionDetection={collisionDetection}
              onDragEnd={handleDragEnd}
            >
              {dndContent}
            </DndContext>
          )}
        </DndKeyContext.Provider>

        {positionToolbarAlertBanner === "bottom" && (
          <AlertBannerRegion table={table} config={dt(table)} />
        )}

        <BottomToolbarRegion table={table} config={dt(table)} />

        <DataTableEditModal table={table} />
      </div>
    </DataTableProvider>
  )
}

"use client"

import {
  DndContext,
  DragOverlay,
  KeyboardSensor,
  PointerSensor,
  closestCenter,
  pointerWithin,
  useDroppable,
  useSensor,
  useSensors,
  type Announcements,
  type CollisionDetection,
  type DragEndEvent,
  type DragOverEvent,
  type DragStartEvent,
  type ScreenReaderInstructions,
} from "@dnd-kit/core"
import { sortableKeyboardCoordinates } from "@dnd-kit/sortable"
import * as React from "react"

import { NON_DATA_COLUMN_IDS } from "./constants"
import { dt } from "./internal"
import type { DataTableRow } from "./table-types"
import type { DataTableInstance } from "./types"

/** What a table registers with a {@link DataTableDndProvider}. */
export interface DndScopeEntry {
  table: DataTableInstance<never>
  collisionDetection: CollisionDetection
  handleDragEnd: (event: DragEndEvent) => void
  announcements: Announcements
  screenReaderInstructions: ScreenReaderInstructions
}

interface DndScope {
  register: (key: string, entry: DndScopeEntry) => () => void
  /** The table key or drop zone a row from another table is over. */
  overTarget: string | null
}

const DndScopeContext = React.createContext<DndScope | null>(null)

/** This table's key inside a provider (null outside one): ids of its
 *  draggables and droppables are prefixed with it, so tables can share ids. */
export const DndKeyContext = React.createContext<string | null>(null)

const SEPARATOR = "::"

/** A drag id unique across the tables of a provider (unchanged outside one). */
export function useDndId() {
  const key = React.useContext(DndKeyContext)
  return React.useCallback(
    (id: string) => (key == null ? id : `${key}${SEPARATOR}${id}`),
    [key]
  )
}

/** The enclosing provider, for a table registering itself. */
export function useDndScope() {
  return React.useContext(DndScopeContext)
}

/** Where a row from one table was dropped, for `onRowDragEnd`. */
export type RowDropTarget =
  | {
      type: "table"
      /** The table it was dropped on. */
      table: DataTableInstance<never>
      /** The row it was dropped on, when it was dropped on one. */
      rowId?: string
    }
  | { type: "zone"; id: string }

const ZONE_PREFIX = `zone${SEPARATOR}`

/**
 * A drop target for rows dragged out of tables in the same
 * {@link DataTableDndProvider}. Attach `setNodeRef` to the element; `isOver`
 * is true while a row is over it. The source table's `onRowDragEnd` receives
 * `{ type: "zone", id }` when a row is dropped there.
 */
export function useDataTableDropZone(id: string) {
  const { setNodeRef, isOver, active } = useDroppable({
    id: `${ZONE_PREFIX}${id}`,
    data: { type: "zone", zoneId: id },
  })
  return {
    setNodeRef,
    isOver: isOver && active?.data.current?.type === "row",
  }
}

type DragData = {
  type?: string
  tableKey?: string
  rowId?: string
  zoneId?: string
}
const dataOf = (item: { data: { current?: unknown } } | null | undefined) =>
  (item?.data.current ?? {}) as DragData

/** A short label for the dragged row: its first data cell's value. */
function rowPreview(row: DataTableRow<never> | undefined) {
  const cell = row
    ?.getVisibleCells()
    .find((c) => !NON_DATA_COLUMN_IDS.has(c.column.id))
  return String(cell?.getValue() ?? row?.id ?? "")
}

/**
 * Lets rows be dragged between the tables inside it, and onto drop zones made
 * with {@link useDataTableDropZone}. The tables share one drag-and-drop
 * context; each table's own reordering (rows, columns, the group zone) keeps
 * working as before. A row dropped on another table or a zone calls the
 * source table's `onRowDragEnd({ row, table, over })`. Works with the
 * keyboard as well as the pointer.
 */
export function DataTableDndProvider({
  children,
}: {
  children: React.ReactNode
}) {
  const entries = React.useRef(new Map<string, DndScopeEntry>())
  const [overTarget, setOverTarget] = React.useState<string | null>(null)
  const [preview, setPreview] = React.useState<string | null>(null)

  const register = React.useCallback((key: string, entry: DndScopeEntry) => {
    entries.current.set(key, entry)
    return () => {
      entries.current.delete(key)
    }
  }, [])

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  )

  const entryOf = (item: { data: { current?: unknown } } | null) => {
    const key = dataOf(item).tableKey
    return key ? entries.current.get(key) : undefined
  }

  // Columns and the group zone stay within their own table. Rows may also go
  // to other tables' rows, other tables themselves, and drop zones: a row hit
  // under the pointer wins, then a zone, then a table; the keyboard (no
  // pointer) moves between rows and zones.
  const collisionDetection: CollisionDetection = (args) => {
    const source = dataOf(args.active)
    const entry = entryOf(args.active)
    if (source.type !== "row") {
      if (!entry) return []
      return entry.collisionDetection({
        ...args,
        droppableContainers: args.droppableContainers.filter(
          (c) => dataOf(c).tableKey === source.tableKey
        ),
      })
    }
    const rowTargets = args.droppableContainers.filter((c) => {
      const data = dataOf(c)
      return (
        data.type === "row" || data.type === "zone" || data.type === "table"
      )
    })
    const hits = pointerWithin({ ...args, droppableContainers: rowTargets })
    const rank = (type?: string) =>
      type === "row" ? 0 : type === "zone" ? 1 : 2
    if (hits.length > 0) {
      const byId = new Map(rowTargets.map((c) => [c.id, c]))
      return [...hits].sort(
        (a, b) =>
          rank(dataOf(byId.get(a.id)).type) - rank(dataOf(byId.get(b.id)).type)
      )
    }
    return closestCenter({
      ...args,
      droppableContainers: rowTargets.filter((c) => dataOf(c).type !== "table"),
    })
  }

  const targetOf = (event: DragOverEvent | DragEndEvent): string | null => {
    const source = dataOf(event.active)
    const over = dataOf(event.over)
    if (source.type !== "row" || !event.over) return null
    if (over.type === "zone") return `${ZONE_PREFIX}${over.zoneId}`
    if (over.tableKey && over.tableKey !== source.tableKey) return over.tableKey
    return null
  }

  const onDragStart = (event: DragStartEvent) => {
    const data = dataOf(event.active)
    if (data.type === "row" && data.tableKey && data.rowId) {
      const table = entries.current.get(data.tableKey)?.table
      setPreview(rowPreview(table?.getCoreRowModel().rowsById[data.rowId]))
    }
  }

  const onDragOver = (event: DragOverEvent) => setOverTarget(targetOf(event))

  const onDragEnd = (event: DragEndEvent) => {
    setOverTarget(null)
    setPreview(null)
    const source = dataOf(event.active)
    const entry = entryOf(event.active)
    if (!entry || !event.over) return
    const over = dataOf(event.over)
    if (
      source.type === "row" &&
      (over.type === "zone" ||
        (over.tableKey && over.tableKey !== source.tableKey))
    ) {
      const table = entry.table
      const row = source.rowId
        ? table.getCoreRowModel().rowsById[source.rowId]
        : undefined
      if (!row) return
      const target: RowDropTarget =
        over.type === "zone"
          ? { type: "zone", id: over.zoneId! }
          : {
              type: "table",
              table: entries.current.get(over.tableKey!)!.table,
              rowId: over.type === "row" ? over.rowId : undefined,
            }
      dt(table).onRowDragEnd?.({ row, table, over: target as never })
      return
    }
    if (over.tableKey === source.tableKey) entry.handleDragEnd(event)
  }

  // Screen-reader text from the table the dragged item belongs to.
  const announcements: Announcements = {
    onDragStart: (e) => entryOf(e.active)?.announcements.onDragStart(e),
    onDragMove: (e) => entryOf(e.active)?.announcements.onDragMove?.(e),
    onDragOver: (e) => entryOf(e.active)?.announcements.onDragOver(e),
    onDragEnd: (e) => entryOf(e.active)?.announcements.onDragEnd(e),
    onDragCancel: (e) => entryOf(e.active)?.announcements.onDragCancel(e),
  }
  const firstEntry = () => entries.current.values().next().value
  const screenReaderInstructions: ScreenReaderInstructions = {
    get draggable() {
      return firstEntry()?.screenReaderInstructions.draggable ?? ""
    },
  }

  return (
    <DndScopeContext.Provider value={{ register, overTarget }}>
      <DndContext
        sensors={sensors}
        collisionDetection={collisionDetection}
        accessibility={{ announcements, screenReaderInstructions }}
        onDragStart={onDragStart}
        onDragOver={onDragOver}
        onDragEnd={onDragEnd}
        onDragCancel={() => {
          setOverTarget(null)
          setPreview(null)
        }}
      >
        {children}
        <DragOverlay dropAnimation={null}>
          {preview != null && (
            <div
              data-slot="data-table-drag-preview"
              className="pointer-events-none max-w-64 truncate rounded-md border bg-popover px-3 py-2 text-sm text-popover-foreground shadow-md"
            >
              {preview}
            </div>
          )}
        </DragOverlay>
      </DndContext>
    </DndScopeContext.Provider>
  )
}

/** Whether a row from another table is over the table with this key. */
export function useIsDropTarget(key: string | null) {
  const scope = React.useContext(DndScopeContext)
  return !!key && scope?.overTarget === key
}

/** The table's own droppable (inside a provider): a row from another table
 *  can be dropped anywhere on it, also when it is empty. */
export function TableDropTarget({ tableKey }: { tableKey: string }) {
  const { setNodeRef } = useDroppable({
    id: `${tableKey}${SEPARATOR}table`,
    data: { type: "table", tableKey },
  })
  return (
    <div
      ref={setNodeRef}
      aria-hidden
      className="pointer-events-none absolute inset-0"
    />
  )
}

import type { RankingInfo } from "@tanstack/match-sorter-utils"
import {
  aggregationFns,
  createExpandedRowModel,
  createFacetedMinMaxValues,
  createFacetedRowModel,
  createFacetedUniqueValues,
  createFilteredRowModel,
  createGroupedRowModel,
  createPaginatedRowModel,
  createSortedRowModel,
  filterFns,
  metaHelper,
  sortFns,
  stockFeatures,
  tableFeatures,
  type AggregationFnDef,
  type BuiltInAggregationFn,
  type BuiltInFilterFn,
  type BuiltInSortFn,
  type FilterFn,
  type RowData,
  type SortFn,
  type TableFeature,
  type TableFeatures,
} from "@tanstack/react-table"

import { toDataTableState } from "../helpers/table-state"
import type { DataTableCoreTable } from "./table-types"
import type { DataTableMethodKey } from "./types"
import { createUiStateFeature, type DataTableUiState } from "./ui-state"

// TanStack types `aggregationFns` with a type alias it doesn't export, which
// declaration emit can't name. A named interface over the same type gives the
// emitted `DataTableFeatures` something it can reference.
// The index signatures let columns name the consumer's own functions
// (`sortFn: "byPriority"`), registered per table from the hook's options.
/* eslint-disable @typescript-eslint/no-explicit-any */
interface BuiltInAggregationFns extends Pick<
  typeof aggregationFns,
  BuiltInAggregationFn
> {
  [name: string]: AggregationFnDef<any, any, any, any>
}
interface FilterFnRegistry extends Pick<typeof filterFns, BuiltInFilterFn> {
  [name: string]: FilterFn<any, any>
}
interface SortFnRegistry extends Pick<typeof sortFns, BuiltInSortFn> {
  [name: string]: SortFn<any, any>
}
/* eslint-enable @typescript-eslint/no-explicit-any */
const builtInAggregationFns: BuiltInAggregationFns = aggregationFns
const filterFnRegistry: FilterFnRegistry = filterFns
const sortFnRegistry: SortFnRegistry = sortFns

// Our instance members (`getState()` in our state shape, `dataTable`, the methods) as a
// TanStack feature, so TanStack's own types for tables built with this feature
// set carry them (see the `Table_FeatureMap` augmentation in `types.ts`). The
// base entry is a placeholder that puts the key on `DataTableFeatures`; each
// table gets the working one from `createDataTableFeatures`.
const dataTableInstanceFeature: TableFeature = {}
// Placeholder for the typed feature map; `createDataTableFeatures` supplies
// the real one (it needs the hook's defaults).
const dataTableUiFeature: TableFeature = {}

// Filtering and sorting are filled per table with our own factories, each
// typed for the hook's `TData`. Their slots take TanStack's own declared type
// for a custom row model (the factory receives the table untyped), which any
// such factory fits. The type `createFilteredRowModel()` infers on its own
// expects `Table<any, any>`, whose filter meta is TanStack's empty
// `FilterMeta`, not our `RankingInfo`, so our factories wouldn't fit it.
type FilteredRowModelSlot = NonNullable<TableFeatures["filteredRowModel"]>
type SortedRowModelSlot = NonNullable<TableFeatures["sortedRowModel"]>
const filteredRowModel: FilteredRowModelSlot = createFilteredRowModel()
const sortedRowModel: SortedRowModelSlot = createSortedRowModel()

// Every built-in feature (MRT parity) plus every row model and the full fn
// registries, so string fns like "sum" / "mean" / "includesString" and the
// "auto" defaults resolve as they did on TanStack v8. `filterMeta` types what
// the fuzzy global filter stores via `addMeta` (match-sorter's RankingInfo).
const baseFeatures = tableFeatures({
  ...stockFeatures,
  dataTableInstanceFeature,
  dataTableUiFeature,
  filteredRowModel,
  sortedRowModel,
  groupedRowModel: createGroupedRowModel(),
  expandedRowModel: createExpandedRowModel(),
  paginatedRowModel: createPaginatedRowModel(),
  facetedRowModel: createFacetedRowModel(),
  facetedUniqueValues: createFacetedUniqueValues(),
  facetedMinMaxValues: createFacetedMinMaxValues(),
  filterFns: filterFnRegistry,
  sortFns: sortFnRegistry,
  aggregationFns: builtInAggregationFns,
  filterMeta: metaHelper<RankingInfo>(),
})

export type DataTableFeatures = typeof baseFeatures

/** Which row-model stages run. Read on every row-model call, so they track
 *  the latest options without recreating the (cached-once) factories. */
export interface RowModelGates {
  pagination: boolean
  grouping: boolean
  expanding: boolean
  faceting: boolean
}

const EMPTY_FACETS = new Map<unknown, number>()

/* eslint-disable @typescript-eslint/no-explicit-any */
interface CustomFns {
  filterFns?: Record<string, FilterFn<any, any>>
  sortFns?: Record<string, SortFn<any, any>>
  aggregationFns?: Record<string, AggregationFnDef<any, any, any, any>>
}

/**
 * The consumer's filter or sort functions as registry entries that call the
 * latest version by name (the registry is built once per table). Each keeps
 * the original's own properties (`autoRemove`, …).
 */
function liveFns<K extends "filterFns" | "sortFns">(
  getCustomFns: () => CustomFns,
  key: K
): NonNullable<CustomFns[K]> {
  const out: Record<string, (...args: any[]) => any> = {}
  for (const [name, fn] of Object.entries(getCustomFns()[key] ?? {})) {
    out[name] = Object.assign(
      (...args: any[]) =>
        ((getCustomFns()[key]?.[name] ?? fn) as (...a: any[]) => any)(...args),
      fn
    )
  }
  return out as NonNullable<CustomFns[K]>
}

/** The consumer's aggregation functions, calling the latest version. */
function liveAggregationFns(
  getCustomFns: () => CustomFns
): NonNullable<CustomFns["aggregationFns"]> {
  const out: NonNullable<CustomFns["aggregationFns"]> = {}
  for (const [name, def] of Object.entries(
    getCustomFns().aggregationFns ?? {}
  )) {
    const latest = () => getCustomFns().aggregationFns?.[name] ?? def
    out[name] = {
      aggregate: (context) => latest().aggregate(context),
      ...(def.merge && {
        merge: (context: any) => (latest().merge ?? def.merge!)(context),
      }),
    }
  }
  return out
}
/* eslint-enable @typescript-eslint/no-explicit-any */

/** Every method the table adds to the TanStack instance. */
export const DATA_TABLE_METHODS = [
  "setDensity",
  "setIsFullscreen",
  "setShowColumnFilters",
  "setShowGlobalFilter",
  "setColumnFilterMode",
  "setGlobalFilterMode",
  "setAdvancedFilter",
  "setShowAdvancedFilterPanel",
  "setEditingCell",
  "setRowDraftValue",
  "beginRowEdit",
  "beginCreate",
  "cancelEdit",
  "autoSizeColumn",
  "autoSizeAllColumns",
] as const satisfies readonly DataTableMethodKey[]

/**
 * The per-table feature set. TanStack builds each row model once, on first
 * use, from whatever is on `features` at that moment, so stages that our
 * options can switch off are wrapped in gates that read the current config
 * instead of being omitted. Filtering and sorting take our own factories (the
 * advanced-filter and fuzzy-rank wrappers).
 */
export function createDataTableFeatures({
  gates,
  getTableInstance,
  filteredRowModel,
  sortedRowModel,
  uiDefaults,
  getCustomFns,
}: {
  /** The consumer's `filterFns` / `sortFns` / `aggregationFns`, added to the
   *  built-in registries so columns can name them. Read once for the names;
   *  each registered function calls the latest version. */
  getCustomFns: () => CustomFns
  gates: () => RowModelGates
  /** Starting values of the UI state slices (see `ui-state.ts`). */
  uiDefaults: () => DataTableUiState
  /** The hook's `dataTable` config, read lazily. */
  getTableInstance: () => unknown
  filteredRowModel: DataTableFeatures["filteredRowModel"]
  sortedRowModel: DataTableFeatures["sortedRowModel"]
}): DataTableFeatures {
  return {
    ...baseFeatures,
    dataTableInstanceFeature: {
      // Render contexts, `row.table` and `column.table` hand out TanStack's
      // core table, not the hook's instance, so mirror our members onto it.
      // Non-enumerable, so they aren't copied onto the hook's instance (which
      // has its own).
      constructTableAPIs: (table) => {
        const core = table as unknown as DataTableCoreTable<RowData>
        Object.defineProperties(core, {
          getState: { value: () => toDataTableState(core.store.state) },
          dataTable: { get: getTableInstance },
          // The methods, for render contexts (`cell: ({ table }) => …`),
          // which hold TanStack's own instance.
          ...Object.fromEntries(
            DATA_TABLE_METHODS.map((key) => [
              key,
              {
                get: () =>
                  (getTableInstance() as Record<string, unknown> | undefined)?.[
                    key
                  ],
              },
            ])
          ),
        })
      },
    },
    dataTableUiFeature: createUiStateFeature(uiDefaults),
    filterFns: {
      ...baseFeatures.filterFns,
      ...liveFns(getCustomFns, "filterFns"),
    },
    sortFns: { ...baseFeatures.sortFns, ...liveFns(getCustomFns, "sortFns") },
    aggregationFns: {
      ...baseFeatures.aggregationFns,
      ...liveAggregationFns(getCustomFns),
    },
    filteredRowModel,
    sortedRowModel,
    groupedRowModel: (table) => {
      const model = baseFeatures.groupedRowModel(table)
      return () => (gates().grouping ? model() : table.getPreGroupedRowModel())
    },
    expandedRowModel: (table) => {
      const model = baseFeatures.expandedRowModel(table)
      return () =>
        gates().expanding ? model() : table.getPreExpandedRowModel()
    },
    paginatedRowModel: (table) => {
      const model = baseFeatures.paginatedRowModel(table)
      return () =>
        gates().pagination ? model() : table.getPrePaginatedRowModel()
    },
    facetedRowModel: (table, columnId) => {
      const model = baseFeatures.facetedRowModel(table, columnId)
      return () => (gates().faceting ? model() : table.getPreFilteredRowModel())
    },
    facetedUniqueValues: (table, columnId) => {
      const values = baseFeatures.facetedUniqueValues(table, columnId)
      return () => (gates().faceting ? values() : EMPTY_FACETS)
    },
    facetedMinMaxValues: (table, columnId) => {
      const values = baseFeatures.facetedMinMaxValues(table, columnId)
      return () => (gates().faceting ? values() : undefined)
    },
  }
}

import type { RowData } from "@tanstack/react-table"

import type { DataTableConfig, DataTableOptionsResolved } from "./types"

/**
 * The table's full configuration for its own parts: `table.dataTable` plus
 * the live UI state, the methods and internal members its public type leaves
 * out (the runtime object is the same).
 */
export function dt<TData extends RowData>(table: {
  dataTable: DataTableOptionsResolved<TData>
}): DataTableConfig<TData> {
  return table.dataTable as unknown as DataTableConfig<TData>
}

import * as React from "react"

/** Default timing for the table's motion (ms and a CSS easing). */
export const MOTION_DEFAULTS = {
  duration: 280,
  durationFast: 160,
  ease: "cubic-bezier(0.22, 1, 0.36, 1)",
} as const

function toMs(value: string, fallback: number): number {
  const v = value.trim()
  if (!v) return fallback
  const n = parseFloat(v)
  if (Number.isNaN(n)) return fallback
  return v.endsWith("ms") ? n : v.endsWith("s") ? n * 1000 : n
}

/** A custom property's value: inline first (cheap), then computed. */
function readVar(el: Element, name: string): string {
  const inline = (el as HTMLElement).style?.getPropertyValue(name)
  if (inline && inline.trim()) return inline
  return getComputedStyle(el).getPropertyValue(name)
}

/** The motion timing in effect on an element (theme overrides included). */
export function readMotionTokens(el: Element | null) {
  if (!el || typeof getComputedStyle === "undefined") {
    return { ...MOTION_DEFAULTS }
  }
  return {
    duration: toMs(
      readVar(el, "--dt-motion-duration"),
      MOTION_DEFAULTS.duration
    ),
    durationFast: toMs(
      readVar(el, "--dt-motion-duration-fast"),
      MOTION_DEFAULTS.durationFast
    ),
    ease: readVar(el, "--dt-motion-ease").trim() || MOTION_DEFAULTS.ease,
  }
}

/** `data-slot` of the short-lived copies of leaving rows (motion layer). */
export const LEAVE_COPY_SLOT = "data-table-leave-copy"

/** Selector suffix that keeps a query out of the leave copies. */
export const NOT_IN_LEAVE_COPY = `:not([data-slot="${LEAVE_COPY_SLOT}"] *)`

const QUERY = "(prefers-reduced-motion: reduce)"

/** Whether the user asked for reduced motion (false where unknown). */
export function getReducedMotion(): boolean {
  return typeof matchMedia === "function" ? matchMedia(QUERY).matches : false
}

/** Subscribe to reduced-motion changes (for useSyncExternalStore). */
export function subscribeReducedMotion(cb: () => void): () => void {
  if (typeof matchMedia !== "function") return () => {}
  const mql = matchMedia(QUERY)
  mql.addEventListener("change", cb)
  return () => mql.removeEventListener("change", cb)
}

/** Whether this table should animate right now. */
export function useAnimationsActive(enabled: boolean): boolean {
  const reduced = React.useSyncExternalStore(
    subscribeReducedMotion,
    getReducedMotion,
    () => false
  )
  return enabled && !reduced
}

/**
 * Set on every table root: the timing its own controls use. With
 * `[data-animations]` it is the motion tokens (`--dt-motion-*`, with the
 * `MOTION_DEFAULTS` as fallbacks), otherwise 0ms. Each root sets it, so the
 * nearest root wins: a non-animated table nested in an animated one (in a
 * detail panel, say) keeps its controls still. Literal strings, so Tailwind
 * sees the classes; a test keeps the numbers in step with `MOTION_DEFAULTS`.
 */
export const MOTION_ROOT_CLASS =
  "[--dt-ctl-duration:0ms] data-[animations]:[--dt-ctl-duration:var(--dt-motion-duration,280ms)] data-[animations]:[--dt-ctl-ease:var(--dt-motion-ease,cubic-bezier(0.22,1,0.36,1))]"

/**
 * Tailwind classes that time a control's CSS transition with its table's
 * control timing (see `MOTION_ROOT_CLASS`): 0ms, so an instant change, when
 * that table does not animate (off, or reduced motion).
 */
export const MOTION_TIMING_CLASS =
  "duration-[var(--dt-ctl-duration,0ms)] ease-[var(--dt-ctl-ease,ease)]"

"use client"

import type { RowData } from "@tanstack/react-table"
import * as React from "react"

import { TooltipProvider } from "@/components/ui/tooltip"

import type { DataTableInstance } from "./types"

const DataTableContext = React.createContext<DataTableInstance<never> | null>(
  null
)

/**
 * Makes `table` available to `useDataTableInstance()` below it, and supplies
 * the tooltip provider the table's parts need. `<DataTable>` renders one; wrap
 * your own layout in it when you compose the exported parts yourself.
 */
export function DataTableProvider<TData extends RowData>({
  table,
  children,
}: {
  table: DataTableInstance<TData>
  children: React.ReactNode
}) {
  return (
    <DataTableContext.Provider
      value={table as unknown as DataTableInstance<never>}
    >
      {/* Radix names the open delay `delayDuration`; Base UI's provider names
          it `delay`. Both ignore foreign props, so passing both (via an
          assertion, since each flavor types only its own) keeps this file
          flavor-neutral for the registry's install-time transform. */}
      <TooltipProvider
        {...({
          delayDuration: 300,
          delay: 300,
        } as Partial<React.ComponentProps<typeof TooltipProvider>>)}
      >
        {children}
      </TooltipProvider>
    </DataTableContext.Provider>
  )
}

/**
 * The table instance from the nearest `<DataTable>` (or `DataTableProvider`),
 * for components rendered inside it — cells, toolbar slots, menus — without
 * passing `table` down. The instance is stable; read state with
 * `table.getState()` and subscribe with `table.Subscribe` to re-render.
 */
export function useDataTableInstance<
  TData extends RowData,
>(): DataTableInstance<TData> {
  const table = React.useContext(DataTableContext)
  if (!table) {
    throw new Error(
      "useDataTableInstance must be used inside <DataTable> or <DataTableProvider>."
    )
  }
  return table as unknown as DataTableInstance<TData>
}

