import { createFilteredRowModel, type RowData } from "@tanstack/react-table"

import type {
  AdvancedFilterGroup,
  AdvancedFilterOperator,
  AdvancedFilterRule,
  FilterVariant,
} from "../core/types"
import type {
  DataTableFeatures,
  DataTableRow,
  DataTableRowModel,
  DataTableRowModelFactory,
} from "../core/table-types"
import { parseDate } from "../helpers/parse-date"

/** A value that contributes nothing to a filter (no cell value / no input). */
function isEmptyValue(value: unknown): boolean {
  return (
    value == null ||
    value === "" ||
    (Array.isArray(value) && value.length === 0)
  )
}

/** Parse a number from a value, or null if it isn't numeric. */
function asNumber(value: unknown): number | null {
  if (typeof value === "number") return Number.isNaN(value) ? null : value
  if (typeof value === "string" && value.trim() !== "") {
    const n = Number(value)
    return Number.isNaN(n) ? null : n
  }
  return null
}

/** Parse an epoch time from a Date or date-ish string, or null. */
function asTime(value: unknown): number | null {
  if (!(value instanceof Date) && typeof value !== "string") return null
  return parseDate(value)?.getTime() ?? null
}

/** Order two cell-ish values: numeric first, then date, then string. */
function compareValues(a: unknown, b: unknown): number {
  const na = asNumber(a)
  const nb = asNumber(b)
  if (na != null && nb != null) return na - nb
  const ta = asTime(a)
  const tb = asTime(b)
  if (ta != null && tb != null) return ta - tb
  return String(a).localeCompare(String(b))
}

/** Loose equality: numeric when both sides parse as numbers, else case- and
 *  whitespace-insensitive string compare (so "Active" matches a "active" rule). */
function looseEquals(cell: unknown, value: unknown): boolean {
  const nc = asNumber(cell)
  const nv = asNumber(value)
  if (nc != null && nv != null) return nc === nv
  if (typeof cell === "boolean" || typeof value === "boolean") {
    return String(cell) === String(value)
  }
  return (
    String(cell).trim().toLowerCase() === String(value).trim().toLowerCase()
  )
}

const VALUELESS_OPERATORS: ReadonlySet<AdvancedFilterOperator> = new Set([
  "isEmpty",
  "isNotEmpty",
])

/**
 * Evaluate one operator against a cell value. Rules whose value input is
 * incomplete are treated as inactive (return true) so a half-typed rule doesn't
 * blank the table. An empty cell only matches `isEmpty` / `notEquals` /
 * `notContains`; every other operator needs a value to compare against.
 */
export function applyOperator(
  cellValue: unknown,
  operator: AdvancedFilterOperator,
  value: unknown,
  value2: unknown
): boolean {
  if (operator === "isEmpty") return isEmptyValue(cellValue)
  if (operator === "isNotEmpty") return !isEmptyValue(cellValue)

  const cellEmpty = isEmptyValue(cellValue)

  if (operator === "between") {
    if (isEmptyValue(value) || isEmptyValue(value2)) return true
    if (cellEmpty) return false
    const lo = compareValues(cellValue, value)
    const hi = compareValues(cellValue, value2)
    return lo >= 0 && hi <= 0
  }

  // A value-requiring operator with no value is inactive.
  if (isEmptyValue(value)) return true

  if (operator === "notEquals")
    return cellEmpty || !looseEquals(cellValue, value)
  if (operator === "notContains") {
    return (
      cellEmpty ||
      !String(cellValue).toLowerCase().includes(String(value).toLowerCase())
    )
  }

  // Remaining operators can't match an empty cell.
  if (cellEmpty) return false

  switch (operator) {
    case "equals":
      return looseEquals(cellValue, value)
    case "contains":
      return String(cellValue)
        .toLowerCase()
        .includes(String(value).toLowerCase())
    case "startsWith":
      return String(cellValue)
        .toLowerCase()
        .startsWith(String(value).toLowerCase())
    case "endsWith":
      return String(cellValue)
        .toLowerCase()
        .endsWith(String(value).toLowerCase())
    case "greaterThan":
      return compareValues(cellValue, value) > 0
    case "greaterThanOrEqual":
      return compareValues(cellValue, value) >= 0
    case "lessThan":
      return compareValues(cellValue, value) < 0
    case "lessThanOrEqual":
      return compareValues(cellValue, value) <= 0
    default:
      return true
  }
}

/** Evaluate a single rule against a row. */
export function evaluateRule<TData extends RowData>(
  row: DataTableRow<TData>,
  rule: AdvancedFilterRule
): boolean {
  return applyOperator(
    row.getValue(rule.columnId),
    rule.operator,
    rule.value,
    rule.value2
  )
}

/** Evaluate the whole group against a row (AND/OR over its rules). */
export function evaluateAdvancedFilterGroup<TData extends RowData>(
  row: DataTableRow<TData>,
  group: AdvancedFilterGroup
): boolean {
  if (group.rules.length === 0) return true
  return group.logic === "and"
    ? group.rules.every((rule) => evaluateRule(row, rule))
    : group.rules.some((rule) => evaluateRule(row, rule))
}

/** Operators offered for a column, by its filter variant. */
export function getOperatorsForVariant(
  variant: FilterVariant
): AdvancedFilterOperator[] {
  switch (variant) {
    case "select":
    case "multi-select":
      return ["equals", "notEquals", "isEmpty", "isNotEmpty"]
    case "range":
    case "range-slider":
      return [
        "equals",
        "notEquals",
        "greaterThan",
        "greaterThanOrEqual",
        "lessThan",
        "lessThanOrEqual",
        "between",
        "isEmpty",
        "isNotEmpty",
      ]
    case "date":
    case "date-range":
    case "datetime":
    case "datetime-range":
    case "time":
    case "time-range":
      return [
        "equals",
        "notEquals",
        "greaterThan",
        "lessThan",
        "between",
        "isEmpty",
        "isNotEmpty",
      ]
    case "checkbox":
      return ["equals"]
    default:
      return [
        "contains",
        "notContains",
        "startsWith",
        "endsWith",
        "equals",
        "notEquals",
        "isEmpty",
        "isNotEmpty",
      ]
  }
}

/** Whether an operator hides its value input(s). */
export function isValuelessOperator(operator: AdvancedFilterOperator): boolean {
  return VALUELESS_OPERATORS.has(operator)
}

/** Rebuild a row model from a filtered set of top-level rows, recomputing the
 *  flat list + id map from the kept rows and their descendants. */
function filterRowModel<TData extends RowData>(
  model: DataTableRowModel<TData>,
  predicate: (row: DataTableRow<TData>) => boolean
): DataTableRowModel<TData> {
  const rows = model.rows.filter(predicate)
  const flatRows: DataTableRow<TData>[] = []
  const rowsById: Record<string, DataTableRow<TData>> = {}
  const collect = (rs: DataTableRow<TData>[]) => {
    for (const row of rs) {
      flatRows.push(row)
      rowsById[row.id] = row
      if (row.subRows.length) collect(row.subRows)
    }
  }
  collect(rows)
  return { rows, flatRows, rowsById }
}

/**
 * Wraps TanStack's filtered row model and additionally applies the advanced
 * filter group on top, so both filter systems are active simultaneously. The
 * group is read through `getGroup` at evaluation time (the factory keeps a
 * stable identity to preserve memoization), and results are cached per
 * underlying model + group so they only recompute when something changes.
 *
 * TanStack memoizes its filtered model on state only, never on the filter
 * functions, so the delegate is rebuilt whenever `options.globalFilterFn`
 * changes identity (e.g. a global filter mode switch or a consumer swapping
 * the fn); the fresh memo then recomputes with the new function.
 *
 * A consumer `globalFilterFn` must therefore be identity-stable: a new function
 * on every render re-filters on every render.
 */
export function createAdvancedFilteredRowModel<TData extends RowData>(
  getGroup: () => AdvancedFilterGroup,
  getGlobalFilterMode: () => unknown = () => undefined
): DataTableRowModelFactory<TData> {
  const base = createFilteredRowModel<DataTableFeatures, TData>()
  return (table) => {
    // TanStack memoizes the filtered model on state only (column filters,
    // global filter, pre-filtered rows), never on the filter functions or our
    // global search mode. Key the delegate on both and rebuild it when either
    // changes; the fresh memo recomputes.
    let delegate = base(table)
    let delegateFor = table.options.globalFilterFn
    let delegateMode = getGlobalFilterMode()
    let cachedFor: DataTableRowModel<TData> | null = null
    let cachedGroup: AdvancedFilterGroup | null = null
    let cached: DataTableRowModel<TData> | null = null
    return () => {
      const mode = getGlobalFilterMode()
      if (
        table.options.globalFilterFn !== delegateFor ||
        mode !== delegateMode
      ) {
        delegate = base(table)
        delegateFor = table.options.globalFilterFn
        delegateMode = mode
      }
      const model = delegate()
      const group = getGroup()
      if (group.rules.length === 0) return model
      if (cached && cachedFor === model && cachedGroup === group) return cached
      cached = filterRowModel(model, (row) =>
        evaluateAdvancedFilterGroup(row, group)
      )
      cachedFor = model
      cachedGroup = group
      return cached
    }
  }
}

import type { RowData } from "@tanstack/react-table"
import { rankItem } from "@tanstack/match-sorter-utils"

import {
  MODE_FNS,
  getModeFn,
  isInactive,
  type FilterMode,
  type GlobalFilterMode,
} from "./filter-modes"
import type { DataTableFilterFn } from "../core/table-types"

/** The consumer's `filterFns`, by name. */
export type CustomFilterFns<TData extends RowData> = Record<
  string,
  DataTableFilterFn<TData>
>

/**
 * Single dynamic filter function assigned to every column via `defaultColumn`.
 * It reads the column's current mode from the provided lookup and dispatches.
 * Mode state lives in the hook; this closure reads it through `getMode` (a ref
 * getter) so the function identity stays stable across renders.
 */
export function createDynamicFilterFn<TData extends RowData>(
  getMode: (columnId: string) => FilterMode,
  getCustomFns: () => CustomFilterFns<TData> = () => ({}),
  getVariant: (columnId: string) => string | undefined = () => undefined
): DataTableFilterFn<TData> {
  const fn: DataTableFilterFn<TData> = (
    row,
    columnId,
    filterValue,
    addMeta
  ) => {
    const mode = getMode(columnId)
    const custom = getCustomFns()[mode]
    if (custom) return custom(row, columnId, filterValue, addMeta)
    const modeFn = getModeFn(mode, getVariant(columnId)) ?? MODE_FNS.contains
    return modeFn(row.getValue(columnId), filterValue)
  }
  // Keep valueless modes active even with a blank value; otherwise drop blanks.
  fn.autoRemove = (value) => isInactive(value)
  return fn
}

/**
 * Mode-aware global search. `fuzzy` uses match-sorter's `rankItem` (MRT's own
 * choice); other modes reuse the column mode functions. Matches across every
 * searchable column (TanStack runs this per column and ORs the results).
 */
export function createGlobalFilterFn<TData extends RowData>(
  getMode: () => GlobalFilterMode,
  getCustomFns: () => CustomFilterFns<TData> = () => ({})
): DataTableFilterFn<TData> {
  const fn: DataTableFilterFn<TData> = (
    row,
    columnId,
    filterValue,
    addMeta
  ) => {
    const value = String(filterValue ?? "")
    if (value === "") return true
    const mode = getMode()
    const custom = getCustomFns()[mode]
    if (custom) return custom(row, columnId, value, addMeta)
    if (mode === "fuzzy") {
      // Stash the rank so `enableGlobalFilterRankedResults` can order rows by
      // match quality; `rankGlobalFuzzy` reads it back off columnFiltersMeta.
      const itemRank = rankItem(row.getValue(columnId), value)
      addMeta?.(itemRank)
      return itemRank.passed
    }
    const modeFn = getModeFn(mode) ?? MODE_FNS.contains
    return modeFn(row.getValue(columnId), value)
  }
  fn.autoRemove = (value) => value == null || value === ""
  return fn
}

// Barrel for the filtering engine. Internal modules:
//   filter-modes.ts     — mode predicates (MODE_FNS), value coercers, mode sets
//   filter-factories.ts — the per-column / global dynamic FilterFn factories
//   ranked-row-model.ts — fuzzy-rank sorted row model
//   variant-modes.ts    — variant → default mode + mode-menu options
// Most of the module imports from here ("../fns/filter-fns"); keep this surface
// stable when adding to the sub-modules.

export {
  MODE_FNS,
  GLOBAL_FILTER_MODES,
  VALUELESS_MODES,
  SUBSTRING_MODES,
  getModeFn,
  isInactive,
  type BuiltInFilterMode,
  type BuiltInGlobalFilterMode,
  type FilterMode,
  type GlobalFilterMode,
} from "./filter-modes"
export {
  createDynamicFilterFn,
  createGlobalFilterFn,
  type CustomFilterFns,
} from "./filter-factories"
export { rankGlobalFuzzy, createRankedSortedRowModel } from "./ranked-row-model"
export { defaultModeForVariant, modeOptionsForVariant } from "./variant-modes"

/** Built-in global-search modes offered in the global filter-mode menu. */
export type BuiltInGlobalFilterMode =
  "fuzzy" | "contains" | "startsWith" | "endsWith" | "equals"

/** The global search mode menu's default modes. */
export const GLOBAL_FILTER_MODES: readonly BuiltInGlobalFilterMode[] = [
  "fuzzy",
  "contains",
  "startsWith",
  "endsWith",
  "equals",
]

/** A global-search mode: a built-in one, or the name of a custom function in
 *  the `filterFns` option. */
export type GlobalFilterMode = BuiltInGlobalFilterMode | (string & {})

/** A filter mode: a built-in one, or the name of a custom function in the
 *  `filterFns` option. */
export type FilterMode = BuiltInFilterMode | (string & {})

/** The built-in filter modes across variants. */
export type BuiltInFilterMode =
  // text
  | "contains"
  | "equals"
  | "notEquals"
  | "startsWith"
  | "endsWith"
  | "fuzzy"
  // shared
  | "empty"
  | "notEmpty"
  // numeric
  | "between"
  | "betweenInclusive"
  | "greaterThan"
  | "greaterThanOrEqualTo"
  | "lessThan"
  | "lessThanOrEqualTo"
  // date
  | "before"
  | "after"
  | "betweenDates"
  // fixed (no mode menu)
  | "equalsString"
  | "arrIncludesSome"
  | "equalsBool"

import { rankItem } from "@tanstack/match-sorter-utils"
import { endOfDay, isAfter, isBefore, startOfDay } from "date-fns"

import { parseDate } from "../helpers/parse-date"

const str = (v: unknown): string => (v == null ? "" : String(v))
const lower = (v: unknown): string => str(v).toLowerCase()
const num = (v: unknown): number =>
  typeof v === "number" ? v : parseFloat(str(v))
const isBlank = (v: unknown): boolean =>
  v == null || v === "" || (Array.isArray(v) && v.length === 0)
const toDate = parseDate

// Each entry: (row value already resolved) decides inclusion. The dynamic
// `filterFn` resolves `row.getValue(columnId)` and dispatches by mode.
type ModeFn = (cellValue: unknown, filterValue: unknown) => boolean

export const MODE_FNS: Record<BuiltInFilterMode, ModeFn> = {
  contains: (cell, val) => lower(cell).includes(lower(val)),
  equals: (cell, val) => lower(cell) === lower(val),
  notEquals: (cell, val) => lower(cell) !== lower(val),
  startsWith: (cell, val) => lower(cell).startsWith(lower(val)),
  endsWith: (cell, val) => lower(cell).endsWith(lower(val)),
  fuzzy: (cell, val) => rankItem(str(cell), str(val)).passed,

  empty: (cell) => isBlank(cell),
  notEmpty: (cell) => !isBlank(cell),

  greaterThan: (cell, val) => num(cell) > num(val),
  greaterThanOrEqualTo: (cell, val) => num(cell) >= num(val),
  lessThan: (cell, val) => num(cell) < num(val),
  lessThanOrEqualTo: (cell, val) => num(cell) <= num(val),
  between: (cell, val) => betweenNum(cell, val, false),
  betweenInclusive: (cell, val) => betweenNum(cell, val, true),

  before: (cell, val) => {
    const c = toDate(cell)
    const v = toDate(val)
    return c != null && v != null && isBefore(c, startOfDay(v))
  },
  after: (cell, val) => {
    const c = toDate(cell)
    const v = toDate(val)
    return c != null && v != null && isAfter(c, endOfDay(v))
  },
  betweenDates: (cell, val) => {
    const c = toDate(cell)
    const range = (Array.isArray(val) ? val : []) as unknown[]
    const from = toDate(range[0])
    const to = toDate(range[1])
    if (c == null) return false
    if (from != null && isBefore(c, startOfDay(from))) return false
    if (to != null && isAfter(c, endOfDay(to))) return false
    return from != null || to != null
  },

  equalsString: (cell, val) => str(cell) === str(val),
  arrIncludesSome: (cell, val) => {
    const arr = (Array.isArray(val) ? val : []) as unknown[]
    if (arr.length === 0) return true
    return arr.map(str).includes(str(cell))
  },
  equalsBool: (cell, val) => Boolean(cell) === Boolean(val),
}

function betweenNum(cell: unknown, val: unknown, inclusive: boolean): boolean {
  const arr = (Array.isArray(val) ? val : []) as unknown[]
  const n = num(cell)
  if (Number.isNaN(n)) return false
  const min = arr[0] === "" || arr[0] == null ? null : num(arr[0])
  const max = arr[1] === "" || arr[1] == null ? null : num(arr[1])
  if (min != null && (inclusive ? n < min : n <= min)) return false
  if (max != null && (inclusive ? n > max : n >= max)) return false
  return min != null || max != null
}

const TIME_OF_DAY = /^(\d{1,2}):(\d{2})(?::\d{2}(?:\.\d+)?)?$/

/** Minutes since midnight from a Date, an "HH:mm[:ss]" string or a
 *  date-time string; null when it is none of those. */
function toMinutesOfDay(value: unknown): number | null {
  if (typeof value === "string") {
    const match = TIME_OF_DAY.exec(value.trim())
    if (match) return Number(match[1]) * 60 + Number(match[2])
  }
  const date = toDate(value)
  return date ? date.getHours() * 60 + date.getMinutes() : null
}

/** A date-time to the minute (epoch minutes), or null. */
function toMinute(value: unknown): number | null {
  const date = toDate(value)
  return date ? Math.floor(date.getTime() / 60_000) : null
}

/** The date modes, comparing values converted by `convert` (inclusive
 *  ranges, open-ended when one bound is blank). */
function comparedModes(
  convert: (value: unknown) => number | null
): Partial<Record<BuiltInFilterMode, ModeFn>> {
  const both = (cell: unknown, val: unknown) => {
    const c = convert(cell)
    const v = convert(val)
    return c != null && v != null ? ([c, v] as const) : null
  }
  return {
    equals: (cell, val) => {
      const pair = both(cell, val)
      return pair != null && pair[0] === pair[1]
    },
    notEquals: (cell, val) => {
      const pair = both(cell, val)
      return pair == null || pair[0] !== pair[1]
    },
    before: (cell, val) => {
      const pair = both(cell, val)
      return pair != null && pair[0] < pair[1]
    },
    after: (cell, val) => {
      const pair = both(cell, val)
      return pair != null && pair[0] > pair[1]
    },
    betweenDates: (cell, val) => {
      const c = convert(cell)
      const range = (Array.isArray(val) ? val : []) as unknown[]
      const from = convert(range[0])
      const to = convert(range[1])
      if (c == null || (from == null && to == null)) return false
      return (from == null || c >= from) && (to == null || c <= to)
    },
  }
}

const DATETIME_MODE_FNS = comparedModes(toMinute)
const TIME_MODE_FNS = comparedModes(toMinutesOfDay)

/** Variants whose values compare differently from the mode's default: date
 *  modes on date-times compare to the minute, on times by time of day. */
export const VARIANT_MODE_FNS: Readonly<
  Record<string, Partial<Record<BuiltInFilterMode, ModeFn>>>
> = {
  datetime: DATETIME_MODE_FNS,
  "datetime-range": DATETIME_MODE_FNS,
  time: TIME_MODE_FNS,
  "time-range": TIME_MODE_FNS,
}

/** The built-in function for a mode, if it is one. */
export function getModeFn(mode: string, variant?: string): ModeFn | undefined {
  if (!Object.hasOwn(MODE_FNS, mode)) return undefined
  const builtIn = mode as BuiltInFilterMode
  return (variant && VARIANT_MODE_FNS[variant]?.[builtIn]) || MODE_FNS[builtIn]
}

/** Modes that activate without a typed value (they test the cell only). */
export const VALUELESS_MODES: ReadonlySet<FilterMode> = new Set([
  "empty",
  "notEmpty",
])

/** Modes whose string value should drive match highlighting in cells. */
export const SUBSTRING_MODES: ReadonlySet<FilterMode> = new Set([
  "contains",
  "startsWith",
  "endsWith",
  "equals",
  "fuzzy",
])

/**
 * A value is "inactive" (filter should auto-remove) when blank — unless the
 * mode is valueless, where any truthy sentinel keeps it active.
 */
export function isInactive(value: unknown): boolean {
  if (Array.isArray(value)) return value.every((v) => v == null || v === "")
  return value == null || value === ""
}

import { createSortedRowModel, type RowData } from "@tanstack/react-table"
import type { RankingInfo } from "@tanstack/match-sorter-utils"
import type {
  DataTableCoreTable,
  DataTableFeatures,
  DataTableRow,
  DataTableRowModel,
  DataTableRowModelFactory,
} from "../core/table-types"

/**
 * Descending comparator over the best fuzzy rank a row earned across the
 * columns the global search ran on. Drives `enableGlobalFilterRankedResults`.
 * Ranks are written to `row.columnFiltersMeta` by the fuzzy branch of
 * `createGlobalFilterFn`; only that branch writes meta, so this never picks up
 * per-column filter state.
 */
export function rankGlobalFuzzy<TData extends RowData>(
  rowA: DataTableRow<TData>,
  rowB: DataTableRow<TData>
): number {
  const best = (row: DataTableRow<TData>): number => {
    let max = -Infinity
    for (const meta of Object.values(row.columnFiltersMeta)) {
      const rank = (meta as RankingInfo | undefined)?.rank
      if (rank != null && rank > max) max = rank
    }
    return max === -Infinity ? 0 : max
  }
  return best(rowB) - best(rowA)
}

/**
 * Wraps TanStack's sorted row model. When `isActive(table)` is true (the caller
 * decides: fuzzy global search on, no user sort, no grouping/expansion), the
 * top-level rows are re-ordered by best fuzzy rank; otherwise the normal sorted
 * model passes through untouched. Re-ordering at the sorted-model layer means
 * pagination, pinning, and the body all observe the ranked order with no extra
 * wiring. The result is cached per underlying model object, so the sort only
 * re-runs when filtering/sorting/data actually change.
 */
export function createRankedSortedRowModel<TData extends RowData>(
  isActive: (table: DataTableCoreTable<TData>) => boolean
): DataTableRowModelFactory<TData> {
  const base = createSortedRowModel<DataTableFeatures, TData>()
  return (table) => {
    const delegate = base(table)
    let cachedFor: DataTableRowModel<TData> | null = null
    let cached: DataTableRowModel<TData> | null = null
    return () => {
      const model = delegate()
      if (!isActive(table)) return model
      if (cached && cachedFor === model) return cached
      cached = { ...model, rows: [...model.rows].sort(rankGlobalFuzzy) }
      cachedFor = model
      return cached
    }
  }
}

/** Best-effort column id used to key per-column state (e.g. filter modes). */
export function columnKey(def: {
  id?: string
  accessorKey?: unknown
}): string | null {
  if (def.id) return def.id
  if (typeof def.accessorKey === "string") return def.accessorKey
  return null
}

import type { RowData } from "@tanstack/react-table"
import type { DataTableColumn } from "../core/table-types"

/** Best-effort human label for a column: explicit meta.label, else its
 *  string header, else its id. */
export function getColumnLabel<TData extends RowData, TValue>(
  column: DataTableColumn<TData, TValue>
): string {
  const meta = column.columnDef.meta
  if (meta?.label) return meta.label
  const header = column.columnDef.header
  if (typeof header === "string" && header.length > 0) return header
  return column.id
}

import type { OnChangeFn, RowData } from "@tanstack/react-table"

import type { DataTableColumn } from "../core/table-types"

// Column pinning speaks physical left/right in our API. TanStack v9 speaks
// logical start/end; this module is the only place that translates, so the
// rest of the table never sees TanStack's pinning vocabulary.

export type PinSide = "left" | "right"

/** Column pinning state as consumers pass it (`initialState`, `state`). */
export interface DataTableColumnPinningState {
  left?: string[]
  right?: string[]
}

/** TanStack v9's column pinning state shape. */
export interface CoreColumnPinningState {
  start: string[]
  end: string[]
}

export function getPinSide<TData extends RowData, TValue>(
  column: DataTableColumn<TData, TValue>
): PinSide | false {
  const pinned = column.getIsPinned()
  return pinned === "start" ? "left" : pinned === "end" ? "right" : false
}

export function pinColumn<TData extends RowData, TValue>(
  column: DataTableColumn<TData, TValue>,
  side: PinSide | false
): void {
  column.pin(side === "left" ? "start" : side === "right" ? "end" : false)
}

/** Sticky offset from the pinned edge, so stacked pinned columns line up. */
export function getPinOffset<TData extends RowData, TValue>(
  column: DataTableColumn<TData, TValue>,
  side: PinSide
): number {
  return side === "left" ? column.getStart("start") : column.getAfter("end")
}

/** The boundary column of a pinned group: last on the left, first on the right. */
export function isPinnedEdgeColumn<TData extends RowData, TValue>(
  column: DataTableColumn<TData, TValue>,
  side: PinSide
): boolean {
  return side === "left"
    ? column.getIsLastColumn("start")
    : column.getIsFirstColumn("end")
}

export function toCorePinning(
  state: DataTableColumnPinningState
): CoreColumnPinningState {
  return { start: state.left ?? [], end: state.right ?? [] }
}

export function fromCorePinning(
  state: Partial<CoreColumnPinningState>
): Required<DataTableColumnPinningState> {
  return { left: state.start ?? [], right: state.end ?? [] }
}

/** Adapts a consumer's left/right change handler to TanStack's start/end one.
 *  Always hands the consumer a functional updater (TanStack's convention). */
export function mapPinningUpdater(
  onChange: OnChangeFn<DataTableColumnPinningState>
): OnChangeFn<CoreColumnPinningState> {
  return (updater) =>
    onChange((prev) =>
      fromCorePinning(
        typeof updater === "function" ? updater(toCorePinning(prev)) : updater
      )
    )
}

import type { RowData } from "@tanstack/react-table"

import type { DataTableColumnDef } from "../core/table-types"
import type { DisplayColumnId } from "../core/types"

type ColumnOverride<TData extends RowData> = Partial<
  DataTableColumnDef<TData, unknown>
>

export interface DisplayColumnOptions<TData extends RowData> {
  defaultDisplayColumn?: ColumnOverride<TData>
  displayColumnDefOptions?: Partial<
    Record<DisplayColumnId, ColumnOverride<TData>>
  >
}

/**
 * A string that changes only when the options' shape or plain values change.
 * Functions count as equal, since `applyDisplayColumnOptions` reads them
 * live, so options written inline don't rebuild the columns every render.
 */
export function displayColumnOptionsKey<TData extends RowData>(
  options: DisplayColumnOptions<TData>
): string {
  // Only plain objects and arrays are walked: React elements, DOM nodes and
  // class instances (which can be circular) count as equal, like functions.
  return JSON.stringify(options, (_key, value: unknown) => {
    if (typeof value === "function") return "ƒ"
    if (value && typeof value === "object" && !Array.isArray(value)) {
      const proto = Object.getPrototypeOf(value)
      if (
        (proto !== Object.prototype && proto !== null) ||
        "$$typeof" in value
      ) {
        return "◇"
      }
    }
    return value
  })
}

/**
 * An injected column with the consumer's overrides: `defaultDisplayColumn`,
 * then its own `displayColumnDefOptions` entry. `meta` merges with the
 * column's; the id never changes. Function props call the latest options
 * through `getOptions`, so they stay current while the definition is reused.
 */
export function applyDisplayColumnOptions<TData extends RowData>(
  column: DataTableColumnDef<TData, unknown>,
  getOptions: () => DisplayColumnOptions<TData>
): DataTableColumnDef<TData, unknown> {
  const id = column.id as DisplayColumnId
  const pick = (options: DisplayColumnOptions<TData>) => [
    options.defaultDisplayColumn,
    options.displayColumnDefOptions?.[id],
  ]
  const overrides = pick(getOptions())
  if (!overrides.some(Boolean)) return column

  const merged: Record<string, unknown> = { ...column }
  for (const override of overrides) {
    if (!override) continue
    for (const [key, value] of Object.entries(override)) {
      if (key === "id") continue
      if (key === "meta") {
        merged.meta = { ...(merged.meta as object), ...(value as object) }
      } else if (typeof value === "function") {
        // Call whichever override supplies this key now (per-id wins).
        merged[key] = (...args: unknown[]) => {
          const latest = pick(getOptions())
            .map((o) => (o as Record<string, unknown> | undefined)?.[key])
            .filter((fn) => typeof fn === "function")
            .pop() as ((...args: unknown[]) => unknown) | undefined
          return latest?.(...args)
        }
      } else {
        merged[key] = value
      }
    }
  }
  return merged as unknown as DataTableColumnDef<TData, unknown>
}

import type { RowData } from "@tanstack/react-table"

import type { DataTableColumn, DataTableRow } from "../core/table-types"
import type { DataTableFilterOption, DataTableInstance } from "../core/types"

/** A column's select options for editing `row` (undefined when creating):
 *  `meta.editSelectOptions` (resolved when a function), else
 *  `meta.filterSelectOptions`. */
export function getEditSelectOptions<TData extends RowData>(
  column: DataTableColumn<TData, unknown>,
  table: DataTableInstance<TData>,
  row?: DataTableRow<TData>
): DataTableFilterOption[] | undefined {
  const meta = column.columnDef.meta
  const options = meta?.editSelectOptions
  if (typeof options === "function") return options({ row, column, table })
  return options ?? meta?.filterSelectOptions
}

import type { RowData } from "@tanstack/react-table"

import type { DataTableInstance } from "../core/types"
import { defaultModeForVariant, type FilterMode } from "../fns/filter-fns"
import type { DataTableColumn } from "../core/table-types"
import { dt } from "../core/internal"

/** Effective filter mode for a column: explicit selection → meta → variant default. */
export function getEffectiveMode<TData extends RowData, TValue>(
  column: DataTableColumn<TData, TValue>,
  table: DataTableInstance<TData>
): FilterMode {
  const variant = column.columnDef.meta?.filterVariant ?? "text"
  return (
    dt(table).columnFilterModes[column.id] ??
    column.columnDef.meta?.filterMode ??
    defaultModeForVariant(variant)
  )
}

import type { RowData } from "@tanstack/react-table"

import type { DataTableColumnDef } from "../core/table-types"

/** Leaf column defs in document order, descending through header groups
 *  (`columns: [...]`). Per-column state keyed by column id must be derived
 *  from leaves, or a column nested in a group silently gets the defaults. */
export function flattenLeafColumns<TData extends RowData>(
  columns: ReadonlyArray<DataTableColumnDef<TData, unknown>>
): DataTableColumnDef<TData, unknown>[] {
  const leaves: DataTableColumnDef<TData, unknown>[] = []
  for (const def of columns) {
    const children = (def as { columns?: DataTableColumnDef<TData, unknown>[] })
      .columns
    if (children && children.length > 0) {
      leaves.push(...flattenLeafColumns(children))
    } else {
      leaves.push(def)
    }
  }
  return leaves
}

/** A whole number in the language's own digits (Persian `۱۲`, Nepali `१२`),
 *  without thousands separators, for compact counters such as page buttons
 *  and row numbers. */
export function formatInteger(value: number, language: string): string {
  return value.toLocaleString(language, { useGrouping: false })
}

import type { RowData } from "@tanstack/react-table"

import type { DataTableInstance } from "../core/types"
import { dt } from "../core/internal"

/** Whether the per-column filter row renders under the headers. */
export function isFilterRowVisible<TData extends RowData>(
  table: DataTableInstance<TData>
): boolean {
  const { enableColumnFilters, showColumnFilters, columnFilterDisplayMode } =
    dt(table)
  return (
    enableColumnFilters &&
    showColumnFilters &&
    columnFilterDisplayMode === "subheader" &&
    table.getAllColumns().some((column) => column.getCanFilter())
  )
}

/** Rows in `<thead>`: one per header group, plus the filter row. Body rows
 *  are numbered after these for `aria-rowindex`. */
export function getHeaderRowCount<TData extends RowData>(
  table: DataTableInstance<TData>
): number {
  if (!dt(table).enableTableHead) return 0
  return table.getHeaderGroups().length + (isFilterRowVisible(table) ? 1 : 0)
}

/** Data rows in display order (top-pinned, center, bottom-pinned). */
export function getDataRowCount<TData extends RowData>(
  table: DataTableInstance<TData>
): number {
  return (
    table.getTopRows().length +
    table.getCenterRows().length +
    table.getBottomRows().length
  )
}

import type { RowData } from "@tanstack/react-table"

import { DISPLAY_COLUMN_IDS } from "../core/constants"
import type { ColumnFilterDisplayMode, DataTableInstance } from "../core/types"
import type { DataTableColumn, DataTableColumnDef } from "../core/table-types"
import { getPinSide } from "./column-pinning"
import { dt } from "../core/internal"

/**
 * Feature flags that decide which affordances a column header renders. Single
 * source of truth so the autosize measurement, the per-column minimum width,
 * and the header components themselves can never disagree about what shows (the
 * disagreement that let controls get clipped under the fixed table layout).
 */
export interface HeaderControlsOptions {
  enableColumnActions: boolean
  enableColumnOrdering: boolean
  enableGrouping: boolean
  enableColumnPinning: boolean
  enableColumnVirtualization: boolean
  columnFilterDisplayMode: ColumnFilterDisplayMode
}

// size-7 (28px) icon button + the header's gap-0.5 (2px) between affordances.
const ICON_BUTTON_WIDTH = 30
// The sort glyph + its gap, rendered inside the label button.
const SORT_INDICATOR_WIDTH = 20
// Horizontal cell padding + a sliver of label, so a column never collapses to
// controls-only. A coarse constant: the exact (density-dependent) padding isn't
// knowable without the DOM, and over-reserving a few px is harmless.
const LABEL_AND_PADDING_MIN = 56
// Rough width of one uppercase, letter-spaced header character at the header's
// text-xs scale. Deterministic (no canvas) so the SSR and client size vars
// agree — a canvas measurement would differ between them and warn on hydration.
const HEADER_CHAR_WIDTH = 8.5
// Horizontal cell padding reserved around the header label.
const HEADER_PADDING = 24
// Cap so a very long header can't create an enormous default column.
const HEADER_LABEL_MAX = 260

/** Build {@link HeaderControlsOptions} from a live table's resolved config. */
export function headerControlsOptionsFromTable<TData extends RowData>(
  table: DataTableInstance<TData>
): HeaderControlsOptions {
  const config = dt(table)
  return {
    enableColumnActions: config.enableColumnActions,
    enableColumnOrdering: config.enableColumnOrdering,
    enableGrouping: config.enableGrouping,
    enableColumnPinning: config.enableColumnPinning,
    enableColumnVirtualization: config.enableColumnVirtualization,
    columnFilterDisplayMode: config.columnFilterDisplayMode,
  }
}

/** Whether the column-reorder drag grip renders in this column's header. */
export function shouldShowColumnDragGrip<TData extends RowData, TValue>(
  column: DataTableColumn<TData, TValue>,
  opts: HeaderControlsOptions
): boolean {
  if (DISPLAY_COLUMN_IDS.has(column.id)) return false
  return (
    (opts.enableColumnOrdering ||
      (opts.enableGrouping && column.getCanGroup())) &&
    !getPinSide(column)
  )
}

/** Whether the column-actions (⋮) trigger renders in this column's header. */
export function shouldShowColumnActions<TData extends RowData, TValue>(
  column: DataTableColumn<TData, TValue>,
  opts: HeaderControlsOptions
): boolean {
  return (
    opts.enableColumnActions &&
    column.columnDef.meta?.enableColumnActions !== false &&
    (column.getCanSort() ||
      column.getCanHide() ||
      column.getCanFilter() ||
      (opts.enableColumnPinning && column.getCanPin()) ||
      (opts.enableGrouping && column.getCanGroup()))
  )
}

/** Whether the popover filter button renders in this column's header. */
export function shouldShowColumnFilterButton<TData extends RowData, TValue>(
  column: DataTableColumn<TData, TValue>,
  opts: HeaderControlsOptions
): boolean {
  return opts.columnFilterDisplayMode === "popover" && column.getCanFilter()
}

/**
 * Width (px) to reserve beside the label for the header affordances that will
 * actually render for this column — the sort indicator plus any of the drag
 * grip, actions trigger, and filter button. Used as `extraWidth` when
 * autosizing and as the controls portion of {@link getHeaderControlsMinWidth}.
 */
export function getHeaderControlsWidth<TData extends RowData, TValue>(
  column: DataTableColumn<TData, TValue>,
  opts: HeaderControlsOptions
): number {
  return (
    (column.getCanSort() ? SORT_INDICATOR_WIDTH : 0) +
    (shouldShowColumnDragGrip(column, opts) ? ICON_BUTTON_WIDTH : 0) +
    (shouldShowColumnActions(column, opts) ? ICON_BUTTON_WIDTH : 0) +
    (shouldShowColumnFilterButton(column, opts) ? ICON_BUTTON_WIDTH : 0)
  )
}

// ----------------------------------------------------------------------------
// ColumnDef-based reservation
//
// The functions above read a *built* column (capabilities via getCan*). The
// size/minSize floors, however, must be baked into the column defs *before*
// `useReactTable` — a pure transform, so React Compiler keeps it and SSR/client
// agree (mutating a built column in an effect/memo gets dead-code-eliminated on
// the client and desyncs hydration). These mirror the predicates above but
// derive capabilities from the def + flags. They err toward reserving (a column
// counts as sortable/filterable unless explicitly disabled) so the reservation
// is always ≥ what actually renders — controls can never end up clipped.
// ----------------------------------------------------------------------------

type AnyColumnDef<TData extends RowData> = DataTableColumnDef<
  TData,
  unknown
> & {
  accessorKey?: unknown
  accessorFn?: unknown
  columns?: unknown
  enableSorting?: boolean
  enableHiding?: boolean
  enableColumnFilter?: boolean
  enableGrouping?: boolean
  enablePinning?: boolean
  minSize?: number
  size?: number
}

function hasAccessor<TData extends RowData>(def: AnyColumnDef<TData>): boolean {
  return def.accessorKey != null || def.accessorFn != null
}

function defLabel<TData extends RowData>(def: AnyColumnDef<TData>): string {
  if (def.meta?.label) return def.meta.label
  if (typeof def.header === "string" && def.header.length > 0) return def.header
  if (typeof def.accessorKey === "string") return def.accessorKey
  return ""
}

function getColumnDefControlsWidth<TData extends RowData>(
  def: AnyColumnDef<TData>,
  opts: HeaderControlsOptions
): number {
  const canSort = def.enableSorting !== false && hasAccessor(def)
  const canHide = def.enableHiding !== false
  const canFilter = def.enableColumnFilter !== false && hasAccessor(def)
  const canGroup = def.enableGrouping !== false && hasAccessor(def)
  const canPin = def.enablePinning !== false

  const showGrip =
    opts.enableColumnOrdering || (opts.enableGrouping && canGroup)
  const showActions =
    opts.enableColumnActions &&
    def.meta?.enableColumnActions !== false &&
    (canSort ||
      canHide ||
      canFilter ||
      (opts.enableColumnPinning && canPin) ||
      (opts.enableGrouping && canGroup))
  const showFilter = opts.columnFilterDisplayMode === "popover" && canFilter

  return (
    (canSort ? SORT_INDICATOR_WIDTH : 0) +
    (showGrip ? ICON_BUTTON_WIDTH : 0) +
    (showActions ? ICON_BUTTON_WIDTH : 0) +
    (showFilter ? ICON_BUTTON_WIDTH : 0)
  )
}

/** {@link getHeaderControlsMinWidth} computed from a column def (pre-build). */
export function getColumnDefMinWidth<TData extends RowData>(
  def: DataTableColumnDef<TData, unknown>,
  opts: HeaderControlsOptions
): number {
  return LABEL_AND_PADDING_MIN + getColumnDefControlsWidth(def, opts)
}

/** {@link getHeaderPreferredWidth} computed from a column def (pre-build). */
export function getColumnDefPreferredWidth<TData extends RowData>(
  def: DataTableColumnDef<TData, unknown>,
  opts: HeaderControlsOptions
): number {
  const labelWidth = Math.min(
    HEADER_LABEL_MAX,
    defLabel(def).length * HEADER_CHAR_WIDTH
  )
  return Math.ceil(
    HEADER_PADDING + labelWidth + getColumnDefControlsWidth(def, opts)
  )
}

/** True for a leaf user/data column def (not an injected display column or a
 *  header group) — the only defs that get a control-aware size/minSize. */
export function isDataColumnDef<TData extends RowData>(
  def: DataTableColumnDef<TData, unknown>
): boolean {
  const anyDef = def as AnyColumnDef<TData>
  if (Array.isArray(anyDef.columns)) return false
  if (def.id != null && DISPLAY_COLUMN_IDS.has(def.id)) return false
  return hasAccessor(anyDef)
}

import type { RowData } from "@tanstack/react-table"
import type { DataTableColumn, DataTableRow } from "../core/table-types"

/**
 * A column is editable when it has an accessor and isn't opted out via
 * `meta.enableEditing` — `false`, or a function returning false for `row`.
 * Without a row (the create form) a function counts as editable.
 */
export function isColumnEditable<TData extends RowData, TValue>(
  column: DataTableColumn<TData, TValue>,
  row?: DataTableRow<TData>
): boolean {
  if (column.accessorFn == null) return false
  const enabled = column.columnDef.meta?.enableEditing
  if (typeof enabled === "function") return row ? enabled(row) : true
  return enabled !== false
}

export interface MeasureColumnWidthOptions {
  /** CSS `font` shorthand read from a rendered cell (e.g. `getComputedStyle(cell).font`). */
  font: string
  /** Total horizontal cell padding (left + right) in px. */
  padding: number
  /** Extra space for header affordances (sort icon, actions trigger). Default 0. */
  extraWidth?: number
  /** Lower bound for the result. Default 0. */
  minWidth?: number
  /** Upper bound, to stop one long value producing an absurd column. Default 400. */
  maxWidth?: number
}

// A single reused canvas keeps text measurement off the DOM (no reflow) and
// avoids allocating a canvas per call.
let sharedCtx: CanvasRenderingContext2D | null | undefined

function getContext(): CanvasRenderingContext2D | null {
  if (sharedCtx !== undefined) return sharedCtx
  if (typeof document === "undefined") {
    sharedCtx = null
    return null
  }
  sharedCtx = document.createElement("canvas").getContext("2d")
  return sharedCtx
}

/**
 * Measure the width a column needs to fit its widest value without wrapping.
 *
 * Pure + framework-free: canvas text measurement means it covers the full
 * dataset (not just the rows currently rendered under virtualization), at the
 * cost of not accounting for custom cell markup — it measures the raw string
 * values the caller passes in. Falls back to a rough character estimate when no
 * canvas is available (non-browser environments).
 */
export function measureColumnWidth(
  values: string[],
  headerText: string,
  options: MeasureColumnWidthOptions
): number {
  const {
    font,
    padding,
    extraWidth = 0,
    minWidth = 0,
    maxWidth = 400,
  } = options
  const ctx = getContext()

  let contentWidth: number
  if (ctx) {
    ctx.font = font
    contentWidth = ctx.measureText(headerText).width
    for (const value of values) {
      const width = ctx.measureText(value).width
      if (width > contentWidth) contentWidth = width
    }
  } else {
    // ~8px per character is a coarse fallback for non-browser environments.
    const longest = values.reduce(
      (max, v) => (v.length > max ? v.length : max),
      headerText.length
    )
    contentWidth = longest * 8
  }

  const total = Math.ceil(contentWidth + padding + extraWidth)
  return Math.max(minWidth, Math.min(maxWidth, total))
}

const DATE_ONLY = /^(\d{4})-(\d{2})-(\d{2})$/

/**
 * Parses a cell or filter value as a Date, or null when blank or invalid.
 * A date-only string (`"2025-01-10"`) is that calendar day at local midnight;
 * `new Date()` would read it as UTC midnight, the previous day west of UTC.
 */
export function parseDate(value: unknown): Date | null {
  if (value == null || value === "") return null
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value
  if (typeof value === "string") {
    const match = DATE_ONLY.exec(value.trim())
    if (match) {
      const [, y, m, d] = match.map(Number) as [number, number, number, number]
      const date = new Date(y, m - 1, d)
      // Reject overflow such as Feb 30, which Date would roll into March.
      return date.getMonth() === m - 1 && date.getDate() === d ? date : null
    }
  }
  if (typeof value !== "string" && typeof value !== "number") return null
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? null : date
}

import { defaultRangeExtractor, type Range } from "@tanstack/react-virtual"

/**
 * Column-virtualizer range: the visible window plus every pinned column, so
 * sticky pinned columns stay rendered however far the table scrolls.
 */
export function pinnedRangeExtractor(
  range: Range,
  pinnedIndexes: number[]
): number[] {
  const indexes = defaultRangeExtractor(range)
  if (!pinnedIndexes.length) return indexes
  const merged = new Set(indexes)
  for (const index of pinnedIndexes) {
    if (index >= 0 && index < range.count) merged.add(index)
  }
  return [...merged].sort((a, b) => a - b)
}

/** Rows the table knows about and where the drawn ones sit. */
export type RowSnapshot = {
  /** Every row key in the row model (plus "<id>:detail" for open panels). */
  members: ReadonlySet<string>
  /** Drawn rows only: px from the table's top edge. */
  tops: ReadonlyMap<string, number>
}

export type RowAnimationPlan = {
  moves: { key: string; dy: number }[]
  enters: string[]
  leaves: string[]
  /** Rows already in the data, drawn now but not before: a change brought
   *  them into a virtual window. */
  arrivals: string[]
  skipped: boolean
}

/** Above this many animated rows the table just updates. */
export const MAX_ANIMATED_ROWS = 300

/** An empty plan: a fresh object each time, so no caller can share it. */
const none = (skipped = false): RowAnimationPlan => ({
  moves: [],
  enters: [],
  leaves: [],
  arrivals: [],
  skipped,
})

/**
 * What changed between two snapshots: rows to glide (with the distance), rows
 * that appeared in the data and rows that left it. Rows that were in the data
 * but are newly drawn are arrivals, not entering; rows no longer drawn but
 * still in the data are not leaving. Only call it for a row change: a scroll
 * would make every row new to the window an arrival.
 */
export function planRowAnimations(
  prev: RowSnapshot | null,
  next: RowSnapshot,
  limit = MAX_ANIMATED_ROWS
): RowAnimationPlan {
  if (!prev) return none()
  const moves: { key: string; dy: number }[] = []
  const enters: string[] = []
  const arrivals: string[] = []
  for (const [key, top] of next.tops) {
    const before = prev.tops.get(key)
    if (before !== undefined) {
      if (before !== top) moves.push({ key, dy: before - top })
    } else if (prev.members.has(key)) {
      arrivals.push(key)
    } else {
      enters.push(key)
    }
  }
  const leaves: string[] = []
  for (const key of prev.tops.keys()) {
    if (!next.members.has(key)) leaves.push(key)
  }
  const count = moves.length + enters.length + leaves.length + arrivals.length
  if (count > limit) return none(true)
  return { moves, enters, leaves, arrivals, skipped: false }
}

import type { RowData } from "@tanstack/react-table"
import type { DataTableRow } from "../core/table-types"

export interface RowHeightOptions<TData extends RowData> {
  /** Flat height (px) applied to every row. */
  rowHeight?: number
  /** Per-row height: a px number, `"auto"` (wrap and grow), or `null` to fall
   *  back to `rowHeight` / the density default. */
  getRowHeight?: (row: DataTableRow<TData>) => number | "auto" | null
}

/**
 * Resolves a row's height from the `getRowHeight` / `rowHeight` options.
 * Precedence: `getRowHeight(row)` (unless it returns null/undefined) →
 * `rowHeight` → `undefined` (meaning "use the density default").
 */
export function resolveRowHeight<TData extends RowData>(
  row: DataTableRow<TData>,
  { getRowHeight, rowHeight }: RowHeightOptions<TData>
): number | "auto" | undefined {
  const resolved = getRowHeight?.(row)
  if (resolved != null) return resolved
  return rowHeight
}

import type { RowData } from "@tanstack/react-table"
import type * as React from "react"

import { cn } from "@/lib/utils"

import type { DataTableInstance, DataTableSlots } from "../core/types"

type AnyProps = Record<string, unknown>

// Composed refs, cached per pair so the same two refs give the same callback
// on every render (a new callback makes React detach and re-attach the
// element on each commit).
const composedRefs = new WeakMap<object, WeakMap<object, unknown>>()

/** Points both refs at the element (callback or object refs). */
function composeRefs<T>(a: React.Ref<T>, b: React.Ref<T>) {
  const byFirst = composedRefs.get(a as object) ?? new WeakMap()
  composedRefs.set(a as object, byFirst)
  const cached = byFirst.get(b as object)
  if (cached) return cached as (el: T | null) => void
  const composed = (el: T | null) => {
    for (const ref of [a, b]) {
      if (typeof ref === "function") ref(el)
      else if (ref) (ref as React.RefObject<T | null>).current = el
    }
  }
  byFirst.set(b as object, composed)
  return composed
}

/**
 * Merges consumer props over the table's own: `className` values are
 * combined, `style` objects merged (consumer wins), event handlers both run
 * (ours first), refs both receive the element, anything else is replaced.
 * Undefined values are ignored.
 */
export function mergeProps<P extends object>(
  ours: P,
  ...theirs: Array<Partial<P> | undefined | null>
): P {
  let out = ours as AnyProps
  for (const next of theirs) {
    if (!next) continue
    // An undefined value means "not set", so it never wipes one of ours.
    const add = Object.fromEntries(
      Object.entries(next).filter(([, value]) => value !== undefined)
    )
    const merged: AnyProps = { ...out, ...add }
    if (out.className || add.className) {
      merged.className = cn(out.className as string, add.className as string)
    }
    if (out.style || add.style) {
      merged.style = {
        ...(out.style as React.CSSProperties),
        ...(add.style as React.CSSProperties),
      }
    }
    for (const key of Object.keys(add)) {
      const a = out[key]
      const b = add[key]
      if (
        /^on[A-Z]/.test(key) &&
        typeof a === "function" &&
        typeof b === "function"
      ) {
        merged[key] = (...args: unknown[]) => {
          ;(a as (...args: unknown[]) => void)(...args)
          ;(b as (...args: unknown[]) => void)(...args)
        }
      }
    }
    if (out.ref && add.ref) {
      merged.ref = composeRefs(
        out.ref as React.Ref<unknown>,
        add.ref as React.Ref<unknown>
      )
    }
    out = merged
  }
  return out as P
}

/** A slot value: props, or a function of the slot's context. */
type SlotValue<Ctx, Props> = Props | ((context: Ctx) => Props) | undefined

function resolve<Ctx, Props>(value: SlotValue<Ctx, Props>, context: Ctx) {
  return typeof value === "function"
    ? (value as (context: Ctx) => Props)(context)
    : value
}

type SlotContext<TData extends RowData, K extends keyof DataTableSlots<TData>> =
  Extract<
    NonNullable<DataTableSlots<TData>[K]>,
    (context: never) => unknown
  > extends (context: infer Ctx) => unknown
    ? Ctx
    : never

/**
 * The consumer's props for one part of the table: the table-level
 * `slotProps[key]`, then a column-level `meta.slotProps[key]` when given,
 * each resolved against the part's context.
 */
export function getSlotProps<
  TData extends RowData,
  K extends keyof DataTableSlots<TData>,
>(
  table: DataTableInstance<TData>,
  key: K,
  context: Omit<SlotContext<TData, K>, "table">,
  columnSlot?: unknown
): AnyProps | undefined {
  const ctx = { ...context, table } as never
  const tableLevel = resolve(
    table.dataTable.slotProps?.[key] as SlotValue<never, AnyProps>,
    ctx
  )
  const columnLevel = resolve(columnSlot as SlotValue<never, AnyProps>, ctx)
  if (!tableLevel) return columnLevel
  if (!columnLevel) return tableLevel
  return mergeProps(tableLevel, columnLevel)
}

import type * as React from "react"

/** Keeps a click or double-click on an in-row control (edit, expand, pin,
 *  copy, menu…) from also firing the row's / cell's own (double-)click
 *  handlers. React synthetic events bubble through the React tree, portals
 *  included, so putting this on a wrapper also covers menu items and select
 *  options rendered in portals. */
export function stopPropagation(event: React.SyntheticEvent): void {
  event.stopPropagation()
}

import type { TableState } from "@tanstack/react-table"

import type { DataTableFeatures } from "../core/features"
import {
  fromCorePinning,
  type DataTableColumnPinningState,
} from "./column-pinning"

type CoreState = TableState<DataTableFeatures>

/** Table state in our stable shape: v8-style left/right column pinning and
 *  the v8 `columnSizingInfo` name for TanStack v9's `columnResizing`. Every
 *  other slice is passed through by reference (memo deps stay stable). */
export type DataTableState = Omit<CoreState, "columnPinning"> & {
  columnPinning: Required<DataTableColumnPinningState>
  columnSizingInfo: CoreState["columnResizing"]
}

// TanStack v9 replaces the store's state object only when a slice changes, so
// keying on it hands back the same snapshot (and the same slice references)
// until the next change, like v8's stored state.
const snapshots = new WeakMap<CoreState, DataTableState>()
// The converted pinning is cached on TanStack's own pinning object, so it
// keeps its identity while other slices change (row memo deps compare it).
const pinnings = new WeakMap<
  CoreState["columnPinning"],
  Required<DataTableColumnPinningState>
>()

function stablePinning(
  pinning: CoreState["columnPinning"]
): Required<DataTableColumnPinningState> {
  let converted = pinnings.get(pinning)
  if (!converted) {
    converted = fromCorePinning(pinning)
    pinnings.set(pinning, converted)
  }
  return converted
}

export function toDataTableState(state: CoreState): DataTableState {
  let snapshot = snapshots.get(state)
  if (!snapshot) {
    snapshot = {
      ...state,
      columnPinning: stablePinning(state.columnPinning),
      columnSizingInfo: state.columnResizing,
    }
    snapshots.set(state, snapshot)
  }
  return snapshot
}

export interface VirtualHeaderRun<H> {
  header: H
  /** Position of the run's first column in the rendered (virtual) columns. */
  start: number
  /** Number of adjacent rendered columns the run covers. */
  span: number
}

/**
 * Lays out one header row under column virtualization. Each header covers
 * `colSpan` leaf columns; this finds the header over each rendered column and
 * merges adjacent rendered columns under the same header into one run. A gap
 * in the rendered columns (skipped by the virtualizer) splits a run.
 */
export function getVirtualHeaderRuns<H extends { colSpan: number }>(
  headers: H[],
  virtualIndexes: number[]
): VirtualHeaderRun<H>[] {
  const owners: H[] = []
  for (const header of headers) {
    for (let i = 0; i < header.colSpan; i++) owners.push(header)
  }
  const runs: VirtualHeaderRun<H>[] = []
  virtualIndexes.forEach((index, position) => {
    const header = owners[index]
    if (!header) return
    const last = runs[runs.length - 1]
    if (
      last &&
      last.header === header &&
      virtualIndexes[position - 1] === index - 1
    ) {
      last.span++
    } else {
      runs.push({ header, start: position, span: 1 })
    }
  })
  return runs
}

