import {
  setStateSlice,
  type RowData,
  type Updater,
} from "@tanstack/react-table"

import type { EditingCell } from "../core/types"
import type { DataTableRow } from "../core/table-types"
import type { DataTableUiState, DataTableUiStateKey } from "../core/ui-state"

export interface EditingActions<TData extends RowData> {
  setEditingCell: (updater: Updater<EditingCell | null>) => void
  setRowDraftValue: (columnId: string, value: unknown) => void
  beginRowEdit: (row: DataTableRow<TData>) => void
  beginCreate: () => void
  cancelEdit: () => void
}

/** The table, as far as the editing transitions need it. */
interface StateTable {
  options: object
  store: { state: object }
}

/**
 * Inline editing / create-form transitions. The state they move between
 * (`editingCell`, `editingRowId`, `isCreating`, `rowDraft`) is table state, so
 * each step goes through the slice's change handler like any TanStack setter.
 * The draft is seeded from the row's accessor cells on edit, or from
 * `createRowDefaults` on create. Created once per table: everything is read
 * through the getters when an action runs.
 */
export function createEditingActions<TData extends RowData>(
  getTable: () => StateTable | null,
  getCreateRowDefaults: () => Record<string, unknown> | undefined
): EditingActions<TData> {
  const set = <K extends DataTableUiStateKey>(
    key: K,
    updater: Updater<DataTableUiState[K]>
  ) => {
    const table = getTable()
    if (table) setStateSlice(table as never, key as never, updater as never)
  }

  return {
    setEditingCell: (updater) => set("editingCell", updater),
    setRowDraftValue: (columnId, value) =>
      set("rowDraft", (prev) => ({ ...prev, [columnId]: value })),
    beginRowEdit: (row) => {
      const draft: Record<string, unknown> = {}
      for (const cell of row.getAllCells()) {
        if (cell.column.accessorFn != null) {
          draft[cell.column.id] = cell.getValue()
        }
      }
      set("rowDraft", draft)
      set("editingRowId", row.id)
      set("isCreating", false)
      set("editingCell", null)
    },
    beginCreate: () => {
      const defaults = getCreateRowDefaults()
      set("rowDraft", defaults ? { ...defaults } : {})
      set("isCreating", true)
      set("editingRowId", null)
      set("editingCell", null)
    },
    cancelEdit: () => {
      set("editingCell", null)
      set("editingRowId", null)
      set("isCreating", false)
      set("rowDraft", {})
    },
  }
}

"use client"

import * as React from "react"

import { NOT_IN_LEAVE_COPY } from "../core/motion"

// Never the controls of a leaving row's copy (row animations), which fades
// out in the motion layer for a moment.
const TABBABLE = [
  "a[href]",
  "button:not([disabled])",
  "input:not([disabled])",
  "select:not([disabled])",
  "textarea:not([disabled])",
  '[tabindex]:not([tabindex="-1"])',
]
  .map((selector) => selector + NOT_IN_LEAVE_COPY)
  .join(", ")

const EDITABLE = new Set(["INPUT", "TEXTAREA", "SELECT"])

/**
 * Full-screen mode behaves as a modal dialog: the page behind stops
 * scrolling, Tab cycles inside the table, Escape leaves, and focus returns to
 * where it was when leaving would otherwise drop it on the page.
 */
export function useFullscreenModal(
  paperRef: React.RefObject<HTMLElement | null>,
  isFullscreen: boolean,
  exit: () => void
) {
  React.useEffect(() => {
    if (!isFullscreen) return
    const returnTo = document.activeElement as HTMLElement | null
    const { overflow } = document.body.style
    document.body.style.overflow = "hidden"
    return () => {
      document.body.style.overflow = overflow
      const active = document.activeElement
      if ((!active || active === document.body) && returnTo?.isConnected) {
        returnTo.focus()
      }
    }
  }, [isFullscreen])

  const onKeyDown = (event: React.KeyboardEvent<HTMLElement>) => {
    const paper = paperRef.current
    if (!isFullscreen || !paper) return
    // Only keys from the table itself: menus and pickers render in portals
    // (React still bubbles their events here), take focus and close themselves
    // on Escape.
    const target = event.target as HTMLElement
    if (!paper.contains(target)) return

    if (event.key === "Escape") {
      // With focus still in the table, the only layer that may have claimed
      // the key is a tooltip, which closes as the table does. Inline editors
      // keep Escape for cancelling.
      if (EDITABLE.has(target.tagName)) return
      exit()
      return
    }
    if (event.defaultPrevented) return

    if (event.key === "Tab") {
      const tabbable = Array.from(
        paper.querySelectorAll<HTMLElement>(TABBABLE)
      ).filter((el) => el.getClientRects().length > 0)
      const first = tabbable[0]
      const last = tabbable[tabbable.length - 1]
      if (!first || !last) return
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault()
        last.focus()
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault()
        first.focus()
      }
    }
  }

  return { onKeyDown }
}

"use client"

import * as React from "react"
import type { RowData } from "@tanstack/react-table"

import {
  createGlobalFilterFn,
  createRankedSortedRowModel,
  type CustomFilterFns,
  type GlobalFilterMode,
} from "../fns/filter-fns"
import type {
  DataTableFilterFn,
  DataTableRowModelFactory,
} from "../core/table-types"

interface UseGlobalFilterModeParams<TData extends RowData> {
  /** The current mode (table state), read when filtering and ranking. */
  getMode: () => GlobalFilterMode
  /** The consumer's `filterFns`, read when filtering. */
  getCustomFns: () => CustomFilterFns<TData>
  enableGlobalFilterRankedResults: boolean
  manualSorting: boolean
  manualFiltering: boolean
  enableGrouping: boolean
}

export interface GlobalFilterModeState<TData extends RowData> {
  /** Mode-aware global filter fn. Stable: it reads the mode when it runs, and
   *  the filtered row model re-filters when the mode changes. */
  dynamicGlobalFilterFn: DataTableFilterFn<TData>
  /** Sorted row model that re-orders by fuzzy rank when ranking is active. */
  rankedSortedRowModel: DataTableRowModelFactory<TData>
}

/**
 * Global-search mode state plus the two row-model pieces it drives: the
 * mode-aware global filter fn and the fuzzy-ranked sorted row model. While a
 * fuzzy global search is active and the user hasn't sorted, rows are ordered by
 * best match; the current config is read through a ref so the model factory
 * keeps a stable identity (recreating it would defeat TanStack's memoization).
 */
export function useGlobalFilterMode<TData extends RowData>({
  getMode,
  getCustomFns,
  enableGlobalFilterRankedResults,
  manualSorting,
  manualFiltering,
  enableGrouping,
}: UseGlobalFilterModeParams<TData>): GlobalFilterModeState<TData> {
  const getModeRef = React.useRef(getMode)
  // eslint-disable-next-line react-hooks/refs
  getModeRef.current = getMode
  const getCustomFnsRef = React.useRef(getCustomFns)
  // eslint-disable-next-line react-hooks/refs
  getCustomFnsRef.current = getCustomFns
  // Stable; the filtered row model (fns/advanced-filter.ts) re-filters when
  // the mode changes, since TanStack's own memo ignores filter functions.
  // Read inside TanStack's filtering pass, not during this render.
  /* eslint-disable react-hooks/refs */
  const dynamicGlobalFilterFn = React.useMemo(
    () =>
      createGlobalFilterFn<TData>(
        () => getModeRef.current(),
        () => getCustomFnsRef.current()
      ),
    []
  )
  /* eslint-enable react-hooks/refs */

  const rankingRef = React.useRef<{
    enabled: boolean
    manualSorting: boolean
    manualFiltering: boolean
    grouping: boolean
  }>(null!)
  // Render-phase latest-ref write is load-bearing: TanStack computes row
  // models during render, and the stable factory below must see this render's
  // config (an effect write would rank with stale config for a full frame).
  // eslint-disable-next-line react-hooks/refs
  rankingRef.current = {
    enabled: enableGlobalFilterRankedResults,
    manualSorting,
    manualFiltering,
    grouping: enableGrouping,
  }
  const rankedSortedRowModel = React.useMemo(
    () =>
      // The predicate runs inside TanStack's row-model computation, not
      // during this hook's render.
      // eslint-disable-next-line react-hooks/refs
      createRankedSortedRowModel<TData>((t) => {
        const c = rankingRef.current
        if (!c.enabled || getModeRef.current() !== "fuzzy") return false
        if (c.manualSorting || c.manualFiltering) return false
        const s = t.store.state
        if (!s.globalFilter) return false
        if (s.sorting.some(Boolean)) return false
        if (c.grouping && s.grouping.length > 0) return false
        if (s.expanded === true || Object.values(s.expanded).some(Boolean))
          return false
        return true
      }),
    []
  )

  return {
    dynamicGlobalFilterFn,
    rankedSortedRowModel,
  }
}

"use client"

import * as React from "react"

const NAV_KEYS = new Set([
  "ArrowUp",
  "ArrowDown",
  "ArrowLeft",
  "ArrowRight",
  "Home",
  "End",
  "PageUp",
  "PageDown",
])

/** Controls a cell can hold (edit trigger, expand, copy, checkbox…). */
const FOCUSABLE =
  'button, a[href], input, select, textarea, [tabindex]:not([tabindex="-1"])'

/** Asks the grid to restore focus and its tab stop after a row rendered on
 *  its own (provided by DataTable). */
export const GridSyncContext = React.createContext<(() => void) | null>(null)

const EDITABLE = new Set(["INPUT", "TEXTAREA", "SELECT"])

/** Frames to wait for a scrolled-to cell to render before giving up. */
const MAX_FOCUS_FRAMES = 30

export interface GridCell {
  row: number
  col: number
}

export interface UseGridNavigationOptions<T extends HTMLElement> {
  enabled: boolean
  /** The grid element whose `[data-cell-row]` cells are navigated. */
  ref: React.RefObject<T | null>
  /** Number of navigable rows (display order: top, center, bottom). */
  rowCount: () => number
  /** Number of navigable columns (visible leaf columns). */
  colCount: () => number
  /** Brings a cell that is not rendered (virtualized) into view. */
  scrollToCell: (cell: GridCell) => void
  /** Right-to-left: ArrowLeft moves to the next column, ArrowRight back. */
  rtl?: boolean
}

const findCell = (root: HTMLElement, { row, col }: GridCell) =>
  root.querySelector<HTMLElement>(
    `[data-cell-row="${row}"][data-cell-col="${col}"]`
  )

/**
 * Roving-tabindex keyboard navigation for body cells (MRT V3 parity). Cells
 * carry `data-cell-row` / `data-cell-col`; the grid is a single tab stop and
 * arrow keys / Home / End move focus between cells. Bounds come from the data,
 * not the DOM, so virtualized rows and columns are reachable: a target that is
 * not rendered is scrolled into view, then focused once it renders. Skipped
 * while focus is in an editable control so typing in a filter/edit field isn't
 * hijacked.
 */
export function useGridNavigation<T extends HTMLElement>({
  enabled,
  ref,
  rowCount,
  colCount,
  scrollToCell,
  rtl = false,
}: UseGridNavigationOptions<T>) {
  const activeCellRef = React.useRef<GridCell>({ row: 0, col: 0 })
  const pendingFrameRef = React.useRef<number | null>(null)
  // The last element focused inside the grid (a cell or a control in one).
  const focusedRef = React.useRef<HTMLElement | null>(null)

  // After every render, exactly one rendered cell is the tab stop: the active
  // cell when it is rendered, otherwise the first rendered cell.
  // After a render of the grid or of a row: restore focus that fell to the
  // page, and keep exactly one rendered cell as the tab stop. Rows render on
  // their own (see MemoRow), so they ask for this through `scheduleSync`.
  const sync = () => {
    const root = ref.current
    if (!enabled || !root) return
    // The focused element unmounted and focus fell to the page: an inline
    // editor closed, save/cancel buttons went away, the row was deleted, or it
    // scrolled out of a virtual window. Put focus back at the same cell
    // position (on its control when a control had it), or park it on the grid
    // so the keys keep working from the active cell.
    const focused = focusedRef.current
    if (
      focused &&
      !focused.isConnected &&
      (document.activeElement === document.body || !document.activeElement)
    ) {
      focusedRef.current = null
      const cell = findCell(root, activeCellRef.current)
      if (cell) {
        const inner = focused.matches("[data-cell-row]")
          ? null
          : cell.querySelector<HTMLElement>(FOCUSABLE)
        ;(inner ?? cell).focus({ preventScroll: true })
      } else {
        root.focus({ preventScroll: true })
      }
    }
    const cells = root.querySelectorAll<HTMLElement>("[data-cell-row]")
    if (cells.length === 0) return
    const stop = findCell(root, activeCellRef.current) ?? cells[0]!
    for (const cell of cells) cell.tabIndex = cell === stop ? 0 : -1
  }
  React.useLayoutEffect(sync)

  // One sync per commit, however many rows rendered in it; microtasks run
  // before the browser paints.
  const syncRef = React.useRef(sync)
  const pendingSyncRef = React.useRef(false)
  React.useLayoutEffect(() => {
    syncRef.current = sync
  })
  const [scheduleSync] = React.useState(() => () => {
    if (pendingSyncRef.current) return
    pendingSyncRef.current = true
    queueMicrotask(() => {
      pendingSyncRef.current = false
      syncRef.current()
    })
  })

  React.useEffect(
    () => () => {
      if (pendingFrameRef.current != null)
        cancelAnimationFrame(pendingFrameRef.current)
    },
    []
  )

  const focusCell = (root: HTMLElement, el: HTMLElement) => {
    for (const cell of root.querySelectorAll<HTMLElement>("[data-cell-row]"))
      cell.tabIndex = -1
    el.tabIndex = 0
    el.focus()
  }

  const moveTo = (root: HTMLElement, target: GridCell) => {
    activeCellRef.current = target
    if (pendingFrameRef.current != null)
      cancelAnimationFrame(pendingFrameRef.current)
    pendingFrameRef.current = null

    const el = findCell(root, target)
    if (el) {
      focusCell(root, el)
      return
    }
    // Virtualized: scroll the target into view, then focus it once rendered.
    scrollToCell(target)
    let frames = 0
    const tryFocus = () => {
      pendingFrameRef.current = null
      const rendered = findCell(root, target)
      if (rendered) {
        if (activeCellRef.current === target) focusCell(root, rendered)
        return
      }
      if (++frames < MAX_FOCUS_FRAMES)
        pendingFrameRef.current = requestAnimationFrame(tryFocus)
    }
    pendingFrameRef.current = requestAnimationFrame(tryFocus)
  }

  /** Enter / F2 / Ctrl+C on a focused cell (not on a control inside it). */
  const onCellCommand = (event: React.KeyboardEvent<T>, cell: HTMLElement) => {
    if (event.key === "Enter" || event.key === "F2") {
      // Activate the cell's control: open its editor, toggle, follow a link.
      const control = cell.querySelector<HTMLElement>(FOCUSABLE)
      if (!control) return
      event.preventDefault()
      if (EDITABLE.has(control.tagName)) control.focus()
      else control.click()
      return
    }
    const isCopy =
      (event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "c"
    if (isCopy && !window.getSelection()?.toString()) {
      event.preventDefault()
      void navigator.clipboard?.writeText(cell.textContent?.trim() ?? "")
    }
  }

  const onKeyDown = (event: React.KeyboardEvent<T>) => {
    if (!enabled) return
    const root = ref.current
    if (!root) return

    const active = document.activeElement as HTMLElement | null
    if (active && EDITABLE.has(active.tagName)) return

    if (!NAV_KEYS.has(event.key)) {
      if (active?.matches("[data-cell-row]") && root.contains(active)) {
        onCellCommand(event, active)
      }
      return
    }

    // Focus is on a cell, or parked on the grid itself (see above).
    const current = active?.closest<HTMLElement>("[data-cell-row]")
    let from: GridCell
    if (current && root.contains(current)) {
      from = {
        row: Number(current.dataset.cellRow),
        col: Number(current.dataset.cellCol),
      }
    } else if (active === root) {
      from = activeCellRef.current
    } else return

    const maxRow = rowCount() - 1
    const maxCol = colCount() - 1
    if (maxRow < 0 || maxCol < 0) return

    let { row, col } = from

    switch (event.key) {
      case "ArrowUp":
        row = Math.max(0, row - 1)
        break
      case "ArrowDown":
        row = Math.min(maxRow, row + 1)
        break
      case "PageUp":
      case "PageDown": {
        // About one screen of rows: the visible height over a row's height.
        const rowHeight = current?.offsetHeight || 40
        const step = Math.max(1, Math.floor(root.clientHeight / rowHeight) - 1)
        row =
          event.key === "PageDown"
            ? Math.min(maxRow, row + step)
            : Math.max(0, row - step)
        break
      }
      case "ArrowLeft":
      case "ArrowRight":
        // Columns run right to left in RTL, so the arrows swap meaning.
        if ((event.key === "ArrowRight") !== rtl) {
          col = Math.min(maxCol, col + 1)
        } else {
          col = Math.max(0, col - 1)
        }
        break
      case "Home":
        col = 0
        if (event.ctrlKey) row = 0
        break
      case "End":
        col = maxCol
        if (event.ctrlKey) row = maxRow
        break
    }

    if (row === from.row && col === from.col && current) return
    event.preventDefault()
    moveTo(root, { row, col })
  }

  /** Keeps the active cell in sync when a cell is focused by click or Tab. */
  const onFocus = (event: React.FocusEvent<T>) => {
    if (!enabled) return
    const cell = (event.target as HTMLElement).closest<HTMLElement>(
      "[data-cell-row]"
    )
    if (!cell) return
    focusedRef.current = event.target as HTMLElement
    activeCellRef.current = {
      row: Number(cell.dataset.cellRow),
      col: Number(cell.dataset.cellCol),
    }
  }

  /** Forgets the focused element once focus moves out of the grid, so a
   *  later unmount there does not pull focus back in. */
  const onBlur = (event: React.FocusEvent<T>) => {
    const root = ref.current
    const next = event.relatedTarget as Node | null
    const target = event.target as Node
    if (target.isConnected && root && (!next || !root.contains(next))) {
      focusedRef.current = null
    }
  }

  return { onKeyDown, onFocus, onBlur, activeCellRef, scheduleSync }
}

"use client"

import * as React from "react"

export interface UseInfiniteScrollOptions {
  /** Master switch. When false, no observer is created. */
  enabled: boolean
  /** Whether more rows exist to load. */
  hasNextPage: boolean
  /** Whether a load is currently in flight (blocks re-triggering). */
  isFetchingNextPage: boolean
  /** Called (once per satisfied condition) to request the next chunk. Should be
   *  stable across renders (e.g. `useCallback`) to avoid extra calls. */
  onLoadMore?: () => void
  /** Distance in px from the bottom at which to prefetch. Default 200. */
  threshold?: number
  /** The scroll container the sentinel lives in (IntersectionObserver root). */
  scrollRef: React.RefObject<HTMLElement | null>
  /** The sentinel element rendered after the last row. */
  sentinelRef: React.RefObject<HTMLElement | null>
}

/**
 * Fires `onLoadMore` when a bottom sentinel scrolls near the viewport, gated by
 * the controlled `hasNextPage` / `isFetchingNextPage` flags. Works whether or
 * not row virtualization is on, since the sentinel sits after the rendered
 * window. Re-checks on flag changes so a finished fetch that leaves the sentinel
 * still in view loads the following chunk.
 */
export function useInfiniteScroll({
  enabled,
  hasNextPage,
  isFetchingNextPage,
  onLoadMore,
  threshold = 200,
  scrollRef,
  sentinelRef,
}: UseInfiniteScrollOptions): void {
  const [isIntersecting, setIsIntersecting] = React.useState(false)

  React.useEffect(() => {
    const sentinel = sentinelRef.current
    if (!enabled || !sentinel) {
      setIsIntersecting(false)
      return
    }
    const observer = new IntersectionObserver(
      (entries) => {
        // The browser may batch several records (e.g. the initial "not
        // visible" plus a quick scroll's "visible"); the last is current.
        const entry = entries[entries.length - 1]
        if (entry) setIsIntersecting(entry.isIntersecting)
      },
      {
        root: scrollRef.current ?? null,
        rootMargin: `0px 0px ${threshold}px 0px`,
      }
    )
    observer.observe(sentinel)
    return () => observer.disconnect()
  }, [enabled, threshold, scrollRef, sentinelRef])

  React.useEffect(() => {
    if (enabled && isIntersecting && hasNextPage && !isFetchingNextPage) {
      onLoadMore?.()
    }
  }, [enabled, isIntersecting, hasNextPage, isFetchingNextPage, onLoadMore])
}

"use client"

import * as React from "react"
import type { RowData } from "@tanstack/react-table"

import type { DataTableInstance } from "../core/types"
import { useTableStateListener } from "./use-table-state"

interface PageIndexClampParams {
  enablePagination: boolean
  manualPagination?: boolean
  isLoading: boolean
  showSkeletons: boolean
}

/**
 * Keeps `pageIndex` inside the available pages when the row count shrinks
 * (data refetched, rows deleted, filters narrowed) so the user is never left
 * on an empty page. Runs in an effect, not during render. Skipped under
 * manual pagination (the server owns the page) and while loading (an empty
 * `data` during a refetch must not drop the user to the first page).
 */
export function usePageIndexClamp<TData extends RowData>(
  table: DataTableInstance<TData>,
  {
    enablePagination,
    manualPagination,
    isLoading,
    showSkeletons,
  }: PageIndexClampParams
): void {
  // A no-op on the first page, so the row count (which computes the
  // filtered/sorted row models) is only read when the user is past page 0.
  const clamp = () => {
    if (!enablePagination || manualPagination || isLoading || showSkeletons)
      return
    const { pageIndex, pageSize } = table.getState().pagination
    if (pageIndex === 0) return
    const lastPage = Math.max(0, Math.ceil(table.getRowCount() / pageSize) - 1)
    if (pageIndex > lastPage) table.setPageIndex(lastPage)
  }
  // After renders of the component holding the table (new data), and after
  // state changes (narrower filters), which may not re-render it.
  React.useEffect(clamp)
  useTableStateListener(table, clamp)
}

"use client"

import * as React from "react"
import type { RowData } from "@tanstack/react-table"

import type { DataTableInstance } from "../core/types"
import { useTableStateListener } from "./use-table-state"

interface PageResetParams {
  enablePagination: boolean
  manualPagination?: boolean
  autoResetPageIndex?: boolean
}

const filtersKey = <TData extends RowData>(table: DataTableInstance<TData>) => {
  const { columnFilters, globalFilter, advancedFilter } = table.getState()
  return JSON.stringify([columnFilters, globalFilter, advancedFilter])
}

/**
 * Goes back to the first page when the filters change (column filters, global
 * search or the advanced filter; MRT behaviour), replacing TanStack's
 * render-phase auto-reset (which warns in React 19 dev). Listens to the table
 * store, so it works whether or not the component holding the table
 * re-renders. Skipped under manual pagination (the server owns it) and when
 * the consumer opted into the native auto-reset.
 */
export function usePageResetOnFilterChange<TData extends RowData>(
  table: DataTableInstance<TData>,
  { enablePagination, manualPagination, autoResetPageIndex }: PageResetParams
): void {
  const prevKeyRef = React.useRef<string | null>(null)
  useTableStateListener(table, () => {
    const key = filtersKey(table)
    const prevKey = prevKeyRef.current
    prevKeyRef.current = key
    if (prevKey === null || prevKey === key) return
    if (enablePagination && !manualPagination && autoResetPageIndex == null) {
      if (table.getState().pagination.pageIndex !== 0) table.setPageIndex(0)
    }
  })
  // The starting filters, so the first change is compared against them.
  React.useEffect(() => {
    if (prevKeyRef.current === null) prevKeyRef.current = filtersKey(table)
  }, [table])
}

"use client"

import * as React from "react"
import type { RowData } from "@tanstack/react-table"

import {
  createExpandColumn,
  createRowDragHandleColumn,
  createRowNumberColumn,
  createRowPinColumn,
} from "../injected-columns/injected-columns"
import { createRowActionsColumn } from "../injected-columns/data-table-row-actions"
import { createSelectionColumn } from "../injected-columns/selection-column"
import type { DataTableIcons } from "../core/icons"
import type { DataTableLocalization } from "../core/localization"
import type { EditDisplayMode, UseDataTableOptions } from "../core/types"
import type { DataTableColumnDef } from "../core/table-types"
import {
  applyDisplayColumnOptions,
  displayColumnOptionsKey,
  type DisplayColumnOptions,
} from "../helpers/display-column-options"

interface UseResolvedColumnsParams<TData extends RowData> {
  columns: ReadonlyArray<DataTableColumnDef<TData, unknown>>
  enableRowOrdering: boolean
  enableRowSelection: boolean
  selectAllMode: "page" | "all"
  enableSelectAll: boolean
  needsExpandColumn: boolean
  positionExpandColumn: "first" | "last"
  enableRowNumbers: boolean
  rowNumberMode: "static" | "original"
  enableRowPinning: boolean
  renderRowActions: UseDataTableOptions<TData>["renderRowActions"]
  renderRowActionMenuItems: UseDataTableOptions<TData>["renderRowActionMenuItems"]
  positionActionsColumn: "first" | "last"
  enableEditing: boolean
  editDisplayMode: EditDisplayMode
  localization: DataTableLocalization
  icons: DataTableIcons
  /** `defaultDisplayColumn` / `displayColumnDefOptions`. */
  displayColumnOptions: DisplayColumnOptions<TData>
}

/**
 * Injects the display columns around the user's columns, memoized so TanStack
 * never receives a new `columns` identity per render (a classic infinite-loop /
 * lost-state trap). Leading order: drag handle → selection → expand → row
 * number (or pin) → user columns. The expand and row-actions columns can move to the
 * trailing/leading edge via `positionExpandColumn` / `positionActionsColumn`.
 */
export function useResolvedColumns<TData extends RowData>({
  columns,
  enableRowOrdering,
  enableRowSelection,
  selectAllMode,
  enableSelectAll,
  needsExpandColumn,
  positionExpandColumn,
  enableRowNumbers,
  rowNumberMode,
  enableRowPinning,
  renderRowActions,
  renderRowActionMenuItems,
  positionActionsColumn,
  enableEditing,
  editDisplayMode,
  localization,
  icons,
  displayColumnOptions,
}: UseResolvedColumnsParams<TData>): ReadonlyArray<
  DataTableColumnDef<TData, unknown>
> {
  // The overrides' functions are read through this ref, so the columns are
  // rebuilt only when their plain values change (see `optionsKey`).
  const optionsRef = React.useRef(displayColumnOptions)
  // eslint-disable-next-line react-hooks/refs
  optionsRef.current = displayColumnOptions
  const optionsKey = displayColumnOptionsKey(displayColumnOptions)

  // The column functions read the ref when they run, not during this render.
  /* eslint-disable react-hooks/refs */
  return React.useMemo(() => {
    const leading = []
    const trailing = []
    if (enableRowOrdering) {
      leading.push(createRowDragHandleColumn<TData>(localization, icons))
    }
    if (enableRowSelection) {
      leading.push(
        createSelectionColumn<TData>(
          localization,
          selectAllMode,
          enableSelectAll
        )
      )
    }
    if (needsExpandColumn) {
      const expand = createExpandColumn<TData>(localization, icons)
      if (positionExpandColumn === "last") trailing.push(expand)
      else leading.push(expand)
    }
    if (enableRowNumbers) {
      leading.push(
        createRowNumberColumn<TData>(
          localization,
          rowNumberMode,
          enableRowPinning,
          icons
        )
      )
    } else if (enableRowPinning) {
      leading.push(createRowPinColumn<TData>(localization, icons))
    }
    const showRowActions =
      !!renderRowActions ||
      !!renderRowActionMenuItems ||
      (enableEditing &&
        (editDisplayMode === "row" || editDisplayMode === "modal"))
    if (showRowActions) {
      const actions = createRowActionsColumn<TData>(positionActionsColumn)
      if (positionActionsColumn === "first") leading.unshift(actions)
      else trailing.push(actions)
    }
    const withOptions = (column: DataTableColumnDef<TData, unknown>) =>
      applyDisplayColumnOptions(column, () => optionsRef.current)
    return leading.length > 0 || trailing.length > 0
      ? [...leading.map(withOptions), ...columns, ...trailing.map(withOptions)]
      : columns
    // `optionsKey` stands in for the options themselves (read via the ref).
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    columns,
    enableRowOrdering,
    enableRowSelection,
    selectAllMode,
    enableSelectAll,
    needsExpandColumn,
    positionExpandColumn,
    enableRowNumbers,
    rowNumberMode,
    enableRowPinning,
    renderRowActions,
    renderRowActionMenuItems,
    positionActionsColumn,
    enableEditing,
    editDisplayMode,
    localization,
    icons,
    optionsKey,
  ])
  /* eslint-enable react-hooks/refs */
}

import * as React from "react"

import { LEAVE_COPY_SLOT, readMotionTokens } from "../core/motion"
import {
  MAX_ANIMATED_ROWS,
  planRowAnimations,
  type RowSnapshot,
} from "../helpers/plan-row-animations"

type Args = {
  /** The `<table>` element. */
  tableRef: React.RefObject<HTMLTableElement | null>
  /** Whether the table animates (see `useAnimationsActive`). */
  active: boolean
  /** Identities whose change means the rows may have moved, entered or left. */
  signal: unknown[]
  /** Every row key now (row ids + "<id>:detail" for open panels). Built only
   *  when `signal` changes. */
  members: () => ReadonlySet<string>
  /** True while rows must not move (a cell or row is being edited, or a new
   *  row created). Motion in flight stops when it turns true. A row drag in
   *  progress is detected by the hook itself (`tr[data-dragging]`). */
  paused: () => boolean
}

/** A copy of a leaving row and where it sat, relative to the motion layer. */
type Leaving = {
  node: HTMLTableRowElement
  top: number
  left: number
  width: number
  widths: number[]
}

/** What a change found before React touched the DOM. */
type Job = {
  prev: RowSnapshot
  members: ReadonlySet<string>
  leaving: Leaving[]
}

// The table's own rows: not the rows of a table nested in a detail panel.
const ROWS = ":scope > tbody > tr[data-row-id]"

// Attributes a leave copy drops so nothing mistakes it for the live row:
// keys the planner and grid navigation look up, ids, tab stops, and form
// control names (a copied checked radio would uncheck the live one).
const COPY_DROPS = [
  "id",
  "name",
  "for",
  "tabindex",
  "data-row-id",
  "data-cell-row",
  "data-cell-col",
  "data-index",
  "aria-rowindex",
  "aria-colindex",
]

// A detail panel opens top-down and closes bottom-up. Only clipped, never
// resized: the rows below already glide by the panel's height, so a height
// animation would move them twice (and lay the table out every frame).
const CLIPPED = "inset(0 0 100% 0)"
const REVEAL: Keyframe[] = [
  { clipPath: CLIPPED, opacity: 0 },
  { clipPath: "inset(0)", opacity: 1 },
]
const HIDE: Keyframe[] = [
  { clipPath: "inset(0)", opacity: 1 },
  { clipPath: CLIPPED, opacity: 0 },
]
const FADE: Keyframe[] = [{ opacity: 1 }, { opacity: 0 }]

const isDetail = (tr: HTMLTableRowElement) => tr.dataset.rowKind === "detail"

/** Whether the Web Animations API is there (jsdom has none). */
const canAnimate = () =>
  typeof Element !== "undefined" &&
  typeof Element.prototype.animate === "function"

function changed(a: unknown[] | null, b: unknown[]) {
  return !a || a.length !== b.length || a.some((v, i) => !Object.is(v, b[i]))
}

/** The drawn rows by key. */
function drawnRows(table: HTMLTableElement) {
  const rows = new Map<string, HTMLTableRowElement>()
  table.querySelectorAll<HTMLTableRowElement>(ROWS).forEach((tr) => {
    rows.set(tr.dataset.rowId!, tr)
  })
  return rows
}

/** Where each drawn row sits: px from the table's top edge. */
function topsOf(
  table: HTMLTableElement,
  rows: Map<string, HTMLTableRowElement>
) {
  const origin = table.getBoundingClientRect().top
  const tops = new Map<string, number>()
  for (const [key, tr] of rows) {
    tops.set(key, tr.getBoundingClientRect().top - origin)
  }
  return tops
}

function motionLayer(table: HTMLTableElement) {
  return table
    .closest('[data-slot="data-table-surface"]')
    ?.querySelector<HTMLElement>(
      ':scope > [data-slot="data-table-motion-layer"]'
    )
}

/**
 * How far down the motion layer shows its copies (it clips the rest): to the
 * table's bottom, or the surface's visible height if that is taller. That is
 * never past what the table itself scrolls to, so the copies never extend the
 * surface's scroll area: when a change shrinks the content, the browser
 * clamps the scroll with the change, rather than with a jump when the copies
 * go. The trade-off: in a scrolled surface, a leaving row that sat below the
 * table's new bottom is clipped instead of fading out. Reads only.
 */
function layerClip(layer: HTMLElement, table: HTMLTableElement) {
  const top = layer.getBoundingClientRect().top
  const bottom = table.getBoundingClientRect().bottom - top
  return Math.max(bottom, layer.parentElement?.clientHeight ?? 0)
}

/** An inert copy of a row to fade out in the motion layer. */
function copyRow(tr: HTMLTableRowElement) {
  const copy = tr.cloneNode(true) as HTMLTableRowElement
  for (const el of [copy, ...copy.querySelectorAll("*")]) {
    for (const name of COPY_DROPS) el.removeAttribute(name)
  }
  return copy
}

/**
 * Above this many gliding rows, their cells draw no border line while they
 * glide (the table's border is still cleared). The lines are box-shadow
 * animations, painted on the main thread every frame for every cell, and in
 * a reshuffle that large a missing separator for 280 ms goes unnoticed.
 */
const MAX_BORDER_LINES = 100

/**
 * The layers gliding rows paint on: above the rows they cross (whose pinned
 * cells sit at z 2), under the pinned row groups (z 10) and the sticky header
 * (z 20). The farther a row travels, the higher its layer, so a long glide
 * passes over the short ones instead of sliding under them.
 */
const GLIDE_Z = { min: 3, levels: 7 }

/** Each glide's layer, by its distance (equal distances share one). */
function glideLayers(dys: number[]) {
  const distances = dys.map(Math.abs).sort((a, b) => a - b)
  return dys.map((dy) => {
    const rank = distances.indexOf(Math.abs(dy))
    return GLIDE_Z.min + Math.floor((rank * GLIDE_Z.levels) / dys.length)
  })
}

/** A gliding row's bottom border, drawn by its cells (see `moveBorder`). */
type BorderLine = {
  tr: HTMLTableRowElement
  /** The border as an inset shadow line; null when the row has none. */
  line: string | null
  /** Each cell's own box-shadow, kept under the line. */
  shadows: string[]
}

/**
 * Reads what `moveBorder` needs. Reads only: every gliding row is read before
 * any animation starts, so the whole batch costs one style pass. (Rows don't
 * all share one border: the last row of a group usually has none.)
 */
function readBorder(tr: HTMLTableRowElement): BorderLine {
  const style = getComputedStyle(tr)
  const width = style.borderBottomWidth
  if (style.borderBottomStyle === "none" || width === "0px") {
    return { tr, line: null, shadows: [] }
  }
  return {
    tr,
    line: `inset 0 -${width} 0 0 ${style.borderBottomColor}`,
    shadows: [...tr.cells].map((cell) => getComputedStyle(cell).boxShadow),
  }
}

const CLEAR_BORDER: PropertyIndexedKeyframes = {
  borderBottomColor: ["transparent", "transparent"],
}

/**
 * The table draws a row's bottom border where the row is laid out, under its
 * cells and unmoved by the row's transform: a gliding row covers it, or it
 * cuts across whatever passes there. While the row glides, its cells draw the
 * border instead (an inset line on top of their own shadows: the selection
 * mark, a focus ring) and the table's stays clear. Writes only.
 */
function moveBorder({ tr, line, shadows }: BorderLine, duration: number) {
  if (!line) return []
  const lines = [...tr.cells].map((cell, i) => {
    const own = shadows[i] ?? "none"
    const shadow = own === "none" ? line : `${line}, ${own}`
    return cell.animate({ boxShadow: [shadow, shadow] }, { duration })
  })
  return [...lines, tr.animate(CLEAR_BORDER, { duration })]
}

/** Draws a leave copy at its row's last place and animates it out. */
function animateOutCopy(
  layer: HTMLElement,
  table: HTMLTableElement,
  { node, top, left, width, widths }: Leaving,
  keyframes: Keyframe[],
  options: KeyframeAnimationOptions,
  ghosts: Set<HTMLElement>,
  onRemoved: () => void
) {
  const ghost = document.createElement("table")
  ghost.className = table.className
  // Column size variables and the like live on the table's own style.
  ghost.style.cssText = table.style.cssText
  Object.assign(ghost.style, {
    position: "absolute",
    top: `${top}px`,
    left: `${left}px`,
    width: `${width}px`,
    minWidth: "0",
    margin: "0",
    tableLayout: "fixed",
  })
  ghost.inert = true
  ghost.setAttribute("data-slot", LEAVE_COPY_SLOT)
  ;[...node.cells].forEach((cell, i) => {
    const w = `${widths[i] ?? 0}px`
    Object.assign(cell.style, { width: w, minWidth: w, maxWidth: w })
  })
  const body = document.createElement("tbody")
  body.append(node)
  ghost.append(body)
  layer.append(ghost)
  ghosts.add(ghost)
  const remove = () => {
    ghost.remove()
    ghosts.delete(ghost)
    onRemoved()
  }
  ghost
    .animate(keyframes, { ...options, fill: "forwards" })
    .finished.then(remove, remove)
}

/**
 * Glides drawn rows to their new places, fades rows that entered the data in
 * and rows that left it out (from copies in the motion layer), using the Web
 * Animations API. Runs only when `signal` changes, never on scroll; the work
 * is proportional to the drawn rows, except `members()` (once per change).
 *
 * Must be called from a component that commits before the table body: its
 * insertion effect reads the rows as they were, before React updates them.
 * That leans on React's commit order, which is internal rather than
 * documented: a sibling's insertion effects run before the next sibling's DOM
 * mutations (React 19.2 runs a component's own insertion effects only after
 * its children's mutations, hence a sibling placed before `<table>`, see
 * `DataTableRowMotion`). If an upgrade changes that, the old positions and the
 * leave copies come from the new DOM. The browser tests in
 * `data-table.animations.browser.test.tsx` that guard it: "glides rows when
 * sorting", "fades out rows that leave and removes the copies", "draws a
 * leave copy where the row was, in a scrolled surface" and "hides a detail
 * panel as the rows below glide up".
 */
export function useRowAnimations({
  tableRef,
  active,
  signal,
  members,
  paused,
}: Args) {
  const lastSignal = React.useRef<unknown[] | null>(null)
  const lastMembers = React.useRef<ReadonlySet<string> | null>(null)
  const job = React.useRef<Job | null>(null)
  const running = React.useRef(new Set<Animation>())
  const ghosts = React.useRef(new Set<HTMLElement>())
  /** The motion layer, while it is sized to show copies (see `layerClip`). */
  const sized = React.useRef<HTMLElement | null>(null)

  /** Back to an empty, zero-height layer once no copy is left. */
  const unclip = () => {
    if (ghosts.current.size > 0 || !sized.current) return
    sized.current.style.removeProperty("height")
    sized.current = null
  }

  /** Drops the motion in flight, so it never plays against a new layout. */
  const stop = () => {
    for (const animation of running.current) animation.cancel()
    running.current.clear()
    for (const ghost of ghosts.current) ghost.remove()
    ghosts.current.clear()
    unclip()
  }

  // Before React touches the rows: where they sit, and copies of the rows
  // about to leave.
  React.useInsertionEffect(() => {
    job.current = null
    const isChange = changed(lastSignal.current, signal)
    lastSignal.current = signal
    if (!active || !canAnimate()) {
      lastMembers.current = null
      stop()
      return
    }
    // Unchanged rows: nothing to do, unless animations just turned on and
    // the next change needs a baseline, or an edit just started under motion
    // still in flight.
    if (!isChange && lastMembers.current) {
      const moving = running.current.size > 0 || ghosts.current.size > 0
      if (moving && paused()) stop()
      return
    }
    const next = members()
    const prev = lastMembers.current
    lastMembers.current = next
    // On the first commit the table is not attached yet: `next` is the
    // baseline for the next change.
    const table = tableRef.current
    if (!prev || !table) return
    if (paused() || table.querySelector(":scope > tbody > tr[data-dragging]")) {
      stop()
      return
    }
    const rows = drawnRows(table)
    // Far more drawn rows than could animate: the planner would skip this
    // change, so skip it before reading every row's position.
    if (rows.size > 3 * MAX_ANIMATED_ROWS) {
      stop()
      return
    }
    const tops = topsOf(table, rows)
    const gone = [...rows.keys()].filter((key) => !next.has(key))
    const layer = motionLayer(table)
    const leaving: Leaving[] = []
    // Past the limit the planner skips the change, so copy nothing.
    if (layer && gone.length <= MAX_ANIMATED_ROWS) {
      const base = layer.getBoundingClientRect()
      for (const key of gone) {
        const tr = rows.get(key)!
        const rect = tr.getBoundingClientRect()
        leaving.push({
          node: copyRow(tr),
          top: rect.top - base.top,
          left: rect.left - base.left,
          width: rect.width,
          widths: [...tr.cells].map((c) => c.getBoundingClientRect().width),
        })
      }
    }
    job.current = { prev: { members: prev, tops }, members: next, leaving }
  })

  // After the update: glide, fade in, and fade out the copies.
  React.useLayoutEffect(() => {
    const work = job.current
    job.current = null
    const table = tableRef.current
    if (!work || !table) return
    // Rows mid-animation were measured where they showed; restart from
    // there. The previous change's leave copies would fade over the new
    // layout: drop them too.
    stop()
    const live = running.current

    const rows = drawnRows(table)
    const plan = planRowAnimations(work.prev, {
      members: work.members,
      tops: topsOf(table, rows),
    })
    if (plan.skipped) {
      stop()
      return
    }
    const { duration, durationFast, ease } = readMotionTokens(table)
    const layer = work.leaving.length > 0 ? motionLayer(table) : null
    const clip = layer ? layerClip(layer, table) : 0
    const track = (animation: Animation) => {
      live.add(animation)
      const done = () => live.delete(animation)
      animation.finished.then(done, done)
    }

    const glides = plan.moves.flatMap(({ key, dy }) => {
      const tr = rows.get(key)
      return tr ? [{ tr, dy }] : []
    })
    // All reads before the first animation: a read after a write would
    // force another style pass, once per row.
    const borders =
      glides.length <= MAX_BORDER_LINES
        ? glides.map(({ tr }) => readBorder(tr))
        : null
    const layers = glideLayers(glides.map(({ dy }) => dy))
    glides.forEach(({ tr, dy }, i) => {
      // Positioned only while it glides, so its z-index applies; sticky
      // pinned cells inside it stay sticky.
      const layer = { position: "relative", zIndex: layers[i] }
      track(
        tr.animate(
          [
            { transform: `translateY(${dy}px)`, ...layer },
            { transform: "none", ...layer },
          ],
          { duration, easing: ease }
        )
      )
      const border = borders?.[i]
      if (border) {
        for (const animation of moveBorder(border, duration)) track(animation)
      } else if (!borders) {
        track(tr.animate(CLEAR_BORDER, { duration }))
      }
    })
    // Rows new to a virtual window came with the change (from outside the
    // drawn rows, so there is no place to glide from): they fade in too, at
    // once, as the rows they replace are gone (still in the data: no copies).
    const arrived = new Set(plan.arrivals)
    for (const key of [...plan.enters, ...plan.arrivals]) {
      const tr = rows.get(key)
      if (!tr) continue
      if (isDetail(tr)) {
        // Clip the cells (the panel is one full-width cell). Same timing as
        // the glide, so the panel's bottom edge and the row below move
        // together.
        for (const cell of tr.cells) {
          track(
            cell.animate(REVEAL, {
              duration,
              easing: ease,
              fill: "backwards",
            })
          )
        }
        // The table draws the row's collapsed bottom border, which no clip
        // or opacity on the cells or the row hides: keep it clear until the
        // panel's bottom edge reaches it.
        track(tr.animate(CLEAR_BORDER, { duration }))
        continue
      }
      track(
        tr.animate(
          [
            { opacity: 0, transform: "translateY(4px)" },
            { opacity: 1, transform: "none" },
          ],
          {
            duration: durationFast,
            easing: ease,
            // Starts as the leaving rows fade; hidden until then.
            delay: arrived.has(key) ? 0 : durationFast / 2,
            fill: "backwards",
          }
        )
      )
    }
    if (!layer) return
    layer.style.height = `${clip}px`
    sized.current = layer
    for (const copy of work.leaving) {
      // A panel closes with the glide of the rows below; other rows fade.
      const detail = isDetail(copy.node)
      animateOutCopy(
        layer,
        table,
        copy,
        detail ? HIDE : FADE,
        { duration: detail ? duration : durationFast, easing: ease },
        ghosts.current,
        unclip
      )
    }
  })

  React.useEffect(() => {
    const live = running.current
    const copies = ghosts.current
    return () => {
      for (const animation of live) animation.cancel()
      live.clear()
      for (const ghost of copies) ghost.remove()
      copies.clear()
    }
  }, [])
}

"use client"

import type { RowData } from "@tanstack/react-table"
import * as React from "react"

import { dt } from "../core/internal"
import type { DataTableInstance } from "../core/types"

const sameSet = (a: readonly string[], b: readonly string[]) =>
  a.length === b.length && a.every((id) => b.includes(id))

/**
 * Supports `rowPinningDisplayMode`:
 * - publishes the sticky header's and footer's heights on the scroll surface
 *   (`--dt-head-h`, `--dt-foot-h`), so pinned row groups stick just inside
 *   them;
 * - in the select modes, keeps `rowPinning` equal to the selected rows (new
 *   selections are added after the rows already pinned).
 */
export function useRowPinningDisplay<TData extends RowData>({
  table,
  surfaceRef,
  stickyHeader,
  stickyFooter,
}: {
  table: DataTableInstance<TData>
  surfaceRef: React.RefObject<HTMLElement | null>
  stickyHeader: boolean
  stickyFooter: boolean
}) {
  React.useLayoutEffect(() => {
    const surface = surfaceRef.current
    const { tableHeadRef, tableFooterRef } = table.dataTable.refs
    if (!surface) return
    const publish = () => {
      const head = stickyHeader ? (tableHeadRef.current?.offsetHeight ?? 0) : 0
      const foot = stickyFooter
        ? (tableFooterRef.current?.offsetHeight ?? 0)
        : 0
      surface.style.setProperty("--dt-head-h", `${head}px`)
      surface.style.setProperty("--dt-foot-h", `${foot}px`)
    }
    publish()
    if (typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(publish)
    for (const el of [tableHeadRef.current, tableFooterRef.current]) {
      if (el) observer.observe(el)
    }
    return () => observer.disconnect()
  }, [table, surfaceRef, stickyHeader, stickyFooter])

  React.useEffect(() => {
    const sync = () => {
      const mode = dt(table).rowPinningDisplayMode
      if (mode !== "select-top" && mode !== "select-bottom") return
      const { rowSelection, rowPinning } = table.getState()
      const selected = Object.keys(rowSelection).filter(
        (id) => rowSelection[id]
      )
      const side = mode === "select-top" ? "top" : "bottom"
      const current = [...(rowPinning.top ?? []), ...(rowPinning.bottom ?? [])]
      const next = [
        ...current.filter((id) => selected.includes(id)),
        ...selected.filter((id) => !current.includes(id)),
      ]
      const pinnedSide = rowPinning[side] ?? []
      const otherSide = rowPinning[side === "top" ? "bottom" : "top"] ?? []
      if (sameSet(pinnedSide, next) && otherSide.length === 0) return
      table.setRowPinning(
        side === "top" ? { top: next, bottom: [] } : { top: [], bottom: next }
      )
    }
    sync()
    const subscription = table.store.subscribe(sync)
    return () => subscription.unsubscribe()
  }, [table])
}

"use client"

import {
  KeyboardSensor,
  PointerSensor,
  closestCenter,
  pointerWithin,
  useSensor,
  useSensors,
  type CollisionDetection,
  type DragEndEvent,
} from "@dnd-kit/core"
import { arrayMove, sortableKeyboardCoordinates } from "@dnd-kit/sortable"
import type { RowData } from "@tanstack/react-table"

import type { DataTableInstance } from "../core/types"
import { dt } from "../core/internal"

/**
 * Sensors + drag-end handler for the single `DndContext` that drives both
 * column and row reordering. The active item's `data.type` (set in useSortable)
 * routes to the right handler — two nested contexts can't be used: dnd-kit
 * renders an a11y `<div>` that is invalid inside `<tbody>`, and a body-wrapping
 * context would swallow header drags.
 */
type DragData = { type?: string; rowId?: string; columnId?: string }

export function useTableDnd<TData extends RowData>(
  table: DataTableInstance<TData>
) {
  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  )

  // The group drop zone should accept a drop anywhere inside its bounds, not
  // only near its center. Prefer a pointer-within hit on the zone; otherwise
  // fall back to closestCenter for column/row reordering (and keyboard dnd,
  // where pointerWithin yields nothing). Only targets of the dragged item's
  // own type are considered, so a row can't land on a header and vice versa;
  // the untyped group zone is reachable by column drags only.
  const collisionDetection: CollisionDetection = (args) => {
    const activeType = args.active.data.current?.type
    const isGroupZone = (id: string | number) =>
      args.droppableContainers.find((c) => c.id === id)?.data.current?.type ===
      "group-zone"
    if (activeType === "column") {
      const groupHit = pointerWithin(args).find((c) => isGroupZone(c.id))
      if (groupHit) return [groupHit]
    }
    const sameType = args.droppableContainers.filter(
      (c) =>
        c.data.current?.type === activeType ||
        (activeType === "column" && c.data.current?.type === "group-zone")
    )
    return closestCenter({ ...args, droppableContainers: sameType })
  }

  const onRowOrderChange = dt(table).onRowOrderChange

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event
    if (!over) return
    // Ids may carry a provider prefix; the drag data has the plain ones.
    const from = (active.data.current ?? {}) as DragData
    const to = (over.data.current ?? {}) as DragData

    if (from.type === "row") {
      // Reordering applies with row ordering on (a row may be draggable only
      // to move it out of the table).
      if (!dt(table).enableRowOrdering || to.type !== "row") return
      if (from.rowId !== to.rowId) {
        onRowOrderChange?.(from.rowId!, to.rowId!)
      }
      return
    }

    // column drag → drop on the group zone groups by that column
    if (to.type === "group-zone") {
      const column = table.getColumn(from.columnId!)
      if (column && !column.getIsGrouped()) column.toggleGrouping()
      return
    }
    // Otherwise it's a reorder, which only applies when ordering is enabled
    // (a column may be draggable solely to support drag-to-group).
    if (!dt(table).enableColumnOrdering) return
    if (from.columnId === to.columnId) return
    const base =
      table.getState().columnOrder.length > 0
        ? table.getState().columnOrder
        : table.getAllLeafColumns().map((c) => c.id)
    const oldIndex = base.indexOf(from.columnId!)
    const newIndex = base.indexOf(to.columnId!)
    if (oldIndex === -1 || newIndex === -1) return
    table.setColumnOrder(arrayMove(base, oldIndex, newIndex))
  }

  return { sensors, collisionDetection, handleDragEnd }
}

"use client"

import * as React from "react"

import type { DataTableState } from "../helpers/table-state"

/** The table, as far as store subscriptions need it. */
interface StoreTable {
  store: { subscribe: (listener: () => void) => { unsubscribe: () => void } }
  getState: () => DataTableState
}

/** Equal when both are the same value, or arrays / plain objects whose items
 *  are the same values (one level deep). */
export function shallowEqual(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true
  if (
    typeof a !== "object" ||
    typeof b !== "object" ||
    a === null ||
    b === null ||
    Array.isArray(a) !== Array.isArray(b)
  ) {
    return false
  }
  const aKeys = Object.keys(a)
  if (aKeys.length !== Object.keys(b).length) return false
  return aKeys.every((key) =>
    Object.is(
      (a as Record<string, unknown>)[key],
      (b as Record<string, unknown>)[key]
    )
  )
}

/**
 * Subscribes a component to part of the table state: it re-renders only when
 * the selected value changes (compared shallowly), however often the rest of
 * the state changes.
 */
export function useTableState<T>(
  table: StoreTable,
  selector: (state: DataTableState) => T
): T {
  const selectorRef = React.useRef(selector)
  const cacheRef = React.useRef<{ value: T } | null>(null)
  // eslint-disable-next-line react-hooks/refs
  selectorRef.current = selector

  const subscribe = React.useCallback(
    (onChange: () => void) => {
      const subscription = table.store.subscribe(onChange)
      return () => subscription.unsubscribe()
    },
    [table]
  )
  // Hands React the previous value while the selection is shallowly equal,
  // so an unrelated state change does not re-render.
  const getSnapshot = () => {
    const next = selectorRef.current(table.getState())
    const cached = cacheRef.current
    if (cached && shallowEqual(cached.value, next)) return cached.value
    cacheRef.current = { value: next }
    return next
  }
  return React.useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

/**
 * Calls `listener` after every table state change, outside React renders.
 * For effects that react to state (resetting the page when filters change),
 * which must not depend on the component re-rendering.
 */
export function useTableStateListener(
  table: StoreTable,
  listener: () => void
): void {
  const listenerRef = React.useRef(listener)
  React.useLayoutEffect(() => {
    listenerRef.current = listener
  })
  React.useEffect(() => {
    const subscription = table.store.subscribe(() => listenerRef.current())
    return () => subscription.unsubscribe()
  }, [table])
}

"use client"

import type { RowData } from "@tanstack/react-table"
import { useVirtualizer } from "@tanstack/react-virtual"
import * as React from "react"

import type { DataTableInstance } from "../core/types"
import { getPinSide } from "../helpers/column-pinning"
import { pinnedRangeExtractor } from "../helpers/pinned-range-extractor"
import { resolveRowHeight } from "../helpers/resolve-row-height"
import { getVirtualHeaderRuns } from "../helpers/virtual-header-runs"
import type { DataTableRow } from "../core/table-types"
import { dt } from "../core/internal"

export interface VirtualRowItem<TData extends RowData> {
  row: DataTableRow<TData>
  /** The row's index among the center rows. */
  index: number
  detail: boolean
}

/** Lays out one cell per virtual column with spacers for the skipped columns. */
export type WithColumnSpacers = (
  cells: React.ReactNode[],
  keyPrefix: string
) => React.ReactNode

/** Where a header cell lands under column virtualization. */
export interface VirtualHeaderLayout {
  key: string
  /** Rendered columns the cell spans (fewer than `colSpan` when cut off). */
  colSpan: number
  /** Width override when the cell spans only part of its columns. */
  widthStyle?: React.CSSProperties
}

/** Lays out one header/footer row (any depth) with spacers. */
export type WithHeaderSpacers = <H extends { id: string; colSpan: number }>(
  headers: H[],
  render: (header: H, layout: VirtualHeaderLayout) => React.ReactNode,
  keyPrefix: string
) => React.ReactNode

/**
 * Row + column virtualization for {@link DataTable}. Builds the flattened
 * virtualization list (center rows + their expanded detail panels), wires both
 * `@tanstack/react-virtual` instances, exposes them via the optional instance
 * refs, and returns the helpers the header/body/footer need to render only the
 * visible window with left/right column spacers.
 */
export function useTableVirtualizers<TData extends RowData>(
  table: DataTableInstance<TData>,
  gridRef: React.RefObject<HTMLDivElement | null>
) {
  const {
    enableRowVirtualization,
    enableColumnVirtualization,
    renderDetailPanel,
    estimateRowHeight,
    rowHeight,
    getRowHeight,
    virtualOverscan,
    rowVirtualizerOptions,
    columnVirtualizerOptions,
    rowVirtualizerInstanceRef,
    columnVirtualizerInstanceRef,
    direction,
  } = dt(table)

  // Flatten center rows (+ expanded detail panels) into a virtualization list.
  // It walks every row, so it is rebuilt only when the rows or their expansion
  // change, not on each scroll frame.
  const centerRows = table.getCenterRows()
  const expanded = table.getState().expanded
  const getIsRowExpanded = table.options.getIsRowExpanded
  const hasDetailPanel = !!renderDetailPanel
  const virtualItems = React.useMemo(() => {
    const items: VirtualRowItem<TData>[] = []
    if (!enableRowVirtualization) return items
    centerRows.forEach((row, index) => {
      items.push({ row, index, detail: false })
      if (hasDetailPanel && row.getIsExpanded() && !row.getIsGrouped()) {
        items.push({ row, index, detail: true })
      }
    })
    return items
    // Read through `row.getIsExpanded()`.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    enableRowVirtualization,
    hasDetailPanel,
    centerRows,
    expanded,
    getIsRowExpanded,
  ])

  // User-supplied passthrough options, resolved from their value-or-function form.
  const rowVOptions =
    typeof rowVirtualizerOptions === "function"
      ? rowVirtualizerOptions({ table })
      : rowVirtualizerOptions
  const columnVOptions =
    typeof columnVirtualizerOptions === "function"
      ? columnVirtualizerOptions({ table })
      : columnVirtualizerOptions

  // The React Compiler bails on TanStack Virtual's mutable instance; expected.
  // eslint-disable-next-line react-hooks/incompatible-library
  const rowVirtualizer = useVirtualizer({
    count: virtualItems.length,
    getScrollElement: () => gridRef.current,
    // Per-row estimate: an exact px number pins the row; "auto" (or no override)
    // uses the flat estimate and lets `measureElement` correct to the real
    // height. Detail-panel rows always fall back to the flat estimate.
    estimateSize: (index) => {
      const item = virtualItems[index]
      if (!item || item.detail) return estimateRowHeight
      const resolved = resolveRowHeight(item.row, { rowHeight, getRowHeight })
      return typeof resolved === "number" ? resolved : estimateRowHeight
    },
    overscan: virtualOverscan,
    measureElement:
      typeof window !== "undefined"
        ? (el) => el?.getBoundingClientRect().height ?? 0
        : undefined,
    ...rowVOptions,
  })

  // Horizontal virtualizer for wide tables. When off, count is 0 and the
  // helpers below fall through to rendering all columns. Leaf columns are taken
  // in render order (pinned columns moved to the edges, as cells and headers
  // are); `getVisibleLeafColumns` ignores pinning.
  const leafColumns = (table.getHeaderGroups().at(-1)?.headers ?? []).map(
    (header) => header.column
  )
  const pinnedIndexes = leafColumns.flatMap((column, index) =>
    getPinSide(column) ? [index] : []
  )
  const columnVirtualizer = useVirtualizer({
    horizontal: true,
    count: enableColumnVirtualization ? leafColumns.length : 0,
    getScrollElement: () => gridRef.current,
    estimateSize: (index) => leafColumns[index]?.getSize() ?? 150,
    getItemKey: (index) => leafColumns[index]?.id ?? index,
    // Pinned columns are sticky, so they must render even when scrolled out.
    rangeExtractor: (range) => pinnedRangeExtractor(range, pinnedIndexes),
    // Right-to-left scroll offsets run negative.
    isRtl: direction === "rtl",
    overscan: virtualOverscan,
    ...columnVOptions,
  })

  // Sizes are estimates, which the virtualizer caches; re-measure when a
  // column is resized, reordered, hidden or pinned.
  const columnLayoutKey = leafColumns
    .map((column) => `${column.id}:${column.getSize()}`)
    .join()
  React.useEffect(() => {
    if (enableColumnVirtualization) columnVirtualizer.measure()
  }, [columnLayoutKey, enableColumnVirtualization, columnVirtualizer])

  // Expose the virtualizer instances for imperative control (e.g. scrollToIndex).
  React.useEffect(() => {
    if (rowVirtualizerInstanceRef)
      rowVirtualizerInstanceRef.current = rowVirtualizer
  })
  React.useEffect(() => {
    if (columnVirtualizerInstanceRef)
      columnVirtualizerInstanceRef.current = columnVirtualizer
  })

  const virtualColumns = enableColumnVirtualization
    ? columnVirtualizer.getVirtualItems()
    : []
  const totalColumnWidth = columnVirtualizer.getTotalSize()

  /**
   * Lays out a row's cells (one per virtual column, in the same order) with a
   * spacer wherever columns are skipped: before the window, after it, and
   * between the window and any pinned columns rendered outside it.
   */
  const withColumnSpacers = (
    cells: React.ReactNode[],
    keyPrefix: string
  ): React.ReactNode => {
    if (!enableColumnVirtualization) return cells
    // An empty cell collapses under auto table layout unless it has a min width.
    const spacer = (key: string, width: number) => (
      <td
        key={`${keyPrefix}-${key}`}
        aria-hidden
        style={{ width, minWidth: width, padding: 0 }}
      />
    )
    const out: React.ReactNode[] = []
    let end = 0
    virtualColumns.forEach((vc, i) => {
      if (vc.start > end) out.push(spacer(`gap-${vc.index}`, vc.start - end))
      out.push(cells[i])
      end = vc.end
    })
    if (totalColumnWidth > end)
      out.push(spacer("gap-end", totalColumnWidth - end))
    return out
  }

  /**
   * Header and footer rows hold group headers spanning several columns, so
   * each rendered column maps to the header covering it, and adjacent columns
   * under one header share a cell.
   */
  const withHeaderSpacers: WithHeaderSpacers = (headers, render, keyPrefix) => {
    const cells: React.ReactNode[] = virtualColumns.map(() => null)
    const runs = getVirtualHeaderRuns(
      headers,
      virtualColumns.map((vc) => vc.index)
    )
    for (const { header, start, span } of runs) {
      const covered = virtualColumns.slice(start, start + span)
      const width = covered.reduce((sum, vc) => sum + vc.size, 0)
      cells[start] = render(header, {
        key: `${header.id}-${covered[0]!.index}`,
        colSpan: span,
        widthStyle:
          span < header.colSpan ? { width, minWidth: width } : undefined,
      })
    }
    return withColumnSpacers(cells, keyPrefix)
  }

  // Kept stable while the rendered column window is unchanged, so the
  // (memoized) header and footer skip renders that do not move it.
  const columnWindowKey = [
    enableColumnVirtualization,
    totalColumnWidth,
    ...virtualColumns.map((vc) => `${vc.index}:${vc.start}:${vc.size}`),
  ].join()
  const stableHeaderSpacers = React.useMemo(
    () => withHeaderSpacers,
    // The key captures everything the function reads.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [columnWindowKey]
  )

  return {
    rowVirtualizer,
    columnVirtualizer,
    virtualItems,
    virtualColumns,
    withColumnSpacers,
    withHeaderSpacers: stableHeaderSpacers,
  }
}

"use client"

import type { RowData } from "@tanstack/react-table"
import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"

import type { DataTableInstance } from "../core/types"
import type { DataTableColumnDef, DataTableRow } from "../core/table-types"
import { stopPropagation } from "../helpers/stop-propagation"
import { dt } from "../core/internal"

export const ROW_ACTIONS_COLUMN_ID = "cn-row-actions"

/** Actions column: edit/save/cancel controls + the consumer's
 *  `renderRowActions` slot. When positioned `"first"` the controls align to the
 *  left edge; when `"last"` (default) they align to the right. */
export function createRowActionsColumn<TData extends RowData>(
  position: "first" | "last" = "last"
): DataTableColumnDef<TData> {
  const align = position === "first" ? "left" : "right"
  return {
    id: ROW_ACTIONS_COLUMN_ID,
    enableSorting: false,
    enableHiding: false,
    enableColumnFilter: false,
    enableResizing: false,
    enableGrouping: false,
    size: 90,
    minSize: 80,
    meta: { enableColumnActions: false, align },
    // Named for screen readers; the column shows no header text.
    header: ({ table }) => (
      <span className="sr-only">
        {dt(table as never).localization.rowActions}
      </span>
    ),
    cell: ({ row, table }) => (
      <RowActionsCell
        row={row}
        table={table as DataTableInstance<TData>}
        align={align}
      />
    ),
  }
}

function RowActionsCell<TData extends RowData>({
  row,
  table,
  align,
}: {
  row: DataTableRow<TData>
  table: DataTableInstance<TData>
  align: "left" | "right"
}) {
  const justify = align === "left" ? "justify-start" : "justify-end"
  const {
    localization,
    icons,
    enableEditing,
    getCanEditRow,
    editDisplayMode,
    editingRowId,
    rowDraft,
    onEditingRowSave,
    beginRowEdit,
    cancelEdit,
    cancelEditing,
    renderRowActions,
    renderRowActionMenuItems,
  } = dt(table)

  const isEditingThisRow = editDisplayMode === "row" && editingRowId === row.id
  const [menuOpen, setMenuOpen] = React.useState(false)

  if (isEditingThisRow) {
    return (
      <div
        className={`flex items-center gap-1 ${justify}`}
        onClick={stopPropagation}
        onDoubleClick={stopPropagation}
      >
        <Button
          variant="ghost"
          size="icon"
          aria-label={localization.save}
          className="size-7"
          onClick={() =>
            onEditingRowSave?.({
              row,
              values: rowDraft,
              table,
              exit: cancelEdit,
            })
          }
        >
          <icons.save />
        </Button>
        <Button
          variant="ghost"
          size="icon"
          aria-label={localization.cancel}
          className="size-7"
          onClick={cancelEditing}
        >
          <icons.cancel />
        </Button>
      </div>
    )
  }

  const canInlineEdit =
    enableEditing &&
    getCanEditRow(row) &&
    (editDisplayMode === "row" || editDisplayMode === "modal")

  return (
    <div
      className={`flex items-center gap-1 ${justify}`}
      onClick={stopPropagation}
      onDoubleClick={stopPropagation}
    >
      {canInlineEdit && !renderRowActionMenuItems && (
        <Button
          variant="ghost"
          size="icon"
          aria-label={localization.edit}
          className="size-7"
          onClick={() => beginRowEdit(row)}
        >
          <icons.edit />
        </Button>
      )}
      {renderRowActions?.({ row, table })}
      {renderRowActionMenuItems && (
        <DropdownMenu open={menuOpen} onOpenChange={setMenuOpen}>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              aria-label={localization.rowActions}
              className="size-7"
            >
              <icons.columnActions />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            {renderRowActionMenuItems({
              row,
              table,
              // The edit action lives in the menu when there is one.
              internalMenuItems: canInlineEdit ? (
                <DropdownMenuItem onClick={() => beginRowEdit(row)}>
                  <icons.edit />
                  {localization.edit}
                </DropdownMenuItem>
              ) : null,
              closeMenu: () => setMenuOpen(false),
            })}
          </DropdownMenuContent>
        </DropdownMenu>
      )}
    </div>
  )
}

