import type { RowData } from "@tanstack/react-table"

import { cn } from "@/lib/utils"

import type { DataTableIcons } from "../core/icons"
import type { DataTableLocalization } from "../core/localization"
import type { DataTableRow } from "../core/table-types"
import { stopPropagation } from "../helpers/stop-propagation"
import { dt } from "../core/internal"

/** Pin / unpin toggle for one row (pins to the top). Shared by the row-number
 *  column (hover-revealed) and the standalone pin column (always visible). */
export function RowPinButton<TData extends RowData>({
  row,
  localization,
  icons,
  className,
}: {
  row: DataTableRow<TData>
  localization: DataTableLocalization
  icons: DataTableIcons
  className?: string
}) {
  const pinned = row.getIsPinned()
  // `rowPinningDisplayMode: "bottom"` pins to the bottom; other modes the top.
  const side =
    dt(row.table as never).rowPinningDisplayMode === "bottom" ? "bottom" : "top"
  return (
    <button
      type="button"
      aria-label={pinned ? localization.unpinRow : localization.pinRow}
      aria-pressed={!!pinned}
      onClick={(event) => {
        stopPropagation(event)
        row.pin(pinned ? false : side)
      }}
      onDoubleClick={stopPropagation}
      className={cn(
        "flex items-center justify-center text-muted-foreground transition-opacity outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/40",
        pinned && "text-primary",
        className
      )}
    >
      {pinned ? (
        <icons.pinnedRow className="size-3.5" />
      ) : (
        <icons.pin className="size-3.5" />
      )}
    </button>
  )
}

"use client"

import type { RowData } from "@tanstack/react-table"

import { SelectionCheckbox } from "../components/body/selection-checkbox"
import type { DataTableLocalization } from "../core/localization"
import type { DataTableColumnDef } from "../core/table-types"
import { getSlotProps } from "../helpers/slot-props"
import type { DataTableCoreTable, DataTableRow } from "../core/table-types"
import { dt } from "../core/internal"

export const SELECTION_COLUMN_ID = "cn-select"

/** The row last clicked in each table: the anchor of a shift-click range. */
const rangeAnchors = new WeakMap<object, string>()

/**
 * Toggles `row`; with shift held (and batch selection on) sets every row from
 * the last-clicked one to `row`, in display order, to the same value.
 */
function toggleRow<TData extends RowData>(
  table: DataTableCoreTable<TData>,
  row: DataTableRow<TData>,
  value: boolean,
  shiftKey: boolean
) {
  const anchorId = rangeAnchors.get(table)
  rangeAnchors.set(table, row.id)
  const batch =
    shiftKey &&
    anchorId != null &&
    anchorId !== row.id &&
    table.options.enableMultiRowSelection !== false &&
    dt(table as never).enableBatchRowSelection
  if (!batch) {
    row.toggleSelected(value)
    return
  }
  // Display order: top-pinned, then the rest, then bottom-pinned.
  const rows = [
    ...table.getTopRows(),
    ...table.getCenterRows(),
    ...table.getBottomRows(),
  ]
  const from = rows.findIndex((r) => r.id === anchorId)
  const to = rows.findIndex((r) => r.id === row.id)
  if (from === -1 || to === -1) {
    row.toggleSelected(value)
    return
  }
  const range = rows.slice(Math.min(from, to), Math.max(from, to) + 1)
  table.setRowSelection((prev) => {
    const next = { ...prev }
    for (const r of range) {
      if (!r.getCanSelect()) continue
      if (value) next[r.id] = true
      else delete next[r.id]
    }
    return next
  })
}

/**
 * Builds the auto-injected selection column. The header carries the
 * select-all checkbox (with indeterminate state) for multi-select tables; for
 * single-select tables the header is empty. `selectAllMode` selects the current
 * page ("page", default) or every row ("all"); `enableSelectAll: false` hides
 * the header checkbox. Clicks are isolated from row click handlers via
 * `stopPropagation`.
 */
export function createSelectionColumn<TData extends RowData>(
  localization: DataTableLocalization,
  selectAllMode: "page" | "all" = "page",
  enableSelectAll = true
): DataTableColumnDef<TData> {
  return {
    id: SELECTION_COLUMN_ID,
    enableSorting: false,
    enableHiding: false,
    enableColumnFilter: false,
    enableResizing: false,
    size: 44,
    minSize: 44,
    meta: { enableColumnActions: false, align: "center" },
    header: ({ table }) => {
      // No select-all affordance for single-select tables or when disabled;
      // the header still names the column for screen readers.
      if (!enableSelectAll || table.options.enableMultiRowSelection === false)
        return <span className="sr-only">{localization.selectRow}</span>
      const allMode = selectAllMode === "all"
      const allSelected = allMode
        ? table.getIsAllRowsSelected()
        : table.getIsAllPageRowsSelected()
      const someSelected = allMode
        ? table.getIsSomeRowsSelected()
        : table.getIsSomePageRowsSelected()
      return (
        <div
          className="flex items-center justify-center"
          onClick={(e) => e.stopPropagation()}
          onDoubleClick={(e) => e.stopPropagation()}
        >
          <SelectionCheckbox
            {...getSlotProps(table as never, "selectCheckbox", {})}
            aria-label={localization.selectAll}
            checked={allSelected}
            indeterminate={someSelected && !allSelected}
            onCheckedChange={(value) =>
              allMode
                ? table.toggleAllRowsSelected(!!value)
                : table.toggleAllPageRowsSelected(!!value)
            }
          />
        </div>
      )
    },
    cell: ({ row, table }) => {
      const single = table.options.enableMultiRowSelection === false
      return (
        <div
          className="flex items-center justify-center"
          onClick={(e) => e.stopPropagation()}
          onDoubleClick={(e) => e.stopPropagation()}
        >
          <SelectionCheckbox
            {...getSlotProps(table as never, "selectCheckbox", {
              row: row as never,
            })}
            aria-label={localization.selectRow}
            variant={single ? "radio" : "checkbox"}
            checked={row.getIsSelected()}
            disabled={!row.getCanSelect()}
            onCheckedChange={(value, event) =>
              toggleRow(
                table as unknown as DataTableCoreTable<TData>,
                row as unknown as DataTableRow<TData>,
                value,
                event.shiftKey
              )
            }
          />
        </div>
      )
    },
  }
}

import type { RowData } from "@tanstack/react-table"
import type { CSSProperties } from "react"

import type { DataTableInstance } from "../core/types"
import type { DataTableColumn, DataTableCoreTable } from "../core/table-types"
import {
  getPinOffset,
  getPinSide,
  isPinnedEdgeColumn,
} from "../helpers/column-pinning"
import { dt } from "../core/internal"

/**
 * Sticky positioning for a pinned column. Offsets come from TanStack
 * (`getStart`/`getAfter`) so multiple pinned columns stack correctly.
 */
export function getColumnPinningStyle<TData extends RowData, TValue>(
  column: DataTableColumn<TData, TValue>
): CSSProperties {
  const side = getPinSide(column)
  if (!side) return {}
  // Logical insets: a left (start) pinned column sticks to the right edge in a
  // right-to-left table, matching where TanStack's column order puts it.
  const inset = side === "left" ? "insetInlineStart" : "insetInlineEnd"
  return { position: "sticky", zIndex: 2, [inset]: getPinOffset(column, side) }
}

/**
 * Edge-shadow class for the boundary pinned columns (last left / first right),
 * built from `--border` (via a utility) so it reads in light and dark.
 */
export function getColumnPinningClass<TData extends RowData, TValue>(
  column: DataTableColumn<TData, TValue>
): string {
  const side = getPinSide(column)
  if (!side || !isPinnedEdgeColumn(column, side)) return ""
  return side === "left"
    ? "after:pointer-events-none after:absolute after:inset-y-0 after:-end-px after:w-2 after:translate-x-full after:bg-gradient-to-r after:from-border/60 after:to-transparent rtl:after:-translate-x-full rtl:after:bg-gradient-to-l"
    : "before:pointer-events-none before:absolute before:inset-y-0 before:-start-px before:w-2 before:-translate-x-full before:bg-gradient-to-l before:from-border/60 before:to-transparent rtl:before:translate-x-full rtl:before:bg-gradient-to-r"
}

/** Column ids go into CSS custom-property names; ASCII punctuation and spaces
 *  (dots, slashes…) would make `var()` invalid. Non-ASCII letters are valid
 *  name characters, so ids like `fødsel` and `fådsel` stay distinct. */
export function cssVarId(id: string): string {
  return id.replace(/[^A-Za-z0-9_\u0080-￿-]/g, "_")
}

/**
 * CSS custom properties holding each column's size, set once on the table
 * element. Cells read them via `width: calc(var(--col-…-size) * 1px)` so a
 * resize drag updates a variable instead of re-rendering every cell.
 */
export function getColumnSizeVars<TData extends RowData>(
  table: DataTableCoreTable<TData>
): Record<string, string> {
  const headers = table.getFlatHeaders()
  const vars: Record<string, string> = {}
  for (const header of headers) {
    vars[`--header-${cssVarId(header.id)}-size`] = `${header.getSize()}`
    vars[`--col-${cssVarId(header.column.id)}-size`] =
      `${header.column.getSize()}`
  }
  return vars
}

export function getColumnWidthStyle(columnId: string): CSSProperties {
  return { width: `calc(var(--col-${cssVarId(columnId)}-size) * 1px)` }
}

/**
 * Resolves a column's width style. While resizing, widths come from CSS vars.
 * Otherwise honor an explicitly defined `columnDef.size` (MRT behaviour) but
 * leave unsized columns to the browser's auto layout so the table still fills
 * its container. Column virtualization needs every column to have a concrete
 * width.
 */
export function getWidthStyle<TData extends RowData>(
  column: DataTableColumn<TData, unknown>,
  table: DataTableInstance<TData>
): CSSProperties {
  const { enableColumnResizing, enableColumnVirtualization } = dt(table)
  if (enableColumnResizing) return getColumnWidthStyle(column.id)
  if (enableColumnVirtualization || column.columnDef.size != null) {
    const size = column.getSize()
    return { width: size, minWidth: size }
  }
  return {}
}

const DRAG_VARS = ["dx", "ms", "z", "op"] as const

/**
 * The style that lets a column's body, filter and footer cells follow its
 * header while it is dragged: the header writes its offset into CSS
 * variables on the scroll surface (see {@link setColumnDragVars}), so a drag
 * moves the whole column without re-rendering a row. `baseZIndex` keeps a
 * pinned cell's stacking when no drag is running.
 */
export function getColumnDragStyle(
  columnId: string,
  baseZIndex?: number
): CSSProperties {
  const id = cssVarId(columnId)
  return {
    translate: `var(--col-${id}-dx, 0px) 0`,
    transition: `translate var(--col-${id}-ms, 0ms) ease`,
    zIndex: `var(--col-${id}-z, ${baseZIndex ?? "auto"})` as never,
    opacity: `var(--col-${id}-op, 1)` as never,
  }
}

/**
 * Writes a column's drag offset onto the scroll surface for its cells, or
 * clears it (offset 0 and not dragging), in which case the cells snap back
 * with no animation.
 */
export function setColumnDragVars(
  surface: HTMLElement,
  columnId: string,
  offsetX: number,
  dragging: boolean,
  animate: boolean
) {
  const id = cssVarId(columnId)
  if (offsetX === 0 && !dragging) {
    for (const key of DRAG_VARS)
      surface.style.removeProperty(`--col-${id}-${key}`)
    return
  }
  surface.style.setProperty(`--col-${id}-dx`, `${offsetX}px`)
  surface.style.setProperty(
    `--col-${id}-ms`,
    dragging || !animate ? "0ms" : "200ms"
  )
  if (dragging) {
    surface.style.setProperty(`--col-${id}-z`, "30")
    surface.style.setProperty(`--col-${id}-op`, "0.85")
  } else {
    surface.style.removeProperty(`--col-${id}-z`)
    surface.style.removeProperty(`--col-${id}-op`)
  }
}
